quests[26761] = { id = 26761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bedrohung für das Königreich", description = "Es besteht kein Zweifel, dass die Defias eine ernsthafte Bedrohung für das Königreich darstellen, aber wir können nicht einfach so deren Versteck betreten und hoffen, dass sich alles zum Guten wendet. Nein, ein Angriff auf die Defias erfordert Zeit und Planung. Überlasst die Logistik mir. Unser Königreich hat auch noch andere Sorgen, gegen die umgehend etwas unternommen werden muss!\n\nReist nach Osten, über Elwynn ins Rotkammgebirge und meldet Euch bei Magistrat Solomon in Seenhain. Ich lasse nach Euch schicken, wenn wir bereit sind, die Defias anzugreifen.", sourceObjective = "Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.", completion = "Ich habe schon gehört, dass die Defias wieder auf den Plan getreten sind. Schreckliche Neuigkeiten. Ich wünschte nur, ich hätte bessere zu berichten, aber so wie es aussieht, wird Seenhain angegriffen! Wir verlieren an allen Ecken und Enden Leute. Unsere eigenen Wachen sind viel zu weit verstreut, um mit der Situation fertig zu werden. Wir brauchen einen Helden, der sich der Sache annimmt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26762] = { id = 26762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reaktiviert die Konstrukte", description = "Wir haben eine ganze Reihe unserer Kriegskonstrukte gen Norden nach Nadelfelsbruch geschickt, aber keines ist je zurückgekehrt. Wir wissen, dass die Mystiker der Steintroggs dafür verantwortlich sind.\n\nWir befürchten nun, dass die Mystiker die Kontrolle übernehmen und unsere Konstrukte gegen uns verwenden werden, so wie sie es mit den Fungusgiganten getan haben.\n\n{name}, betretet die Stadt der Steintroggs und reaktiviert die Konstrukte.", sourceObjective = "Reaktiviert 5 deaktivierte Kriegskonstrukte.", completion = "Das war wirklich gute Arbeit, {name}.\n\nUnsere Konstrukte funktionieren wieder und stehen hinter den feindlichen Linien. Es ist nur noch eine Frage der Zeit, bis uns der Durchbruch und damit die Rettung des Steinvaters gelingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26763] = { id = 26763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company-Bergbau", description = "Um diesen Topf zu reparieren, werde ich Reagenzien brauchen. Und um die zu bekommen, werdet Ihr ein ganz klein bisschen töten müssen. Ich hoffe, das stört Euch nicht.\n\nDiese lästigen Geologen der Venture Company haben einige gerommelte Kristalle gesammelt, die für meine Zwecke genügen würden. Ihr findet sie rund um ihr Basislager im Osten, auf der anderen Seite des Nazferitisees.\n\nIst mir egal, was Ihr tun müsst, um sie zu bekommen.", sourceObjective = "Besorgt 5 gerommelte Kristalle von Angehörigen der Venture Co. beim Nazferitisee.", progress = "Habt Ihr die Kristalle?", completion = "Die sind genau richtig. Einen Moment bitte.\n\n<Krazek wirft die Steine in den Kochtopf und schüttelt sie ein wenig.>\n\nAlles repariert!", sourceObjectiveStatus = "unverified-source-field" }
quests[26764] = { id = 26764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moralischer Bankrott", description = "Euch ist vielleicht aufgefallen, dass die Venture Company den Wald rund um ihr Basislager im Osten komplett gerodet hat. Ihr Vorarbeiter wittert Profit, deshalb hat er Druiden versklavt, die er zwingt, den Wald neu wachsen zu lassen, damit er ihn wieder abholzen kann!\n\nIch persönlich finde das abscheulich, nicht nur, weil ich nicht als erster auf die Idee gekommen bin.\n\nBefreit einige dieser Druiden aus ihrer Gefangenschaft. Sie werden Euch bestimmt dankbar sein.", sourceObjective = "Befreit 3 versklavte Druiden aus dem Basislager der Venture Co.", sourceObjectiveStatus = "unverified-source-field" }
quests[26765] = { id = 26765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Korporal Kaleb zurück", description = "So, dieser Kessel ist repariert. Ich habe sogar eine zweite Dampfpfeife eingebaut. Und seht! Am Boden gibt es einen neuen Zerhacker, der sogar durch Beinknochen schneidet!\n\nJa, ja, Krazeks Spezialtopf stellt Köche zu 100% zufrieden! Ich bin sicher, dass er dem Besitzer gefallen wird.", sourceObjective = "Bringt Krazeks reparierten Topf zu Korporal Kaleb im Rebellenlager im Nördlichen Schlingendorntal.", progress = "Hallo, {name}. Hat der Goblin Krazek meinen Topf repariert??", completion = "Er funktioniert wieder! Das ist toll! Jetzt kann ich mit dem Abendessen anfangen! Vielen Dank, {name}.\n\nIch hoffe, dass Krazek Euch nicht zu viele Unannehmlichkeiten bereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26766] = { id = 26766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großes Ziel, großer Köder", description = "Wir haben nur eine Chance, Abyssion zu fangen, {name}. Wir müssen sie gut nutzen.\n\nWir testen die Falle am größten Steindrachen am Alabasterschelf.\n\nUm die Steinmatriarchin anzulocken, benötigen wir ausreichende Köder.\n\nNehmt dieses Messer und besorgt Euch 5 Basiliskenfleischstücke. Das sollte sogar für ihren Appetit genügen.", sourceObjective = "Benutzt Mylras Messer, um 5 Basiliskenfleischstücke aus toten Kristallrückenbasilisken zu schneiden.", progress = "Habt Ihr das Fleisch besorgt?", completion = "Das sollte ausreichen, um die Bestie anzulocken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26767] = { id = 26767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Questerstellung", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als nächstes zu tun ist.", sourceObjective = "Erstellt eine Schnitzeljagdquest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26768] = { id = 26768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenfangen leicht gemacht", description = "Das Fragment von einem Drachen bewachen zu lassen, war ein cleverer Schachzug. Sie können es immer an einen anderen Ort bringen, wenn wir uns ihm nähern.\n\nAbyssion zu fangen wird sehr schwer, aber ich habe einen guten Plan.\n\nDer Schattenhammer benutzt magische Fallen, um die Steindrachen an den Boden zu fesseln, während sie ihnen ihre Energie rauben.\n\nWenn wir an eine solche Falle kämen, könnten wir den Zwielichtdrachen vielleicht lange genug festhalten.\n\nGeht nach Osten zum Alabasterschelf und besorgt Euch eine Falle.", sourceObjective = "Besorgt Euch eine Drachenschlinge von den Zwielichtdrachenjägern.", progress = "Wenn die Schlingen gut genug für Steindrachen sind, funktionieren sie vielleicht auch bei Abyssion.", completion = "Lasst uns schauen, ob die Schlinge auch etwas Größeres als einen Drachen festhalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26769] = { id = 26769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Flussfahrt", description = "Genießt Euren Anteil an der Beute, {name}!\n\nIch teile nicht gern, aber Geschäft ist Geschäft. Und diesem Betrüger Düsentopf stehen 10% dieses Schatzes zu. Könntet Ihr das zu ihm in seinem Außenposten nördlich von hier bringen?\n\nEr leitet eine kleine Forschungsstation stromaufwärts am Fluss. Verlasst die Stadt in Richtung Nordosten und sucht Horton Hornbläser auf. Er wird Euch kostenlos auf einem seiner Flussschiffe mitnehmen. Sagt ihm, ich hätte Euch geschickt!", sourceObjective = "Geht an Bord von Horton Hornbläsers Flussschiff nordöstlich von Ratschet und macht eine Flussfahrt zu Düsentopfs Außenposten.", progress = "Willkommen, {class}. Seid Ihr gerade mit dem Schiff aus Ratschet gekommen? Gibt es Neuigkeiten?", completion = "<Düsentopf entreißt Euch den Beutel mit Edelsteinen.>\n\nGazlowe nennt das 10%? Sagt ihm, dass ich sie wiegen werde!\n\nWill er etwa, dass ich Euch ein Lieferhonorar zahle? Schon gut. Nehmt Euch was von der Beute!", sourceObjectiveStatus = "unverified-source-field" }
quests[26770] = { id = 26770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystische Meister", description = "Die Mystiker der Nadelfelsen haben die Kontrolle über die Fungusgiganten, die tief unten in ihrer Schlucht entstanden sind, übernommen. Jetzt wollen sie auch noch unsere Kriegskonstrukte übernehmen.\n\nGeht Richtung Norden nach Nadelfelsbruch und unternehmt etwas dagegen. Deswegen seid Ihr doch hier, oder?", sourceObjective = "Tötet 5 Mystiker der Nadelfelsen.", completion = "Ein paar Steintroggs weniger ist nie schlecht. Ich freue mich, dass Ihr doch ein anständiger {class} seid.\n\nSchon bald werden wir erfahren, wo genau mein Vater gefangen gehalten wird. Hoffentlich überlebt Ihr so lange.", sourceObjectiveStatus = "unverified-source-field" }
quests[26771] = { id = 26771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallenprobe", description = "Legt nun die Falle für die Matriarchin aus.\n\nGeht zum westlichen Ende des Alabasterschelfs und platziert die Falle mit dem Basiliskenfleisch in die Mitte des Futterplatzes.", sourceObjective = "Legt die Falle mit dem Fleisch am westlichen Ende des Alabasterschelfs aus.", completion = "Gut gemacht, {name}. Ich hoffe, dass die Falle bei Abyssion ebenso gut funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26772] = { id = 26772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankensicht", description = "Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.\n\nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.\n\nIhr habt Euch angefreundet mit Raptor: Ohgan'aka: Tochter von Ohgan.\n\nUm Freundschaft zu stärken, brauchen wir Federn.\n\nGeht nach Nordosten und Ihr werdet Federn finden, ja.", sourceObjective = "Erbeutet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.", progress = "Raptor namens Ohgan'aka, immer noch Eure Freundin.", completion = "Ihr bringt Federn, ja.\n\nIhr könnt Anweisungen befolgen, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26773] = { id = 26773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht Raptor", description = "Wir haben Federn, ja.\n\nWir haben <den/die> {class}, ja.\n\nSprecht mit Priesterin, wenn bereit.", sourceObjective = "Sprecht mit Priesterin Thaalia in Fort Livingston, um am Ritual der Gedankensicht teilzunehmen.", completion = "Was hat Priesterin Euch gesagt?\n\nDer Raptor ist Tochter von Ohgan, Erbe von Mandokirs Thron.\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26774] = { id = 26774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankenkontrolle", description = "Gedankensicht nicht genug, nein.\n\nGedankenkontrolle viel mächtigere Magie, ja.\n\nMächtige Magie braucht mächtige Reagenzien und Trollgehirn ist mächtige Reagenz.\n\nBraddok in Zul'Mamwe, sehr klug, ja.\n\nGeht nach Süden und seht Euch an großes Gehirn von Braddok.", sourceObjective = "Erbeutet Braddoks Riesengehirn von Braddok in Zul'Mamwe.", progress = "Riesengroße Zauber brauchen riesengroße Gehirne, ja.", completion = "Wartet, nächster Teil ist schwierig, ja.\n\nViele Möglichkeiten für Fehlschlag, ja.\n\nAber {name} und {name}'aka werden wieder zusammenkommen... ja, werden sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26775] = { id = 26775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid Raptor", description = "Gedankenkontrolle sehr mächtig, ja.\n\nMit Glück könnt Ihr Ohgan'aka helfen, aus Zul'Gurub zu fliehen.\n\nDann wird Ohgan'aka wieder {name}'aka werden!\n\nSprecht mit Priesterin, ja, und helft {name}'aka bei Flucht.", sourceObjective = "Sprecht mit Priesterin Thaalia und helft dem gefangenen Schmetterschwanzjungen aus Zul'Gurub zu fliehen.", completion = "Sehr schade, ja.\n\nDies ist der Wille der Geister, ja.\n\nWenn Ihr stärker seid, werdet Ihr vielleicht nach Zul'Gurub gehen und deine {name}'aka von Mandokir zurückholen, ja.\n\nDoch erst einmal gibt Euch Priesterin dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26776] = { id = 26776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghaliri", description = "Priesterin spricht Gemeinsprache nicht gut, nein.\n\nVielleicht redet besser mit Ghaliri, vor diesem Zelt.\n\nSagt ihm, was Ihr in Zul'Gurub gesehen, ja.", sourceObjective = "Kehrt zu Ghaliri in Fort Livingston im Nördlichen Schlingendorntal zurück.", completion = "<Ihr erklärt Ghaliri, was bisher geschehen ist.>\n\nAnscheinend hat Jin'do überlebt und ruft seine Brüder zusammen, um Hakkar noch einmal in diese Welt zu holen. Es war gut, dass Ihr zu mir gekommen seid.\n\nIm Moment können wir nur abwarten und beobachten. Jin'do ist schwach. Wir sollten ihn niederstrecken, aber ich muss Rastakhans Entscheidung abwarten, bevor ich den Befehl dazu geben kann. Bis dahin müsst Ihr und Euer Raptor ausharren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26777] = { id = 26777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beruhigt die Geister", description = "Dies ist ein tragisches Land mit einer Geschichte voller Gewalt und Verzweiflung. Viele Tote streifen in ihren Körpern durch das Land, aber manche sind nur verlorene Seelen, die verwirrt umherirren.\n\nSie verdienen Trost.\n\nViele dieser Seelen versammeln sich im Süden in Addles Siedlung und erscheinen Reisenden. Nehmt diesen Schwenker mit heiligem Weihrauch. Schwenkt ihn vor den verlorenen Seelen. Sein sanfter Duft wird ihnen Frieden bringen.", sourceObjective = "Beruhigt 5 verlorene Geister in Addles Siedlung.", completion = "Ihr habt denen Frieden gebracht, die nur Leid kannten, {name}. Seid stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26778] = { id = 26778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schreie der Toten", description = "Könnt Ihr sie hören, {name}? Es sind so viele. Sie wandern an ihren Gräbern entlang, stolpern auf verwesenden Gliedmaßen über den kalten Boden.\n\nDie Toten schreien in der Stille. Sie leiden in ihrem eigenen Fleisch und wurden aus ihrem Schlaf gerissen! Jede Nacht gehe ich auf den Friedhof, um mehr von ihnen Frieden zu bringen, aber es sind nie genug.\n\nHelft mir, {name}. Erlöst die Ghule, die über den Friedhof von Rabenflucht ziehen, von ihrem Leid. Tötet so viele Ihr könnt.", sourceObjective = "Tötet 20 beliebige Ghule auf dem Friedhof von Rabenflucht.", completion = "Doch die Schreie sind nicht mehr so laut. Möge das Licht Euch segnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26779] = { id = 26779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mambo in Zul'Mamwe", description = "Das ganze Trollreich schämt sich für die Schädelspalter. Ihr lächerliches Gezanke mit den Blutskalpen hat das Nördliche Schlingendorntal entzweit. Während Stämme wie die Dunkelspeere und die Zandalari ein gutes Leben führen, kämpfen die Schädelspalter um Ruinen.\n\nMan hat mir erlaubt, Söldner zu belohnen, die gewillt sind, die Schädelspalter zu bestrafen. Ich fordere Euch und jeden, den Ihr kennt, auf, nach Zul'Mamwe im Osten zu reisen und diesen abtrünnigen Stamm zu vernichten.", sourceObjective = "Tötet 16 Schädelspaltertrolle im Inneren von Zul'Mamwe.", completion = "Hier ist, wie versprochen, Eure Belohnung.. Ihr erfüllt die Trollnation mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26780] = { id = 26780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn es Nacht wird im Dschungel", description = "Die Nächte sind im Schlingendorntal besonders schön. Der Himmel ist voller Sterne und das Mondlicht dringt durch diese Blätter hier. Die ganze Nacht könnte ich den Himmel betrachten.\n\nLeider stören die Trolle in den Ruinen von Zul'Mamwe meine astronomischen Studien. Tag und Nacht brennen ihre Kohlenpfannen. Sie berauben mich der Dunkelheit, die ich brauche.\n\nBitte geht nach Zul'Mamwe östlich von hier, {name} und löscht sie.", sourceObjective = "Löscht 8 Kohlenpfannen von Zul'Mamwe in Zul'Mamwe im Nördlichen Schlingendorntal.", completion = "Ich sehe den Unterschied bereits deutlich. Ich kann die Nacht kaum erwarten. Dann kann ich endlich wieder meine Beobachtungen aufnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26781] = { id = 26781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gedankenauge", description = "Einer der zahlreichen Schätze dieses Tals befindet sich ganz in der Nähe, auf UNSERER Seite des riesigen Wirbelstroms. Ein Ogermagier auf dem Ogerhügel der Mosh'Ogg, nordöstlich von hier, besitzt es. Sein Name ist Mai'Zoth. Ich habe gehört, er sei boshaft und seine Magie stark.\n\nWenn er das Gedankenauge besitzen sollte, wird seine Magie noch stärker sein.\n\nBisher ist es mir nicht gelungen, nahe genug an ihn heranzukommen, um es ihm abzunehmen. Würdet Ihr es versuchen?", sourceObjective = "Nehmt Mai'Zoth das Gedankenauge ab.", progress = "Habt Ihr das Auge?", completion = "Ihr habt das Auge geholt! Eure Macht ist der Stoff, aus dem Legenden sind, {name}!\n\nDabei dachten mein Bruder und meine Schwester, wir würden nichts wertvolles in diesem Tal finden. Hah! Und ich fange erst an!", sourceObjectiveStatus = "unverified-source-field" }
quests[26782] = { id = 26782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass <ein/eine:r> {race}, <ein/eine:c> {class}, wie ich höre, dort oben entschlüsselt hat, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?\n\nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh'Ogg im Nordosten entdeckt habe.\n\nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?", sourceObjective = "Erbeutet die Schatzkiste der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", progress = "Wieso finden ausgerechnet OGER immer wertvolle Artefakte?", completion = "<Wulfred wirft einen Blick in den Kasten.>\n\nDamit... damit hatte ich nicht gerechnet. Ich dachte, es wäre ein... ein... \n\n<Seine Augen werden glasig.>\n\nÄhem! Entschuldigt. Ich weiß nicht, was über mich gekommen ist. Ich schicke das nach Süden, zur Grabungsstätte der Forscherliga am Kap. Vielleicht wissen sie etwas damit anzufangen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26783] = { id = 26783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass <ein/eine> {race}, <ein/eine:c> {class}, wie ich höre, dort oben entschlüsselt haben, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?\n\nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh'Ogg im Nordosten entdeckt habe.\n\nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?", sourceObjective = "Erbeutet die Schatzkiste der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", progress = "Wieso finden ausgerechnet OGER immer wertvolle Artefakte?", completion = "<Wulfred wirft einen Blick in den Kasten.>\n\nDamit... damit hatte ich nicht gerechnet. Ich dachte, es wäre ein... ein... \n\n<Seine Augen werden glasig.>\n\nÄhem! Entschuldigt. Ich weiß nicht, was über mich gekommen ist. Ich schicke das nach Süden, zur Grabungsstäte der Forscherliga am Kap. Vielleicht wissen sie etwas damit anzufangen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26784] = { id = 26784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammiges Wasser", description = "Die Elementarkräfte sind stark hier im Hochland, {name}. Deshalb hat der Schattenhammer hier seine Festung errichtet.\n\nIn den richtigen Händen kann diese Energie für etwas Produktives genutzt werden... zum Beispiel für ein Portal nach Orgrimmar.\n\nNordwestlich von hier, an der Mündung des Verralls sind Wasserelementare durch die Taten unserer Feinde flussaufwärts aufgeschreckt worden. Zerstört sie und sammelt 5 Strudelkerne. Ihr werdet nicht nur den Fluss beruhigen, sondern auch unser Portal mit Energie versorgen.", sourceObjective = "Tötet schlammige Wasserelementare und sammelt 5 Strudelkerne.", progress = "Ich hoffe, die Kämpfe im Fluss waren nicht allzu gefährlich.", completion = "Die sind genau richtig! Die unruhigen Wasser dieses aufgewühlten Flusses werden jetzt so viel mehr tun, als nur Schlick oder Stein zu bewegen ... Sie werden Euch von einem Kontinent zum anderen bewegen.\n\nErledigt Eure restlichen Geschäfte hier in Drachenmal. Dann sollten wir fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26785] = { id = 26785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitglied der Meute", description = "Ich habe immer versucht, mein wahres Ich vor den Einwohnern Dunkelhains zu verbergen... Sie scheinen Worgen nicht zu mögen. Es gibt allerdings außerhalb der Stadt noch mehr von uns.\n\nMeine Begleiter, mit denen ich zuerst hier angereist bin, durchsuchen die Wälder nach wilden Worgen. Sie glauben, dass einige von ihnen - die mit den verräterischen Zeichen - wieder zur Vernunft gebracht werden können.\n\nIch bin noch nicht soweit, mich ihnen wieder anzuschließen. Bitte lasst Lehrling Fess an der Kreuzung westlich der Stadt wissen, dass ich noch eine Weile länger in Dunkelhain verweilen werde.", sourceObjective = "Sprecht mit Lehrling Fess an der Kreuzung westlich von Dunkelhain im Dämmerwald.", completion = "Tobias hält sich immer noch in der Stadt auf?\n\nMeister Harris hat ihn davor gewarnt, dem Schicksal seines Bruders weiter nachzugehen. Wir haben schließlich alle ein neues Leben angefangen. Aber es ist schwer, die Vergangenheit hinter sich zu lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26786] = { id = 26786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Landungspunkt sichern", description = "Etwas bereitet mir Kopfzerbrechen, {name}. Die Zwielichtdrachen wussten genau, wo und wann sie unsere Luftflotte angreifen mussten. Man könnte glauben, dass sie unsere Pläne kennen.\n\nZwielichtspione verstecken sich mitten unter uns!\n\nIch werde mit einem der verbliebenen Schiffe nach Orgrimmar zurückkehren und dann werden Köpfe rollen. Ihr müsst hier bleiben. Ich brauche Euch hier, um diese Frontlinie zu sichern. Die Schamanen des Drachenmals sind mächtig. Ich habe sie darum gebeten, ein Portal nach Orgrimmar zu öffnen. Und ich brauche Eure Hilfe.\n\nAlso. Fangt an, zu helfen!", sourceObjective = "Sprecht mit Artesh im Hafen des Drachenmals im Schattenhochland.", completion = "Euer Kriegshäuptling ist entschlussfreudig, {name}. Er setzt Dinge in die Tat um. Ich mag ihn.\n\nLasst uns über das Portal sprechen, das er möchte!", sourceObjectiveStatus = "unverified-source-field" }
quests[26787] = { id = 26787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärendienst", description = "Ich habe Angst, dass ... nun ja, ich habe einfach nur Angst. Außerdem tut es mir leid, dass ich um einen weiteren Gefallen bitten muss.\n\nMeister Harris benötigt Gehirne. Bärengehirne. Offenbar sind sie Teil des Serums - oder ein gleichwertiger Ersatz.\n\nEs gibt viele Schwarzbären in den Wäldern im Westen und entlang des Flussufers, aber... Ich kann das nicht! Ich habe sogar mit einem Gewehr viel zu viel Angst, um dort hinauszugehen und diesen riesigen Ungeheuern gegenüberzutreten. Bitte, lasst mich Euch bezahlen, damit Ihr mir einige bringt!", sourceObjective = "Sammelt 8 Gehirne von Schwarzbären", progress = "Habt Ihr sie bekommen? Habt Ihr sie?", completion = "Danke! Oh, danke. Ich hätte nie gedacht, dass ich einmal so glücklich sein werde, diese Gehirne zu riechen. Jetzt, da ich sie nicht selber holen musste, bin ich es!\n\nHier ist Eure Belohnung, wie versprochen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26788] = { id = 26788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Sieg untermauern", description = "Unsere Allianz mit dem Drachenmalklan ist unter Dach und Fach, aber dieser Hafen ist für Kämpfe immer noch ungeeignet. Diese hauchdünnen Holzwände sind des Kriegshäuptlings unwürdig.\n\nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, wie sie es im Verrall getan haben, entsteht ein seltsamer Schlamm. Er lässt sich problemlos verstreichen und wenn er trocknet, ist er härter als der härteste Stein. Er ist der perfekte Mörtel für große Bauvorhaben.\n\nGeht zur Flussmündung nordwestlich von hier und sammelt Verrallschlamm ein. Selbst eine kleine Menge wird lange reichen.", sourceObjective = "Sammelt 10 Haufen Verrallschlamm.", progress = "Habt Ihr den Schlamm? Der Bau der neuen Wände hat bereits begonnen!", completion = "<Ornak lässt den Schlamm von seinen Fingerspitzen tropfen.>\n\nDas ist genau das richtige Zeug! Ich werde es sofort mit Kies und Wasser vermischen und verdünnen. Nur einige Handvoll hiervon können den Zement für einen ganzen Steinturm aufbessern.\n\nWir haben große Pläne für diesen Hafen, {name}, Ihr werdet schon sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26789] = { id = 26789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt im Walde", description = "{name}, wir haben ein Problem! Ich habe den Dämonenhund Magmadar auf dieser Lichtung aufgespürt, aber als wir uns ausruhten, hat eine Koboldbande unsere Kampfäxte gestohlen! Ihr müsst sie zurückholen, damit Magmadar uns nicht unvorbereitet erwischt! Beeilt Euch, er kann jeden Moment aufwachen!", sourceObjective = "Tötet 5 Test-Kobolde", sourceObjectiveStatus = "unverified-source-field" }
quests[26791] = { id = 26791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Pilze aus dem Boden", description = "Die Mystiker der Steintroggs erschaffen diese Fungusmissgeburten aus den Riesenpilzen im Norden.\n\nIch möchte, dass Ihr einen Kriegswächter mitnehmt, damit er Euch bei den Riesen und den Steintroggs hilft. Macht Euch auf den Weg zu den Riesenpilzen und zielt auf sie. Ich und meine Geomanten werden sie in Grund und Boden stampfen, noch bevor die Mystiker ihr Ritual vollenden.", sourceObjective = "Interagiert mit einem Kriegswächter und benutzt ihn, um 5 Riesenpilze zu vernichten.", completion = "Jetzt haben sie keine dieser Pilzriesen mehr, die sie gegen uns einsetzen könnten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26792] = { id = 26792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungusmissgeburten", description = "Schnappt Euch einen Kriegswächter und vernichtet die Fungusmissgeburten, während Ihr da draußen seid.", sourceObjective = "Tötet 5 Fungusmissgeburten.", completion = "Ich danke Euch, {name}. Vor der Zerstörung der Weltensäule kannten wir derartige Probleme in Tiefenheim nicht.\n\nEuer Irdener Ring muss den Schaden beseitigen, bevor es zu spät ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26793] = { id = 26793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verwitterte Grab", description = "Auf dem Schild an dem verwitterten Grab steht nur:\n\nMORGAN LADIMORE\n\n<Bei genauerer Untersuchung bemerkt Ihr, dass die Erde auf dem Grab vor Kurzem aufgewühlt wurde. Ein großer Teil der Erde scheint verlagert worden zu sein...>", sourceObjective = "Sprecht mit Sirra Von'Indi in Dunkelhain.", completion = "Morgan Ladimore?\n\nAh, ja, natürlich. Das ist eine lange und traurige Geschichte. Ich kannte ihn, nun ja, bevor er in den Krieg zog. Damals sah ich ihn zum letzten Mal. Er war ein nobler und guter Mann, aber es nahm ein schlimmes Ende für ihn.\n\nMoment, ich müsste hier etwas haben, das Euch die Geschichte näher bringen kann als meine lückenhaften Erinnerungen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26794] = { id = 26794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<Er durchsucht die Regale und zieht ein ledergebundenes Buch hervor.>\n\nWenn Ihr mehr wissen möchtet, solltet Ihr Althea fragen. Sie hat sich in letzter Zeit mit den... Ärgernissen, die ihn betreffen, beschäftigt.", sourceObjective = "Sprecht mit Kommandantin Althea Schwarzhaupt in Dunkelhain.", completion = "Morgan Ladimore? Nie gehört...\n\nOh, Ihr meint Mor'Ladim! Dann kennt Ihr die Geschichte wohl noch nicht.\n\nIch erzähle Euch die Kurzfassung. Ein mächtiges untotes Wesen, das sich Mor'Ladim nennt, ist im Dämmerwald gesehen worden. Soweit wir wissen, handelt es sich dabei um den untoten Körper von Morgan Ladimore, von dem Ihr anscheinend gehört habt. Er bereitet uns jede Menge Probleme, greift Wachen auf Patrouille an und bringt Leute um.\n\n<Sie mustert Euch.>\n\nIhr wirkt recht fähig, vielleicht könnt Ihr ihm ja Frieden bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26795] = { id = 26795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "Wie ich von meinen Spähern höre, irrt Mor'Ladim auf merkwürdig verschlungenen Pfaden durch den Dämmerwald. Sein Weg führt ihn dabei über den Friedhof. Wir haben ihn hinter dem Haus auf dem Hügel begraben. Wisst Ihr, wo das ist?\n\nIch kann leider nichts tun, um Euch zu helfen, aber ich wünsche Euch viel Glück.", sourceObjective = "Tötet Mor'Ladim und bringt seinen Schädel zu Kommandantin Althea Schwarzhaupt in Dunkelhain.", progress = "Ich mache Euch keinen Vorwurf, wenn Ihr Schwierigkeiten mit ihm habt, {name}. Einige unserer stärksten Behüter sind Mor'Ladim zum Opfer gefallen.", completion = "Ihr habt ihn getötet? Das ist eine großartige Leistung, {name}! Im Namen der Einwohner Dunkelhains und der Nachtwache, danke ich Euch.\n\nAh... da wäre allerdings noch eine Kleinigkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[26796] = { id = 26796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die überlebende Tochter", description = "Ich hätte Euch dies schon früher mitteilen müssen...\n\nWie soll ich sagen...\n\nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.", sourceObjective = "Sprecht mit Behüterin Sarah Ladimore in Dunkelhain.", completion = "Ja? Mein Vater...\n\n<Sie senkt den Blick.>\n\nIch wünschte... ich hätte etwas für ihn tun können... Hätte ich nur mit ihm gesprochen, bevor er...", sourceObjectiveStatus = "unverified-source-field" }
quests[26797] = { id = 26797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Liebe einer Tochter", description = "Hier, nehmt das und legt es auf sein Grab. Vielleicht... weiß er irgendwie, dass es mir gut geht und dass keiner von uns ihn dafür verantwortlich macht, was geschehen ist.\n\n<In ihren Augen stehen Tränen. Sie streift einen Ring von einem Finger der rechten Hand ab und drückt ihn Euch in die Hand.>\n\nUnd... danke, {name}.", sourceObjective = "Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.", progress = "Lasst mich in Ruhe...", completion = "<Eine geisterhafte Stimme erklingt im Wind...>\n\nIst das...? Sarah? Kann es sein, dass sie noch lebt? Mir fällt ein Stein vom Herzen...\n\n{name}. Nehmt mein Schwert Archeus. Jetzt, da meine Seele sich zur Ruhe begibt, benötige ich es nicht länger. Es wurde geschmiedet, um Gutes zu tun. Ich habe mich unwürdig erwiesen, es zu führen. Doch vielleicht könnt Ihr das Licht damit weitertragen.\n\nLys, meine Geliebte...", sourceObjectiveStatus = "unverified-source-field" }
quests[26798] = { id = 26798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshäuptling wird zufrieden sein", description = "Das Portal ist fertig!\n\nEs ist noch nicht stark genug, um eine ganze Armee zu transportieren, aber wir können die Verbindung lange genug aufrecht erhalten, um wichtige Personen in beide Richtungen hindurchschreiten zu lassen.\n\nDer Kriegshäuptling will bestimmt über Eure Fortschritte hier informiert werden. Geht durch das Portal nach Orgrimmar und überbringt die Neuigkeiten Garrosh Höllschrei.", sourceObjective = "Benutzt das Portal im Hafen des Drachenmals, um nach Orgrimmar zu gelangen. Meldet Euch dort bei Garrosh Höllschrei.", completion = "{class}, Ihr seid von den Drachenmalorcs zurückgekehrt. Ich nehme also an, dass das Portal funktioniert? Gut.\n\nBevor Ihr wieder an Eure Arbeit dorthin zurückkehrt, gilt es, hier in Orgrimmar noch ein schmutziges Geschäft zu bereinigen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26799] = { id = 26799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nicht gerettet werden konnten", description = "Die Val'kyr erwecken jeden Tag hunderte von Leichen. Agatha hat Euch vor nur wenigen Momenten erweckt. Aber nicht alle haben Euer Glück.\n\nEinige behalten ihren freien Willen, leben aber in ewiger Angst und Verwirrung. Sie laufen normalerweise in die Wälder und schrecken vor ihrem eigenen Anblick zurück.\n\nAndere werden völlig wahnsinnig und ziehen ziellos umher. Sie werden oft gewalttätig und müssen zerstört werden.\n\nDas ist Eure Aufgabe, {name}. Zerstört sie, auch wenn sie einst unsere Brüder und Schwestern waren.", sourceObjective = "Tötet 6 hirnlose Zombies.", completion = "Nicht einmal die Macht der Val'kyr reichte aus, um diese Kreaturen zu retten. Sie waren von Anfang an verdammt.\n\nIch habe Euch etwas Ausrüstung besorgt, {name}. Es ist nicht viel, aber es wird helfen. Bitte, sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26800] = { id = 26800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung", description = "Wir haben Leichen aus dem Silberwald, aus dem Hügelland... ach, von überall herbringen lassen, wo wir sie bekommen konnten. Wir können es uns jedoch nicht leisten, die Leichen zu ignorieren, die direkt vor unserer Tür liegen.\n\nDie letzten Überbleibsel des Scharlachroten Kreuzzuges treiben sich hier in Tirisfal herum. Wir haben sie zwar aus Todesend vertreiben können, aber mehrere ihrer Leichen liegen um die Gebäude im Norden und Osten herum.\n\nGeht und findet sie... und nehmt diesen Darnell mit. Er sieht stark genug aus, um ein paar Leichen tragen zu können.", sourceObjective = "Durchsucht Todesend und die Umgebung nach 6 Leichnamen der Scharlachroten, dann zeigt auf sie, damit Darnell sie einsammelt.", completion = "Gute Arbeit, {name}, ich wusste, dass Ihr nicht völlig nutzlos seid. Hier, nehmt Euch etwas hiervon. Wir Todeswachen haben solches Zeug stapelweise herumliegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26801] = { id = 26801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel an unseren Grenzen", description = "Wenn Ihr den Verlassenen nützlich sein wollt, müsst Ihr lernen, wie man kämpft. Und es gibt keine besseren Ziele als die Geißeldiener, die uns immer noch belästigen.\n\nDie elenden Ghule und klappernden Skelette die im Norden und Osten herumlaufen, sind ehemalige Kämpfer der gefallenen Geißel. Sie sollten für <einen neuen/eine neue> {class} wie Euch eine ausgewogene Herausforderung bieten.\n\nTrödelt nicht herum - sprecht erneut mit mir, wenn Ihr fertig seid.", sourceObjective = "Tötet 8 Untote außerhalb von Todesend. Ihr könnt sowohl elende Ghule als auch klappernde Skelette töten.", completion = "Eure Stärke wächst, {name}. Ich habe solche wie Euch schon gesehen. Ihr werdet Todesend verlassen und Größeres in Angriff nehmen, ehe Ihr Euch verseht. Vergesst nur nicht, wo Ihr einmal angefangen habt.\n \nEs liegt noch viel Arbeit vor Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26802] = { id = 26802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verdammten", description = "Zuerst... schaut mal Eure Rüstung an. Ihr seht ganz zerlumpt aus, {class}.\n\nWenn Ihr in einem Stück bleiben wollt - und das wollt Ihr ganz sicher - kann ich vielleicht helfen. Wenn Ihr mir Pfoten und Flügel von den Wölfen und Fledermäusen in der Nähe bringt, finde ich Euch vielleicht etwas Rüstung. Ihr findet diese Kreaturen nördlich und westlich von hier.", sourceObjective = "Besorgt 4 Aasfressertatzen und 4 Nachtsaugerflügel.", progress = "Bemüht Euch, unverletzt zu bleiben, bis ich Euch irgendeine Rüstung besorgt habe.", completion = "Danke, {name}. Diese Rüstung sollte Euch etwas helfen.\n\nHoffentlich hilft sie Euch mehr als ihrem letzten Träger...", sourceObjectiveStatus = "unverified-source-field" }
quests[26803] = { id = 26803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Berichte", description = "Garrosh ist ungehobelt und spricht kaum ein Wort, aber er meint es gut. Bald wird er erkennen, welch wertvoller Verbündeter Euer Volk ist.\n\nIch warte auf Berichte zu den letzten Regungen der Allianz in Durotar, aber sie sind noch nicht eingetroffen. Würdet Ihr für mich nach Klingenhügel reisen und persönlich darum bitten? Am einfachsten gelangt Ihr mit einem Windreiter dorthin. Für eine kleine Gebühr leiht Doras, der Windreitermeister in Orgrimmar, Euch einen seiner Windreiter. Ihr findet ihn auf der Anhöhe nördlich des Tals der Stärke.", sourceObjective = "Sprecht mit Windreitermeister Doras in Orgrimmar.", completion = "Ihr müsst also schnell nach Klingenhügel? Kein Problem. Einer meiner Windreiter kann Euch im Handumdrehen dorthin bringen. Die Leihgebühr beträgt nur ein paar Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26804] = { id = 26804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Klingenhügel", description = "Wenn Ihr bereit seid, einen Windreiter nach Klingenhügel zu nehmen, sprecht mich einfach erneut an. Verschwendet keine Zeit, wenn Ihr angekommen seid, und meldet Euch sofort bei Gar'Thok. Er ist für die Berichte zu den aktuellen Aktivitäten der Allianz in Durotar verantwortlich.", sourceObjective = "Sprecht mit Doras, um einen Windreiterflug nach Klingenhügel zu erwerben. Sobald Ihr angekommen seid, sprecht mit Gar'Thok.", completion = "Etrigg hat Euch geschickt? Der Kriegshäuptling muss ja auf meine Berichte brennen! Ich hätte sie ihm schon lange geschickt, aber wir decken jeden Tag neue Einmarschpläne der Allianz in Durotar auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26805] = { id = 26805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Kap!", description = "Die Forscherliga entwickelt sich ständig weiter, {name}. Sie haben nicht nur Worgen wie mich aufgenommen, sondern sie haben auch ihre Suche nach Artefakten ausgeweitet. Einer unserer Besten, Bronwyn Hackschlag, hat im Süden ein Lager aufgeschlagen. Er glaubt, dass dort ein Gegenstand verborgen liegt, der von den Titanen stammt.\n\nBronwyn hat mich darum gebeten, einige Aufgaben hier im Norden zu übernehmen. Eine dieser Aufgaben ist es, mögliche Rekruten zu finden. Ihr scheint aus dem richtigen Holz geschnitzt zu sein. Sprecht mit Robert Rhodes, dem Flugmeister. Er wird dafür sorgen, dass Ihr dorthin gelangt. Auf Bronwyns Kosten.", sourceObjective = "Sprecht mit Robert Rhodes, um einen Flug zu der Grabungsstätte der Forscherliga am Schlingendornkap zu bekommen.", completion = "Wulfred hat einen guten Blick. Ihr werdet hier in meinem Lager schon zurechtkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26806] = { id = 26806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichte für Orgrimmar", description = "Etrigg muss sich mit dem Teil des Berichts zufriedengeben, den ich schon fertig habe. Sagt ihm, dass ich bald noch mehr schicke.\n\n<Gar'Thok reicht Euch einen Stapel unordentlich gefalteter Papiere.>\n\nDie hier sollten eigentlich die wichtigsten Details zum Anstieg der Allianztruppen in Nordwacht enthalten. Bitte sagt Etrigg, dass es mir leid tut und lasst ihn wissen, dass wir hier alle Hände voll zu tun hatten. Schließlich mussten wir Klingenhügel sichern. Wenn Ihr bereit seid, nach Orgrimmar zurückzukehren, sprecht einfach mit Burok und leiht Euch einen Windreiter.", sourceObjective = "Bringt Gar'Thoks Berichte zu Burok in Klingenhügel.", progress = "Seid Ihr bereit, nach Orgrimmar zurückzukehren?", completion = "Seid Ihr bereit, mit diesen Berichten nach Orgrimmar zurückzukehren? Ich kann sofort einen Flug für Euch arrangieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26807] = { id = 26807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Etrigg", description = "Da Ihr bereits mit Doras gesprochen habt, könnt Ihr einen Windreiter für den Rückflug nach Orgrimmar mieten. Jedes Mal, wenn Ihr in einer neuen Stadt ankommt, solltet Ihr Euch mit dem ansässigen Flugmeister unterhalten. Danach könnt Ihr seine Dienste in Anspruch nehmen, um weite Strecken schnell zurückzulegen.\n\nSprecht erneut mit mir, wenn Ihr bereit seid, einen Rückflug nach Orgrimmar zu erwerben. Bringt diese Berichte zu Etrigg im Tal der Stärke, sobald Ihr gelandet seid.", sourceObjective = "Sprecht mit Burok und erwerbt einen Flug zurück nach Orgrimmar. Sobald Ihr gelandet seid, bringt Gar'thoks Berichte zu Etrigg im Tal der Stärke.", progress = "Habt Ihr diese Berichte schon abgeliefert?", completion = "<Etrigg betrachtet die Berichte aufmerksam.>\n\nDie Allianz ist anmaßender, als wir dachten! Ich spreche sofort mit dem Kriegshäuptling wegen Verstärkung. Vielen Dank, dass Ihr mir diese Berichte so schnell gebracht habt. Ich hoffe, dass dieser Betrag ausreicht, um Eure Reiskosten zu decken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26808] = { id = 26808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maywiki", description = "<Linzi sieht besorgt aus.>\n\nWisst Ihr, hinter dem Kistenstapel verbirgt sich ein Troll. Sie muss furchtbar traurig sein, wenn sie nicht herauskommen und mit niemand reden will.\n\n<Linzi legt einige Akirisschilfrohre in ein Halstuch und bindet sie zusammen.>\n\nHier, gebt sie ihr. Sie sind sehr weich. Vielleicht ist es damit dort hinten ein wenig gemütlicher für sie.", sourceObjective = "Bringt Linzis Geschenk zu Maywiki von Zuldazar, die sich an der Grabungsstätte der Forscherliga befindet.", progress = "Was soll das, {class}?", completion = "<Die Trollfrau schaut in das Paket.>\n\nIch danke Euch. Ihr könnt Eurem Zwergenfreund sagen, dass ich nicht traurig bin. Ich warte. Auf Euch.\n\nIch habe festgestellt, dass Ihr der vielversprechendste {race} in dieser seltsamen Stadt seid. Ich habe eine Aufgabe für Euch, falls Ihr sie annehmen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26809] = { id = 26809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Hintertür", description = "Ich verfolge einen Vertriebenen der Gurubashi. Er heißt Zanzil der Ausgestoßene. Vor Kurzem berichteten meine Brüder aus dem Norden mir, dass er plant, sich wieder in die Gesellschaft einzugliedern. Sein erster Schritt war, einen Abgesandten zu den Schädelspaltern zu schicken. Das sind keine guten Nachrichten.\n\nIch möchte, dass Ihr versucht, Einblick in Zanzils neueste Pläne zu erhalten. Nehmt diesen Weihrauch und stellt ihn vor das Fledermaustotem in den Ruinen von Jubuwal, die sich nördlich von hier befinden. Dann wird Hir'eek Euch führen.", sourceObjective = "Legt den Weihrauch der Gurubashi vor das Totem von Hir'eek und lauscht dann Zanzils Verschwörung.", completion = "Das hatte ich vermutet. Zanzil ist zu überheblich, um sich in die Streitigkeiten zwischen den Blutskalpen und den Schädelspaltern einzumischen. Nein, er ist Teil eines größeren Komplotts ... Jin'do der Verhexer benutzt ihn, um mit seiner Hilfe Hakkar zurück nach Zul'Gurub zu holen.\n\nGut, dass wir das jetzt herausgefunden haben, denn noch gibt es dafür eine einfache Lösung ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26810] = { id = 26810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beseitigt den Ausgestoßenen", description = "Ihr müsst Zanzil töten. Ihr seid auf Hir'eeks Schwingen geritten und habt durch Hir'eeks Augen gesehen; Ihr wisst, wo Zanzil sich in den Ruinen von Aboraz versteckt hält. Begebt Euch dorthin und tötet ihn.\n\nOh, und {race} ... Falls wir getrennt werden, solltet Ihr diesen Fetisch benutzen. Er funktioniert nur innerhalb von Schlingendorn, aber er wird Euch schnell zu mir zurückbringen, falls es notwendig sein sollte.\n\nViel Glück, {race}. Zanzil ist kein gewöhnlicher Gegner.", sourceObjective = "Begebt Euch zu den Ruinen von Aboraz am Schlingendornkap und nehmt Euch Zanzil den Ausgestoßenen vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26811] = { id = 26811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Trollloch", description = "Es sieht so aus, als ob Zanzils Portal nach Zul'Gurub immer noch offen ist. Zul'Gurub ist ein gefährlicher Ort, aber Maywiki hat Euch mit dieser Aufgabe betraut.\n\nDas Portal liegt einladend vor Euch und wartet.", sourceObjective = "Benutzt Zanzils Portal und betretet Zul'Gurub.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26812] = { id = 26812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriesterin Jeklik", description = "Vor Euch ragt eine Rampe auf, die zu einer der vielen Terrassen der Stadt führt. Vor Euch befinden sich Totems, die wie Fledermäuse aussehen. Sie deuten an, dass Ihr Euch in der Hochburg der Hohepriesterin Jeklik befindet, einer Anhängerin von Hir'eek.\n\nJeklik betete Hakkar an und ist eine der Priesterinnen, die Zanzil wiederbeleben will. Wenn Ihr Euch beeilt, könnt Ihr die Wiederbelebung vielleicht verhindern.", sourceObjective = "Zerstört den Leib von Hohepriesterin Jeklik, bevor Zanzil sie wiederbeleben kann.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26813] = { id = 26813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hals über Kopf nach Zul'Gurub", description = "Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!", sourceObjective = "Benutzt Zanzils Portal.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26814] = { id = 26814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriester Venoxis", description = "Venoxis war der Zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der Nächste sein.", sourceObjective = "Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", completion = "Ich bitte Euch, Zanzil den Ausgestoßenen zu töten, einen kleinen, isolierten Vertriebenen der Gurubashi - und was tut Ihr? Stürzt Euch Hals über Kopf in die Hauptstadt der Gurubashi und eliminiert einen ihrer Hohepriester! Beinahe sogar zwei! Es gibt nur ein Wort, um ein derartig tollkühnes und verwegenes Unterfangen zu beschreiben:\n\nHeldentum.\n\nJin'do der Verhexer wandelt immer noch in den Mauern von Zul'Gurub, aber er hat ein Bein verloren, als Ihr Jeklik zerschmettert habt. Den heutigen Kampf haben wir für uns entschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26815] = { id = 26815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzils Geheimnis", description = "Vor vielen Jahren haben die Gurubashi einen der Ihren aus Zul'Gurub verbannt: einen Troll namens Zanzil. Die Gründe dafür sind nicht ganz klar. Ich vermute aber, es hatte etwas damit zu tun, dass er gerne jedem, der ihm über den Weg lief, starke, verhaltensändernde Mittel verabreichte. Die Gurubashi Priester und ihr Blutgott wurden vernichtet, aber Zanzil der Ausgestoßene existiert immer noch...\n\n... ebenso wie sein starkes, verhaltensänderndes Mittel.\n\nIch benötige diese Mixtur für meinen nächsten Test. Sucht bei den Zombies im Norden.", sourceObjective = "Beschafft 5 Phiolen mit Zanzils Mixtur.", progress = "Ausgezeichnet ... Ihr seid noch kein Zombie. Das ist gut.\n\nOh, ääh ... nichts. Es ist nur ... das war ein mögliches Risiko. Habe ich vergessen, Euch zu warnen?", completion = "<Dask analysiert sorgfältig die seltsame, chemische Verbindung.>\n\nDiese Mixtur ist... PERFEKT! Wollen wir doch mal sehen, was sie mit Eurem Artefakt, das möglicherweise titanischen Ursprungs ist, anstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26816] = { id = 26816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutaten für eine Katastrophe", description = "Habt Ihr die Explosion gesehen, die ich verursacht habe? Ich muss 10 Zoll in die Höhe geflogen sein!\n\nJetzt muss ich nur noch an Zanzils Rezept kommen, damit ich herausfinden kann, warum das passiert ist. Einer von Zanzils Lakaien in den Ruinen von Aboraz muss es bei sich haben. Begebt Euch nach Osten, zu der Küste des Kaps, und ergattert es für mich!", sourceObjective = "Beschafft Zanzils Rezeptur von einem seiner Anhänger in den Ruinen von Aboraz.", progress = "Hat er Schimmerkraut verwendet? Ich schätze, er hat Schimmerkraut verwendet.\n\nNein, wartet ...Bernsteinsamen! Es muss sich um Bernsteinsamen handeln.", completion = "Das ist faszinierend! Denkt doch nur an all die Anwendungsmöglichkeiten!\n\nNochmals, vielen Dank, {name}. Denkt daran, wenn Ihr jemals etwas zusammengemischt haben möchtet ... GANZ GLEICH worum es sich handelt ... Dem Kolben vertraut - mit Eurem Kraut!", sourceObjectiveStatus = "unverified-source-field" }
quests[26817] = { id = 26817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reinheitsgebot", description = "Diese Körperflüssigkeit allein wird nicht reichen. Sie ist zu dickflüssig. VIEL zu dickflüssig.\n\nDie Naga im Westen behüten einen Schrein, aus dem das einzig klare Wasser diesseits vom Dämmerwald fließt. Für die meisten Tränke verwende ich Flusswasser, aber Bronwyn verlangt Präzision!\n\nBeschafft Wasser aus dem Nek'maniquellbrunnen, der sich an dem höchsten Punkt des Nagalagers befindet. Viel Glück.", sourceObjective = "Beschafft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen am Schlingendornkap.", progress = "<Dask betrachtet gespannt Euer Bündel, als Ihr Euch nähert.>", completion = "Wisst Ihr, wie schwer es ist, hier am Schlingendornkap frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so erbittert verteidigen.\n\nNun gut, lasst uns mit der Mixtur beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26818] = { id = 26818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plüschpelze", description = "Hallo, ich bin die Händlerin der Stadt! Und Bronwyn ist mein Vater!\n\nTut mir leid, ich sollte nicht so aufgeregt sein. Mein Vater sagt, das ist nicht professionell.\n\nWie auch immer ... Die Leute kommen immer zu mir und fragen mich nach schwerem Leder oder rauem Balg. Doch ich glaube, es würde ihnen gefallen, wenn ich auch einige weiche Materialien hätte ... wie Tigerfell! Glaubt Ihr, Ihr könntet mir welches besorgen?\n\nIhr findet einige Panther hier in der Nähe, aber wenn Ihr die großen Tiger sucht, müsst Ihr Richtung Nordwesten gehen. Sie sind nördlich des großen Trollgebiets.", sourceObjective = "Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.", progress = "Oooh... Ich hoffe, sie sind weich!", completion = "<Linzi prüft die Felle und lächelt.>\n\nDie sind so schön und angenehm! Ich glaube, meine Kunden werden sie LIEBEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[26819] = { id = 26819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bündelweise Akiris", description = "Die Forscher der Naga, die sich westlich von hier befinden, haben ein wertvolles Ozeanschilf bei sich: Akirisschilfrohr. Händler stellen daraus Arzneien und Verpackungen her; Handwerker füttern Rüstungen oder umwickeln Zigarren damit.\n\nWenn wir mit dem Graben fertig waren, hat mein Vater mir abends gezeigt, wie man es verwendet. Leider haben wir keins mehr. Würde es Euch etwas ausmachen, uns noch mehr davon zu holen?", sourceObjective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", progress = "Willkommen zurück!", completion = "Hurra! Es ist schon viele Tage her, dass wir Akirisschilfrohr hatten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26820] = { id = 26820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn sie sie einfach herumliegen lassen ...", description = "Vater sagt, dass ein verantwortungsvoller Händler immer nach lohnenden Geschäften Ausschau hält. Ich versuche, auf Schritt und Tritt nach guten Geschäften Ausschau zu halten, und ich glaube, jetzt habe ich eins gefunden!\n\nDie Naga, die sich westlich von hier befinden, haben Dutzende Statuen, die sie dort, wo sie leben, überall auf den Boden stellen. Sie können unmöglich alle gebrauchen - also dachte ich, dass wir ein paar für uns nehmen!\n\nStatuen, ganz umsonst! Das ist doch ein gutes Geschäft, oder nicht?", sourceObjective = "Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.", progress = "Lasst mal sehen!", completion = "Diese Statuen sind wunderschön...\n\nWow, ich wusste gar nicht, dass die Naga so talentiert sind. Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26821] = { id = 26821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airwyn Bantamflax", description = "Nun, wir haben keine Ahnung, was dieses Artefakt ist. Es ist alt, älter als der Staub ... aber nicht titanischen Ursprungs. Ich bin absolut sprachlos.\n\nAirwyn Bantamflax in Beutebucht ist meine direkte Vorgesetzte. Als nächstes sollten wir sie über diesen Fund informieren. Würdet Ihr ihn bitte zu ihr bringen?", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Airwyn Bantamflax in Beutebucht am Schlingendornkap.", progress = "Ja, {race}? Ich bin sehr beschäftigt.", completion = "Faszinierend!\n\nIch brauche etwas Zeit, um mir das genauer anzusehen. Warum seht Ihr Euch nicht ein wenig in Beutebucht um und kommt später wieder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26822] = { id = 26822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichtsnutzige, züngelnde Kriecher", description = "Ahem! Hrm, hrm ...\n\n<Der Zwerg räuspert sich einige Sekunden lang.>\n\nIhr sucht nach einer Beschäftigung? Und da kommt Ihr zu MIR? Dem kleinen, alten Goris?!\n\nNun, äh ... das ist das erste Mal. Ah, ich hab's!\n\nDas Tal im Norden ist voll nutzloser Basilisken, die nur ihre Wampe auf dem Boden schleifen. Sie sind zu rein gar nichts nutze und man sagt, sie hätten einmal jemand in Stein verwandelt.\n\nWenn Ihr sie tötet, gebe ich Euch etwas von meinem Zeug.", sourceObjective = "Tötet 12 Donnerschwanz- oder Eisenkieferbasilisken.", completion = "Ahem! Aaah... richtig... \n\nGut gemacht! Meinen Glückwunsch, dass Ihr sie getötet habt, meine ich.\n\nHier, bitte, für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26823] = { id = 26823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Mund zu voll genommen", description = "Was immer Ihr tun wollt: Ich habe genau das richtige Rezept dafür. Ihr wollt einen Sprengstofftrank? BUMM!! Ihr wollt einen Blitztrank? BRITZEL!! Ihr wollt einen Schrumpftrank? Flupp!\n\nAlso Bronwyn sagt, er will einen Kohlenstoffdatierungstrank? Nichts leichter als das. Den könnte ich im Schlaf machen. Das Problem ist... wenn wir wollen, dass er präzise funktioniert, dann brauche ich einige hochwertige Zutaten.\n\nFangen wir mit ein wenig Körperflüssigkeit von einem Basilisken im Norden an. Es muss ein ziemlich großer Basilisk sein...", sourceObjective = "Beschafft eine Phiole mit Eisenkieferkörperflüssigkeit vom Eisenkieferungetüm in der Kristalladermine.", progress = "Soll ich's mischen... wird es zischen.", completion = "Also gut! Schritt eins - Zutaten besorgen - erledigt. Zeit für den nächsten Schritt: noch mehr Zutaten besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26824] = { id = 26824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ergebnisse: Nicht eindeutig", description = "Ich habe getan, was ich konnte, {name}. Ich hatte die richtigen Tränke... Ich hatte die richtigen Rezepte... Aber der Ursprung dieser Probe entzieht sich meiner Kenntnis. Sie ist zehntausende Jahre alt, aber wir haben bewiesen, dass sie nicht titanischen Ursprungs ist. Und ein Blick genügt, um festzustellen, dass es nicht Saronit ist. Also... um was in Branns Namen handelt es sich?\n\nSagt Bronwyn, dass ich mein Bestes gegeben habe. Tut mir leid.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Bronwyn im Lager der Forscherliga am Schlingendornkap zurück.", progress = "Ich habe Rauch gesehen. Ist alles in Ordnung?", completion = "Ich wusste, dass dieser Alchemist nur eine große Klappe hat. Nun, danke für Eure Hilfe, {name}. Ich weiß, dass Ihr es versucht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26825] = { id = 26825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"Der Kolben\" Fusselmaul", description = "Hey, Ihr müsst <der Bursche/das Mädchen> sein, von dem Wulfred gesprochen hat. Ihr habt das Ogerartefakt gefunden und ihm geholfen, diese merkwürdigen Steine aus dem Norden zu testen. Willkommen an der Grabungsstätte, {name}!\n\nWir waren gerade dabei, diese Proben zu bestimmen, als Ihr hier angekommen seid. Würde es Euch etwas ausmachen, eine Probe zu Dask zu bringen? Er muss mir helfen, herauszufinden, wie alt sie ist.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Dask \"Der Kolben\" Fusselmaul in der Grabungsstätte der Forscherliga am Schlingendornkap.", progress = "Ihr habt etwas, das ich zusammenmischen soll?", completion = "Also bleibt es wieder einmal an dem kleinen Dask hängen, die Arbeit der Forscherliga zu erledigen! Also gut... Schauen wir einmal, was Ihr da habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26826] = { id = 26826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"Der Kolben\" Fusselmaul", description = "Hey, Ihr müsst <der Bursche/das Mädchen> sein, von dem Wulfred gesprochen hat. Willkommen an der Grabungsstätte, {name}.\n\nWir wollten gerade ein neues Projekt beginnen, als Ihr eingetroffen seid. Würde es Euch etwas ausmachen, diese Probe zu Dask zu bringen? Er muss mir helfen, herauszufinden, wie alt sie ist.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Dask \"Der Kolben\" Fusselmaul in der Grabungsstätte der Forscherliga am Schlingendornkap.", progress = "Ihr habt etwas, das ich zusammenmischen soll?", completion = "Also bleibt es wieder einmal an dem kleinen Dask hängen, die Arbeit der Forscherliga zu erledigen! Also gut... Schauen wir einmal, was Ihr da habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26827] = { id = 26827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Irdenen Ring zusammenrufen", description = "Wir müssen den Irdenen Ring für diesen Kampf zusammenrufen. Unsere zahlenmäßige Unterlegenheit gleichen wir durch unsere Stärke aus.\n\nGeht zum Tempel und versammelt die ruhenden Schamanen aus den hinteren Räumen. Norsala, Lorvarius und ich treffen uns mit ihnen an Lorthunas Tor.", sourceObjective = "Versammelt 5 Schamanen im hinteren Teil des Tempels der Erde und sprecht dann mit Maruut Steinbinder.", completion = "Was Ihr getan habt, hätte ich nicht für möglich gehalten. Ziemlich beeindruckend, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26828] = { id = 26828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Teil der Vereinbarung", description = "Leider muss ich hierbleiben und auf den Riss aufpassen, also müsst Ihr ohne mich kämpfen. Geht jetzt zu Therazane und schließt Euch wie versprochen dem Kampf an. Ihr solltet Sie am Halcyonaufstieg nördlich von Lorthunas Tor und östlich des Geschliffenen Schlunds vorfinden.\n\nWenn unser Teil der Abmachung erfüllt ist, bringt das letzte Stück der Weltensäule so schnell wie möglich hierher.", sourceObjective = "Sprecht mit Therazane auf dem Halcyonaufstieg.", completion = "Ihr seid also gekommen, Fleischling. Wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26829] = { id = 26829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinmarsch", description = "Meine Streitkräfte haben den Angriff bereits begonnen. Schließt Euch ihnen an. Vergießt das Blut dieser Kultisten, damit ich spüren kann, wie sie leiden.", sourceObjective = "Tötet 15 Kultisten des Zwielichthangs.", completion = "Ihr Blut auf dem Boden ist berauschend. Ich werde jeden Augenblick genießen und die Nachzügler langsam in meinem Reich auslöschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26830] = { id = 26830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köder für den Verräter", description = "Ich habe meine Suche nach den Agenten des Schattenhammers, die hier in Orgrimmar herumlungern, noch nicht aufgegeben. Ich brauche jemanden, dem ich vertrauen kann, um den letzten Beweis für den Verrat zu finden.\n\n<Höllschrei nimmt Euch zur Seite.>\n\nSauranok der Mystiker - mein Vertrauter und Berater! - steht unter Verdacht. Deckt die Wahrheit auf, {name}, und Ihr werdet belohnt werden.\n\nWie ich höre, hat der Schattenhammer die Arbeiter an den Luftschiffdocks unterwandert, um seine Lügen über den gesamten Kontinent zu verbreiten. Befragt sie. Solltet Ihr herausfinden, dass Sauranok schuldig ist... Tötet ihn!", sourceObjective = "Befragt Peons des Himmelpfads von Orgrimmar in der Nähe des Zeppelinturms. Haltet Ausschau nach verdächtigen Peons. Versucht, Sauranok den Mystiker aufzuscheuchen und tötet ihn.", progress = "Schön, dass Ihr noch am Leben seid, {class}. Wie steht's mit Euren Nachforschungen?", completion = "Sauranok, Sauranok! Seine eigenen Visionen haben gegen ihn gearbeitet. Der Schattenhammer hat ihn wahrscheinlich aus der Ferne bestochen. Bah! Schwächling! Wir werden seinen Namen nie wieder aussprechen.\n\nIch sagte ihm, dass Ihr an den Luftschiffdocks Nachforschungen anstellt, {name}, um ihn aus der Reserve zu locken. Ja, ich habe Euch als Köder benutzt. Ihr habt Eurer Horde gut gedient und verdient eine Belohnung, weil Ihr diese Schlange in unserer Mitte enttarnt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26831] = { id = 26831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug ins Zwielicht", description = "Terrath braucht Euch auf der anderen Seite des Abgrunds, um Zoltrik Drachenbann zu bekämpfen. Er ist ebenfalls unterwegs, aber er fürchtet, Zoltrik wird sich in die Luft erheben.\n\nWie es scheint, habt Ihr ziemlichen Eindruck hinterlassen, Kleinling. Ist Euch jemals der Gedanke gekommen, dass all dies nie geschehen wäre, wenn ich bei unserem ersten Zusammentreffen auf Euch getreten wäre? Das Schicksal geht seltsame Wege.", sourceObjective = "Besiegt Zoltrik Drachenbann.", progress = "Es ist gut, Euch wieder auf dem Schlachtfeld zu sehen.", completion = "Es war gut, dass Ihr zur Stelle wart. Merkwürdigerweise ist meine Größe durchaus hinderlich, wenn es darum geht, einen Drachen zu reiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26832] = { id = 26832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therazanes Gnade", description = "Der Schattenhammer hat zwei Führungspersönlichkeiten, die getötet werden müssen.\n\nDie eine ist ein Mensch namens Boldrich. Er ist klein, so wie Ihr. Aber dennoch gefährlich, ebenfalls so wie Ihr.\n\nDie andere ist eine Priesterin namens Lorthuna. Sie ist gerissen und nur schwer in die Enge zu treiben. Schlagt schnell zu und lasst sie nicht entkommen, sonst werdet Ihr es später bereuen - das verspreche ich Euch.", sourceObjective = "Besiegt Boldrich Steinreißer und Hohepriesterin Lorthuna.", completion = "Ihr habt Lorthuna entwischen lassen? Ich habe Euch davor gewarnt.\n\nDennoch, ihre Streitkräfte sind zerschlagen und ihr Nachschub ist abgeschnitten. Sie können mir oder meinen Verbündeten nicht mehr viel Schaden zufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26833] = { id = 26833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Stein gemeißelt", description = "Ihr habt getan, worum ich Euch gebeten habe, {race}. Ich werde zu meinem Wort stehen. Gorsik wird Euch mit unserem Stück der Weltensäule am Tempel treffen.\n\nBeendet Euer Ritual und schließt den Riss. Wenn Ihr das getan habt, sagt Eurem Irdenen Ring, er möge diesen Ort verlassen. \n\nIhr allerdings... Ihr dürft noch eine Weile bleiben, wenn Ihr möchtet. Das habt Ihr Euch verdient.", sourceObjective = "Sprecht mit Maruut Steinbinder am Tempel der Erde.", completion = "Gorsik ist eingetroffen. Dank Euch sind nun alle Teile der Weltensäule hier.\n\nWas Ihr für uns getan habt, ist von unermesslichem Wert. Diese letzten Momente werden entscheidend sein. Es fällt mir schwer, noch mehr von Euch zu verlangen, aber ich möchte, dass Ihr es bis zum Ende gemeinsam mit uns durchsteht.\n\nEure Angriffe haben den Schattenhammer zwar niedergeworfen, aber nicht vernichtet. Wir gehen davon aus, dass sie versuchen werden, uns von der Vollendung des Rituals abzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26834] = { id = 26834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in den Abgrund", description = "Tief in der Nadelfelsschlucht lassen die Mystiker all diese Fungusmissgeburten sprießen. Ich habe Schiefer Treibsand und eine kleine Truppe hingeschickt, damit sie sich darum kümmern, aber sie sind auf Schwierigkeiten gestoßen.\n\nErinnert Ihr Euch noch an den Erzgeomanten? Würdet Ihr im Nordosten hinunterfliegen und ihm behilflich sein?", sourceObjective = "Sprecht mit Schiefer Treibsand in der Nadelfelsschlucht in Tiefenheim.", completion = "Schön, Euch wiederzusehen, {name}. Jetzt werden wir weiterkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26835] = { id = 26835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines Problem", description = "Während Ihr dort draußen wart, hat sich Pyrium Leitstein mit mir in Verbindung gesetzt. Er meinte, dass es eine Angelegenheit höchster Dringlichkeit gäbe und dass man umgehend Eure Unterstützung bräuchte. Kehrt zum Eingang am Nadelfelsbruch im Südwesten zurück.\n\nIch wünsche Euch viel Glück bei der Rettung des Steinvaters und der Bergung des zweiten Fragments.", sourceObjective = "Kehrt zu Pyrium Leitstein im Nadelfelsbruch in Tiefenheim zurück.", completion = "{name}, wir haben gute Nachrichten und ein kleines Problem…", sourceObjectiveStatus = "unverified-source-field" }
quests[26836] = { id = 26836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Steinvater... und Flint", description = "Wir haben herausgefunden, wo der Steinvater gefangengehalten wird, und prompt ist der junge Flint losgerannt, um ihn zu befreien!\n\nIch muss Euch nicht sagen, dass das gar nicht gut ist. Flint könnte ebenfalls gefangengenommen werden - oder noch Schlimmeres!\n\nDer Häuptling der Steintroggs, Felsmagen, befindet sich am äußersten Ende der Felssimse über der Nadelfelsschlucht im Norden. Bitte, {name}, Ihr müsst Flint folgen und den Steinvater befreien, bevor wir sie beide verlieren!", sourceObjective = "Befreit Steinvater Erzmantel.", progress = "Ihr müsst Steinvater Erzmantel befreien. Ihr dürft keine Zeit verschwenden, {name}!", completion = "{name}! Ihr habt es geschafft! Wie können wir das jemals wieder gutmachen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26837] = { id = 26837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grabungsstätte der Forscherliga", description = "Hört einmal, {name}... Ihr scheint genau richtig zu sein.\n\nBronwyn Hackschlag von der Forscherliga sucht neue Rekruten für seine Grabungsstätte am Schlingendornkap. Ich persönlich verstehe ja nicht, warum er nicht einfach nach Beutebucht geht und dort seine Rekruten sucht... Piraten kann man leicht mit ein paar Goldstücken überreden.\n\nWie auch immer - gerüchteweise hört man, dass er endlich etwas dort im Dschungel gefunden hat. Ich frage mich, was das sein könnte?", sourceObjective = "Sprecht mit Bronwyn Hackschlag an der Grabungsstätte der Forscherliga am Schlingendornkap.", sourceObjectiveStatus = "unverified-source-field" }
quests[26838] = { id = 26838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn man keine Ahnung hat ...", description = "Vor einigen Jahren hat Captain Kurzen aus Sturmwind eine Brigade ins Schlingendorntal gebracht. Die Einzelheiten seiner Mission sind immer noch unklar. Kurzen fiel schnell dem Wahnsinn anheim, genau wie seine Männer ... außer einigen Rebellen, die es sich zur Aufgabe gemacht haben, das Böse, das Kurzen angerichtet hat, ungeschehen zu machen.\n\nWie ich bereits sagte, das war vor vielen Jahren. Jetzt ist mir zu Ohren gekommen, dass Kurzen tot ist. Doch diese Rebellen bestehen immer noch auf ihrer Rebellion. Wenn Ihr Ermittlungen anstellen wollt, findet Ihr sie in einem Lager an der nördlichen Grenze von Schlingendorntal.", sourceObjective = "Meldet Euch bei Leutnant Doren im Rebellenlager im Nördlichen Schlingendorntal.", completion = "Willkommen in unserem Lager, {class}. Ihr seid genau zum richtigen Zeitpunkt eingetroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26839] = { id = 26839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Auszeit nehmen!", description = "Sagt einmal, {class}, Ihr seht erschöpft aus. Diese schwere Geldbörse ... äh, ich meine ... schwere Ausrüstung mit sich herumzuschleppen muss doch eine große Belastung für Euren armen Rücken sein.\n\nSassy Hartzang hat vor Kurzem ein erstklassiges Fünf-Sterne Erholungszentrum am Schlingendornkap eröffnet. Ballonfahrten, Ruderboottouren, Tagesausflüge nach Beutebucht ... es ist alles vorhanden.\n\nIhr solltet dem Zentrum wirklich einen Besuch abstatten. Ich muss Euch nur anschauen und weiß, dass Ihr nach so vielen schwierigen, lukrativen Abenteuern eine Erholung braucht.", sourceObjective = "Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.Sagt einmal, {class}, Ihr seht erschöpft aus. Diese schwere Geldbörse... äh, ich meine... schwere Ausrüstung mit sich herumzuschleppen muss doch eine große Belastung für Euren armen Rücken sein.\n\nSassy Hartzang hat vor Kurzem ein erstklassiges Fünf-Sterne Erholungszentrum am Schlingendornkap eröffnet. Ballonfahrten, Ruderboottouren, Tagesausflüge nach Beutebucht... es ist alles vorhanden.\n\nIhr solltet dem Zentrum wirklich einen Besuch abstatten. Ich muss Euch nur anschauen und weiß, dass Ihr nach so vielen schwierigen, lukrativen Abenteuern eine Erholung braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26840] = { id = 26840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr ins Hochland", description = "Jetzt, da Orgrimmar sicher ist und wir unsere Verbündeten des Drachenmalklans hinter uns wissen, können wir unsere Aufmerksamkeit dem Schattenhochland und der Vernichtung der Truppen von Todesschwinge zuwenden.\n\nIch brauche die Besten der Horde an der Front. Damit meine ich Euch. Und all Eure Freunde.\n\nDas Hochland wird UNS gehören!\n\nBenutzt das neue Portal, das Ihr erschaffen habt, um in den Hafen des Drachenmals zurückzukehren. Meldet Euch bei Zaela, um zu sehen, wo sie Euch am meisten braucht.", sourceObjective = "Benutzt das Portal des Drachenmals in Orgrimmar, um in den Hafen des Drachenmals im Schattenhochland zurückzukehren und sprecht mit Zaela.", completion = "{name}! Ist in Orgrimmar alles in Ordnung?\n\nWie Ihr seht, läuft der Bau des Hafens des Drachenmals auf Hochtouren. Sollte mein Volk an der Macht der Horde bisher gezweifelt haben, wird dieses beeindruckende Gebäude und die Geschwindigkeit, mit der es errichtet wurde, sie eines besseren belehren.\n\nEs beginnt eine neue Zeit für das Drachenmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26841] = { id = 26841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verbotene Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten überbracht und stammt von unserer Magierlehrerin Rhyanda. Wie es aussieht, möchte Rhyanda mit Euch sprechen, wenn Ihr einen Moment erübrigen könnt. Lest es und bringt es ihr danach bitte.", sourceObjective = "Sprecht mit Rhyanda in Aldrassil im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[26842] = { id = 26842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier ein Gnoll, dort ein Gnoll", description = "Seid gegrüßt, {class}. Wir haben ein Problem und ich würde Euch bitten, uns zu helfen.\n\nEs handelt sich um Gnolle. Westlich der Stadt streift ein ganzer Haufen dieser Viecher durch die Hügel. Eigentlich ist das kein Grund, beunruhigt zu sein, aber normalerweise haben wir hier keine Gnolle in Loch Modan.\n\nMich interessiert, wo sie herkamen, allerdings bin ich nicht neugierig genug, um diese räudigen Dinger zu fragen. Ich bin der Meinung, wir sollten sie loswerden. Bringt mir Beweise, dass Ihr sie getötet habt und ich werde Euch ein beachtliches Kopfgeld zahlen.", sourceObjective = "Sammelt 12 Gnollohren von Spähern und Schlägern der Moosfelle.", progress = "Nun, habt Ihr einige Ohren für mich?", completion = "Gut gemacht, mein Freund. Ich könnte einen {class} wie Euch hier gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26843] = { id = 26843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein winziger, cleverer Kommandant", description = "Wir schlagen uns in diesem Land schon seit Jahren mit Kobolden herum. Bisher waren sie kaum mehr als ein Ärgernis. Aber sie werden bei ihren Diebstählen immer geschickter.\n\nIch glaube, einer von ihnen ist irgendwie klüger als üblich. Aber das wird nicht mehr lange der Fall sein!\n\nIch möchte, dass Ihr zu ihrem Lager im Süden geht und sicherstellt, dass sich dort kein \"Obermotz\" Kobold befindet, der die anderen aufwiegelt. Achtet darauf, auch die Höhle zu untersuchen. Das wäre mit ziemlicher Sicherheit ein guter Ort.\n\nAch ja, und übt keine Zurückhaltung, wenn es darum geht, die Kobolde, die Euch unterwegs begegnen, zu beseitigen.", sourceObjective = "Tötet \"Kommandant\" Nazrim.", completion = "Also hatte ich recht! Die Frage ist, was diese kleinen Nervensägen geplant haben ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26844] = { id = 26844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Regen in die Traufe", description = "Jetzt, da wir diese kleinen Quälgeister erledigt haben, müssen wir uns um weitere Dinge kümmern.\n\nDie Tunnelratten schwärmen durch die ganze Silberbachmine. Sie schlagen Lager auf und schnüffeln überall herum. Dabei ziehen sie immer weitere Kreise. Die gierigen kleinen Viecher suchen bestimmt nach Beute.\n\nVermessen und nach Futter wühlen ist ja schön und gut, solange es nicht auf Zwergenland stattfindet! Kümmert Euch um diese Tunnelratten und meldet Euch dann wieder bei mir.", sourceObjective = "Tötet 5 Feldmesser der Tunnelratten und 5 Futterwühler der Tunnelratten.", completion = "Gut, gut! Jetzt ist mir klar, was in der Mine vor sich geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26845] = { id = 26845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat hier das Sagen?", description = "Dorli hat mir von diesem verrückten Troggsklaven-Vorhaben erzählt, das bei den Kobolden im Gange ist. Wenn Ihr bisher noch nicht mit ihr gesprochen habt, schlage ich vor, dass Ihr das nachholt. Ich möchte dieser Sache auf den Grund gehen.\n\nIm wahrsten Sinne des Wortes! Wer immer hier die Fäden zieht, sitzt garantiert ganz unten in der Mine und gibt von dort die Befehle. Ich will, dass er zur Strecke gebracht wird.\n\nFindet den gerissenen Schlauberger, der die Geomanten und Gräber dirigiert und bringt mir seinen Kopf.", sourceObjective = "Bringt mir den Kopf von Vorarbeiter Scharfspott.", progress = "War Moira vielleicht dort unten? Wunder gibt es ja immer wieder.", completion = "Das ist der Kopf eines Gnolls. Versucht Ihr, mich hier hinter's Licht zu führen, {name}?\n\nWenn nicht, habe ich nicht den Hauch einer Ahnung, was hier vor sich geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26846] = { id = 26846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fieser Plan", description = "Ich habe herausgefunden, was diese Ratten im Schilde führen. Der Grund, warum so viele von ihnen draußen herumlaufen, ist, dass sie Troggs dazu gebracht haben, für sie in der Mine zu schürfen!\n\nDie Geomanten der Tunnelratten haben irgendeinen Taschenspielertrick ersonnen, mit dem sie die Troggs kontrollieren können. Irgendwas mit Kreaturen der Erde oder so ähnlich.\n\nFaszinierend, aber wir können ihnen das nicht durchgehen lassen. Beseitigt diese Geomanten so schnell wie möglich.", sourceObjective = "Tötet 5 Geomanten der Tunnelratten.", completion = "Ich bin sicher, dass das nur funktioniert hat, weil die Troggs ohnehin nicht die hellsten sind. Aber wir Zwerge waren auch einmal Kreaturen der Erde.\n\nVon einem Kobold herumkommandiert zu werden ist so entwürdigend ... Ich bin froh, dass wir nicht herausgefunden haben, ob sie dazu auch in der Lage gewesen wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[26854] = { id = 26854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Pilot", description = "Mein Freund Mori Hangflug, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!\n\nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.\n\nDas ist jetzt mehrere Tage her, und ich habe des Nachts nördlich des Helmsbettsees und westlich des Tunnels das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.\n\nBitte, {name}. Sucht ihn.", sourceObjective = "Findet Pilot Hanglug nördlich des Helmsbettsees.", completion = "Hier liegt die Leiche eines Zwergs - zerfetzt, gefroren und von Aasfressern blankgefressen. Seine Hand umklammert ein Buch, das die grob hingekritzelten Aufzeichnungen von Mori Hangflug enthält. Um ihn gehüllt, nach wie vor in sehr gutem Zustand, ist eine Brigadiersweste.\n\nAn diesem grausigen Ort muss der Pilot der Belagerungsmaschinen sein Ende gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26855] = { id = 26855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilotenrache", description = "Hangflug schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.\n\nWenn man sich den Zustand von Hangflugs Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.\n\nJedenfalls schrieb Hangflug in sein Tagebuch einen letzten Wunsch:\n\nRache an Marterklaue.", sourceObjective = "Tötet Marterklaue.\n\nBringt Pilot Hammerfuß am Südtoraußenposten die räudige Klaue des Bären und Hangflugs Tagebuch.", progress = "Hallo, {name}. Wisst Ihr etwas über den Verbleib meines Freundes Hangflug?", completion = "Das sind traurige Neuigkeiten, denn Hangflug war ein guter Freund. Ich wünschte, ich hätte dort mit Euch sein können, als Ihr die Bestie Marterklaue gefunden habt!\n\nDanke, {name}. Eure Tat wird den Piloten der Belagerungsbrigade von Eisenschmiede in Erinnerung bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26856] = { id = 26856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft die Invasion zurück", description = "Diese Höhle war einst ein Ort großer Ehre. Man brachte junge Krieger hierher, damit sie zum ersten Mal in ihrem Leben einen Erdbohrerwurm erlegen. Daran erinnern wir Orcs uns das ganze Leben lang.\n\nDie Agenten der Brennenden Klinge haben die Einwohner der Höhle versklavt und wollen nun Orgrimmar mit ihren Troggverbündeten angreifen.\n\nWenn Ihr ihre Leutnants zur Strecke bringt, könntet Ihr sie unvorbereitet erwischen und diese Invasion verhindern, bevor sie überhaupt beginnt.", sourceObjective = "Tötet Flintauge, Bazzalan und Jergosh den Herbeirufer.", completion = "Ihr habt es geschafft, {name}! Ihr habt die Invasion der Brennenden Klinge verhindert, bevor sie begann! Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26857] = { id = 26857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssions Diener", description = "Wenn der Drache das Fragment hat, müssen wir seine Aufmerksamkeit auf seinen Hort lenken.\n\nGeht zu Abyssions Hort gleich östlich von hier und besiegt seine Untergebenen. Das wird ihn früher oder später dazu veranlassen, mit dem Weltensäulenfragment aufzutauchen.", sourceObjective = "Besiegt 8 Zwielicht- oder Drachkineinheiten in Abyssions Hort.", completion = "Das sollte genügen, um die Aufmerksamkeit des Drachen zu erregen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26858] = { id = 26858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taragaman der Hungerleider", description = "Der Sengenden Klinge ist es gelungen, einen widerlichen Dämonen zu beschwören, den sie Taragaman den Hungerleider nennen. Er soll bei der Übernahme von Orgrimmar den ersten Angriff leiten.\n\nBeeilt Euch und tötet Taragaman im Namen des Kriegshäuptlings! Lok'tar ogar!", sourceObjective = "Holt das Herz von Taragaman dem Hungerleider.", progress = "Zeigt mir das Herz von Taragaman, wenn er tot ist.", completion = "Meine Kinder werden noch Loblieder auf Euch singen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26860] = { id = 26860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutwurst aus Thelsamar", description = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?\n\nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr <ein toller/eine tolle:c> {class} seid.\n\nBringt mir frische Bärenrücken und überlasst das Kochen nur mir!", sourceObjective = "Sammelt 8 Bärenrücken von Schwarzbären in Loch Modan.", progress = "Ich bin so weit, dass ich mit dem Kochen anfangen könnte; habt Ihr die Bärenrücken?", completion = "Vielen Dank! Die Rückenstücke sind meine eigene geheime Erweiterung des Rezepts... aber hier habt Ihr die Anleitung, wie man es mit jeder beliebigen Sorte Bärenfleisch herstellen kann.\n\nObendrein gibt’s noch eine frische Portion, die ich selbst gekocht habe. Frisch schmecken sie am besten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26861] = { id = 26861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blockiert die Tore", description = "Wenn wir eine Chance gegen Abyssion haben wollen, müssen wir sicherstellen, dass ihn keine Verstärkung zur Unterstützung erreicht.\n\nIn seinem Hort gen Osten werdet Ihr zwei Tore vorfinden. Benutzt diesen Sturmstein, um ihre Funktion zu unterbinden.\n\nWenn alles so läuft wie geplant, werden wir Abyssion angreifen können, ohne dass er viel Unterstützung bekommt.", sourceObjective = "Benutzt den Sturmstein am Zwielichttor und Elementartor in Abyssions Hort.", progress = "Ihr seid zurück, {name}. Sind die Tore geschlossen?", completion = "Ausgezeichnet. Wenn wir gegen Abyssion ziehen, sollten wir keine Gefahr durch seine Verstärkung zu fürchten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26862] = { id = 26862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verpfuschte Elementare", description = "Die Hexenmeister der Sengenden Klinge haben die Geister der Elementare in Flammenschlund versklavt, {name}. Solange mein Zauber sie im Zaum hält, stellen sie keine Bedrohung für die Stadt dar, aber ich kann ihn nicht mehr lange aufrecht halten.\n\nBringt mir sechs der sengenden Bindungen, mit denen sie unter Kontrolle gehalten werden und ich werde ihre Geister im Flammenschlund wieder freisetzen.", sourceObjective = "Beschafft 6 sengende Bindungen.", progress = "Habt Ihr die Bindungen?", completion = "Ich danke Euch, {class}. Die Geister der geschmolzenen Elementare haben endlich ihre Ruhe gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26863] = { id = 26863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Pfoten", description = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!\n\nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.\n\nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", sourceObjective = "Sucht in der Silberbachmine 6 Sätze Minenarbeiterausstattung zusammen.", progress = "Habt Ihr die Minenarbeiterausstattung, {name}?", completion = "Habt Ihr da drin viele Kobolde gesehen? Der Gedanke daran, wie ihre schmutzigen Hände in unserer Mine herumkratzen, verursacht mir Bauchschmerzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26864] = { id = 26864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopflos", description = "Ihr müsst das hier zu Gebirgsjäger Kadrell bringen. Zeigt es ihm und sagt ihm, dass die fiesen Plagegeister hier möglicherweise eine Art Versammlung abhalten werden.", sourceObjective = "Bringt den Kopf von Vorarbeiter Scharfspott zu Gebirgsjäger Kadrell.", progress = "Gibt es Neuigkeiten von der Station Algaz?", completion = "Gnolle, Kobolde und Troggs? Au weia.\n\nIch würde glatt lachen, wenn ich nicht noch eine andere unerwartete Wendung der Geschichte für Euch hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26865] = { id = 26865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind tief unten", description = "Unter dieser Stadt, befinden sich Feinde der Horde, {class}.\n\nDie Angehörigen der Sengenden Klinge planen, Orgrimmar für sich zu übernehmen und sie haben bereits den Flammenschlund überrannt! Wir müssen gegen ihre Truppen anstürmen und zurückerobern, was uns gehört!\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Er hat weitere Instruktionen für Euch.", sourceObjective = "Sprecht mit Steinwächter Kurjack.", completion = "Ich habe Eure Ankunft erwartet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26866] = { id = 26866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind tief unten", description = "Der Flammenschlund in Orgrimmar wurde von der Sengenden Klinge übernommen. {name}, wir können das nicht ungestraft durchgehen lassen, sonst richten sie ihren Blick als nächstes auf Donnerfels.\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Helft ihm auf jede erdenkliche Art und Weise, da unsere Schicksale miteinander verknüpft sind.", sourceObjective = "Sprecht mit Steinwächter Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[26867] = { id = 26867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind tief unten", description = "Kriegshäuptling Garrosh hat unter Aufbietung all seines wohlbekannten Liebreizes freundlich um Eure Anwesenheit im Flammenschlund gebeten, damit Ihr ihm helfen könnt, diesen von der Sengenden Klinge zurückzuerobern. Offensichtlich ist seine verstärkte Stadt nicht so uneinnehmbar, wie er dachte.\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Ich bin sicher, dass er über fähige Hilfe sehr froh sein wird.", sourceObjective = "Sprecht mit Steinwächter Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[26868] = { id = 26868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Achse des Grässlichen", description = "So, also nun haltet mal die Klappe und lasst mich reden. Der Plan sieht so aus...\n\nDiese Gnolle und Murlocs werden sich wahrscheinlich hier draußen irgendwo treffen. Also nehmt Ihr dieses clevere Pflanzenverkleidungsset von mir, zieht es an und seht wie eine Pflanze aus. Dann schleicht Ihr Euch an sie heran und werft die Geruchspheromone, die ihr gesammelt habt, über die Moosfelle, die bei den Murlocs stehen.\n\nDann brennen bei den Murlocs die Sicherungen durch und die Moosfelle werden es sich zweimal überlegen, ehe sie wieder mit diesen verrückten kleinen Nervensägen zusammenarbeiten.", sourceObjective = "Benutzt das clevere Pflanzenverkleidungsset, um Euch an den Repräsentanten der Moosfelle heranzuschleichen. Dann bestäubt ihn mit den starken Murlocpheromonen.", completion = "Hat doch wunderbar geklappt, oder nicht? Vielleicht fällt Kadress mir jetzt endlich nicht mehr auf die Nerven, nachdem ich die Stadt gerettet hab' und so.\n\nIhr habt Euch wohl auch ein paar anständige Sachen verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[26869] = { id = 26869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe der Tiefen", description = "<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>\n\nGut gemacht, {race}.\n\nIn den unterirdischen Tunneln werdet Ihr den Stein, den Ihr sucht, finden. Painit.\n\nDie Gefahren, die vor Euch liegen sind mannigfaltig...\n\nGefahren, die sogar die Steinlords selbst fürchten.\n\nBleibt ruhig.\n\nBleibt stark.\n\nDie Stärke des Felsens ruht unter Euren Füßen.", sourceObjective = "Findet das Painit in den Bruchtiefen.", completion = "<Das ist er. Das ist der Stein, den Ihr für Diamant holen solltet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26870] = { id = 26870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung der Höhlen", description = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer hatte sich vorgenommen, den Smaragdgrünen Traum zu betreten und dabei zu helfen, dieses unwirtliche Land wieder zu dem üppigen Wald zu machen, der es einst gewesen war. Aber etwas ging furchtbar schief.\n\nDie treuen Verbündeten von Naralex, die Druiden des Giftzahns, wandten sich gegen ihn! Ihr Ziel ist es nicht, das Brachland zu heilen, sondern es zu beherrschen. {name}, bevor wir Naralex erwecken und das Gleichgewicht an diesem wichtigen Ort wiederherstellen können, müsst Ihr die Giftzahnlords auslöschen. Ihr Einfluss ist viel zu groß geworden.", sourceObjective = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr die Giftzahnlords Cobrahn, Anacondra, Pythas und Serpentis vernichtet.", completion = "Ich spüre bereits, wie das Gleichgewicht zurückkehrt! Schnell, sprecht mit Muyoh und helft ihm, Naralex zu erwecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[26871] = { id = 26871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fels unter vielen", description = "<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>\n\nIhr habt das getan, worum ich gebeten hatte.\n\nGeht zurück und verlasst die Höhle unverletzt.\n\nVergesst den Edelstein nicht.", sourceObjective = "Kehrt mit dem Painitbrocken zu Diamant an Lorthunas Tor zurück.", progress = "Ihr lebt. Das ist gut.\n\nTragt Ihr den Edelstein bei Euch?", completion = "Gut gemacht, Fleischling!\n\nDie Tunnelgräber zählen zu unseren gefährlichsten Feinden.\n\nDie anderen Steinlords werden diesen Erfolg nicht ignorieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26872] = { id = 26872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviatbälge", description = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Ihre bloße Existenz verursacht der Welt große Schmerzen. Ich glaube, dass ihr Tod unseren Versuchen, den Höhlen Heilung zu bringen, sehr helfen wird.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen hinab, tötet so viele wie möglich und bringt mir ihre Bälge als Beweis ihres Ablebens.", sourceObjective = "Nalpak möchte 10 Deviatbälge.", progress = "Wie viele dieser Bestien konntet Ihr töten?", completion = "Eure Bemühungen werden nicht unbemerkt bleiben, {name}.\n\nVielen Dank für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26873] = { id = 26873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbeugende Maßnahmen", description = "In diesen Höhlen befindet sich ein Kraut mit unvorstellbaren Kräften, {name}. Möchtet Ihr mir helfen, es zu sammeln?\n\nEs handelt sich um eine seltene Blume mit Namen Schlangenflaum. Ich glaube, dass große Mengen davon weitere Alpträume, wie den von Naralex in Zukunft verhindern können.\n\nLeider findet man Schlangenflaum nur in den dunkelsten Ecken dieses Ortes.", sourceObjective = "Nalpak möchte, dass Ihr 5 Schlangenflaum sammelt.", progress = "Ich bin gespannt, ob Ihr genug Schlangenflaum sammeln könnt.", completion = "Gut gemacht, {name}. Hoffentlich können wir sie benutzen, um weitere Alpträume zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26874] = { id = 26874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auferstehung von Naralex", description = "Jetzt, da die Giftzahnlords tot sind, sprecht mit Muyoh. Er wird Euch dabei helfen, Naralex aufzuwecken und diesen Alptraum zu beenden.", sourceObjective = "Sprecht mit Muyoh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26875] = { id = 26875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsterbliches Zwielicht", description = "Die Schattenhammerkultisten sind hier! Sie versuchen, das Ritual zu verhindern! Geht zurück in die Kammern und wehrt sie ab!", sourceObjective = "Tötet 12 Zwielichteindringlinge und 1 entweihten Erdwüter.", completion = "Immer mehr Zwielichttruppen strömen herein, aber offenbar können die Verteidiger des Irdenen Rings ihrer Herr werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26876] = { id = 26876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Weltensäulenfragment", description = "Es wird Zeit, {name}. Wir haben Abyssion erspäht, auf dem Weg zu seinem Hort.\n\nDer Schattenhammer dachte wahrscheinlich, dass das Fragment sicher ist, wenn ein Drache es bewacht, aber ich habe genug Drachen gesehen und kenne ihre einzige Schwäche. Stolz.\n\nAbyssion wird nicht vor einem Kampf mit uns kläglichen Sterblichen davonlaufen.\n\nStellt das Banner des Irdenen Rings in die Mitte seines Horts. Wenn wir ihn besiegt haben, bringt das Fragment zu Maruut. Wir müssen die Weltensäule so bald wie möglich reparieren.", sourceObjective = "Stellt das Banner des Irdenen Rings in der Mitte von Abyssions Hort auf, tötet ihn und nehmt das erste Weltensäulenfragment an Euch.", progress = "{name}! Ihr seid zurückgekehrt!", completion = "Eure Bemühungen, die Weltensäule zu reparieren, sind von unschätzbarem Wert, {name}. Sobald der Tempel der Erde wieder stabil ist, wird auch der Riss zwischen den Welten sich stabilisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26878] = { id = 26878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jünger von Naralex", description = "{class}, das Brachland war einst einer der schönsten Orte in ganz Kalimdor. Es war vielversprechend und voller Leben.\n\nWie Ihr seht, ist das nicht länger der Fall. Es ist ein Land voller Qual und Zwietracht.\n\nDie Jünger von Naralex wollen die Höhlen des Wehklagens säubern und sie in ihrer früheren Schönheit wiederherstellen. Sprecht in den Höhlen des Wehklagens hinter dem Eingang mit Nalpak.", sourceObjective = "Sprecht in den Höhlen des Wehklagens mit Nalpak.", completion = "Ja, {class}? Was bringt Euch an diesen Ort?", sourceObjectiveStatus = "unverified-source-field" }
quests[26881] = { id = 26881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Thaelrid", description = "Finstere Dinge gehen an diesem Ort vor sich, {name}. Wir fürchten, dass die Gerüchte über eine Zusammenarbeit der Naga mit dem Schattenhammer wahr sind.\n\nIch habe Thaelrid, einen unserer besten Späher, ausgeschickt, um der Angelegenheit nachzugehen. Doch er ist nicht zurückgekommen.\n\nFindet ihn. Wenn er noch lebt, findet heraus, was er entdeckt hat.", sourceObjective = "Sucht Späher Thaelrid auf.", completion = "Gut, dass Ashelan Euch geschickt hat. An diesem Ort der Verderbnis wird ein finsterer Plan geschmiedet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26882] = { id = 26882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkerei in der Tiefschwarzen Grotte", description = "Meine Kräfte haben mich verlassen. Ich brauche Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, ein Diener des Alten Gottes, erhob sich aus den Wassern.\n\nDie Kultisten des Schattenhammers haben sich mit den Naga verbündet, um diesen Ort zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nErschlagt Kelris und bringt seinen Kopf zu Ashelan.", sourceObjective = "Holt den Kopf von Zwielichtfürst Kelris.", progress = "Schön, Euch wiederzusehen, {name}. Welche Neuigkeiten bringt Ihr?\n\nWar Euer Vorstoß erfolgreich? Habt Ihr Thaelrid gefunden?", completion = "Kelris hat sich uns schon seit geraumer Zeit entzogen.\n\nOffenbar war Kelris immer dann beteiligt, wenn sich in dieser Gegend das Böse zeigte. Wir glaubten seit einiger Zeit, er sei entweder tot oder vermisst.\n\nAber das hier passt alles wunderbar zusammen. Indem Ihr seiner Herrschaft ein Ende gesetzt habt, rettet ihr die Leben vieler unschuldiger Menschen.\n\nEinem Diener eines Alten Gottes Opfer zu bringen, nur um sich persönliche zu bereichern ist mehr als verabscheuungswürdig!\n\nIhr habt eine große Tat vollbracht, {name}. Ich danke Euch in Namen Eschentals.\n\nIch wünschte nur, Thaelrid hätte überlebt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26883] = { id = 26883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stunde der Finsternis", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder des Schattenhammers, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass der Schattenhammer sich mit den Naga verbündet hat und sich ihre Anhänger hier zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen den Schattenhammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", sourceObjective = "Bringt 10 Zwielichtanhänger an Euch.", progress = "Die Tiefschwarze Grotte war einst ein uralter Tempel der Nachtelfen. Er beherbergte einen äußerst mächtigen Mondbrunnen. Wer weiß, was der Schattenhammer hier Böses ausbrütet.\n\nHabt Ihr Fortschritte dabei gemacht, den Tempel von ihrer Anwesenheit zu befreien?", completion = "Zweifellos seid Ihr tapfer und von noblem Geblüt, {name}. Wir und alle Menschen in Eschental preisen Euch für Eure Bemühungen gegen das Böse.", sourceObjectiveStatus = "unverified-source-field" }
quests[26884] = { id = 26884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforschung der Verderbnis", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. Versucht die Hirnstämme nicht zu beschädigen während Ihr sie tötet, ich brauche ausschließlich makellose Exemplare.", sourceObjective = "Sammelt 8 verderbte Hirnstämme.", progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Tiefschwarzen Grotte kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr habt zweifellos großen Gefahren getrotzt, um diese hier zu bekommen.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, {name}.\n\nWenn Ihr mich nun entschuldigen würdet, ich habe viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26885] = { id = 26885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen in der Tiefe", description = "Wie Ihr vielleicht wisst, ist es meine Pflicht als Auszubildende, Lehren für meine Vorgesetzten zusammenzutragen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die schlafenden Alten Götter erwecken können, wenn sie missbraucht werden.\n\nEs kursieren Gerüchte um einen alten Text, das 'Manuskript von Lorgalis', das sich tief auf dem Boden des Teichs von Ask'ar befindet, in einer eingedellten Eisentruhe. Dieser Ort ist die ehemalige Heimat unserer längst verstorbenen Ahnen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht das Manuskript, bitte. Ich verfüge nicht über genug Fähigkeiten, um weiter voranzuschreiten!", sourceObjective = "Findet das Manuskript von Lorgalis.", progress = "Eure Aufgabe ist keine leichte, mein Freund.\n\nAber wenn Ihr mir das Manuskript besorgt, {name},...dann gebührt Euch eine großzügige Belohnung und wir erhalten ein besseres Verständnis davon, was der Schattenhammer und die Naga im Schilde führen.", completion = "Ihr habt das Manuskript gefunden! Was für ein Freudentag! Ich werde es gründlich studieren und alles lernen, was es zu lernen gibt.\n\nIch werde es doch noch zur Schildwache bringen!\n\nIhr habt uns einen größeren Dienst erwiesen, als Ihr ahnt, {name}. Ich hoffe, dieses Geschenk zeigt Euch meine Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26886] = { id = 26886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gebrüllt", description = "Das fiese Schiff auf der Nordseite der Bucht feuert ständig seine Kanonen auf uns ab. Es ist ja ganz lustig zuzusehen, wie die Goblins von Kanonenkugeln getroffen werden, aber einige meiner Gnomfreunde werden auch getroffen!\n\nEs wäre wirklich sehr nett, wenn Ihr es schafft, Euch an den Kanonen vorbei auf das Schiff zu begeben. Da ist ein gemeiner alter Zuchtmeister, der die anderen Deckmatrosen anschreit. Ich bin sicher, wenn Ihr ihn verprügelt oder tötet, werden sie nicht länger auf uns schießen!", sourceObjective = "Tötet den Zuchtmeister der Südmeerfreibeuter.", completion = "Wunderbar! Ich hoffe, Ihr wurdet nicht von zu vielen Kanonenkugeln getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26887] = { id = 26887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir füllen uns die Taschen", description = "Ich weiß, wir sind hier um uns mit den Dampfdruckgoblins anzufreunden, aber diese grässlichen Bilgewassergoblins sind so unverschämt.\n\nWarum? Ich sah gerade, wie eine Gruppe von ihnen aus den Zähnen von Musketieren und Schlägern der Südmeerfreibeuter Goldfüllungen herausrissen. Glauben die, sie können das einfach für sich behalten?\n\nNatürlich wäre es nett, wenn wir die Piraten selbst umbringen, ihre Füllungen selbst herausnehmen und dann den Dampfdruckgoblins einige als Dankesgeschenk übergeben! Geht dort hinunter und kommt den Goblins zuvor.", sourceObjective = "Sammelt 20 Goldfüllungen von Musketieren oder Schlägern der Südmeerfreibeuter.", progress = "Habt Ihr die Füllungen?", completion = "Noch mehr Gold! Wir werden Mister Noggenfogger bestimmt etwas davon abgeben, damit unsere Beziehung auch in Zukunft reibungslos verläuft.\n\nNur ein kleiner Teil wird nach Gnomeregan für die Entwicklung experimenteller Waffen zurückgebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26888] = { id = 26888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum in der Tiefe", description = "In den dunkelsten Winkeln der Tiefschwarzen Grotte ist ein Monster dort erschienen, wo die Alten Götter lauern. Wir kennen es nur als Aku'mai.\n\nDie Alten Götter und ihre Diener sind eine große Gefahr für unsere Welt. Vor langer Zeit herrschten sie über Azeroth und ich fürchte, dass sie diese Herrschaft erneut anstreben, auch wenn sie Azeroth bei dem Versuch zerstören würden.\n\n{name}, Aku'mai ist eine Kreatur unbeschreiblicher Alpträume. Wir können einfach nicht dulden, dass sie weiter existiert. Vernichtet sie.", sourceObjective = "Tötet Aku'mai.", completion = "Das Ungeheuer ist tot. Ich spüre, wie seine dunkle Gegenwart für immer vergeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26889] = { id = 26889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug der Fröhlichkeit", description = "Meine Güte, wir haben hier ganz schön aufgeräumt!\n\n<Kelsey räuspert sich.>\n\nHört mal, {name}, ich freue mich darauf, diese Tötungskiste zu verlassen, damit ich endlich von diesen Goblins wegkomme und die aufgesetzte Fröhlichkeit ablegen kann. Wenn Ihr hier in der Gegend die Interessen von Gnomeregan weiter vertreten möchtet - und damit auch die der Allianz -, geht vom Außenposten der Schmuggler nach Süden.\n\nSprecht dort mit Zeke Scheuerschuh und denkt daran, dass jegliche Arbeit für die Dampfdruckgoblins uns dabei helfen wird, die Bilgewassergoblins endgültig aus Tanaris zu vertreiben.", sourceObjective = "Sprecht am Außenposten der Schmuggler mit Zeke Scheuerschuh.", completion = "Wisst Ihr, eigentlich bin ich ja nicht beeindruckt, wenn ich einen {race} sehe, aber ich habe gehört, was Ihr für Dampfdruck getan habt. Ihr seid in Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26890] = { id = 26890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz von Aku'mai", description = "Im Eingangsbereich der Tunnel der Tiefschwarzen Grotte findet man überall an den Höhlenwänden große Saphiransammlungen. Uns ist aufgefallen, dass die Naga zur selben Zeit angefangen haben, diese Kristalle abzubauen, als sich auch ihre Waffen stark verbessert haben.\n\nDie Kristalle besitzen offenbar große Elementarkraft und wenn man sie zweckentfremdet, könnten sie eine mächtige Komponente für meine Schmiedekunst sein.\n\nWerdet Ihr mir helfen, {name}? Die Tiefschwarze Grotte liegt am Zoramstrand nördlich unseres Außenpostens.", sourceObjective = "Sammelt 20 Saphire von Aku'mai.", progress = "Wie läuft Eure Suche nach den Kristallen, {name}? Meint Ihr wir können daraus einen Gegenstand anfertigen, mit dem wir die Naga aufhalten können?", completion = "Ausgezeichnet! Die sind genau richtig. Hier habt Ihr eine Belohnung für Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26891] = { id = 26891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inmitten der Ruinen", description = "Die Anhänger des Schattenhammers sind hier in die Mondschreinruinen eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen.\n\n{name}, findet die Zwielichtagenten hier, dann sucht den Tiefenstein der Ruinen. Er dürfte sich irgendwo unter Wasser befinden, wahrscheinlich direkt vor ihren Nasen. Darin ist ein Tiefenkern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", sourceObjective = "Findet den Tiefenkern.", progress = "Konntet Ihr den Tiefenkern finden? Ohne ihn haben wir keine Ahnung, was genau die Anhänger des Schattenhammers da unten vorhaben.", completion = "Genau das brauche ich! Ein Tiefenkern ist ein unglaublicher Quell an Informationen, aus denen wir guten Nutzen ziehen können. Was auch immer die Schattenhammerkultisten da unten im Schilde führen - und glaubt mir, wenn ich sage, dass es nichts Gutes sein kann - meine Kollegen und ich werden es jetzt aufdecken.\n\nIhr habt Eure Sache hier heute gut gemacht. Der Irdene Ring ist Euch sehr dankbar für Eure Hilfe. Ihr habt außerdem der Horde als Ganzes geholfen, und darauf solltet Ihr stolz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26892] = { id = 26892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den tiefsten Tiefen", description = "Die Naga und der Schattenhammer arbeiten zusammen, um all den Fortschritt, den wir in dieser Gegend erzielt haben, zunichte zu machen. Schlimmer noch, Je'neu sagte mir, dass er die Gegenwart eines Alten Gottes tief unter uns spürt.\n\nWenn sie Chaos haben wollen, dann werden wir ihnen genau das geben.\n\n{name}, schlagt ihre stärksten Krieger und dann werden wir sehen, wie ihnen das gefällt.\n\nSeid bei Eurer Suche vorsichtig, die Tiefschwarze Grotte ist voller Unterwasserpassagen und Seitengänge, in denen sich Eure Ziele verbergen können.", sourceObjective = "Vernichtet Ghamoo-Ra, Lady Sarevess und Gelihast.", progress = "Sagt mir, {name}, rennen sie panikerfüllt umher? Sie bekommen genau das, was sie verdienen.", completion = "Ich kann ihre Schreie von hier aus hören! Vielleicht wird ihnen dies zeigen, wie töricht es ist, sich die Rückkehr eines Alten Gottes zu wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26893] = { id = 26893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Es gibt eine Aufgabe, für die Ihr perfekt geeignet seid, {class}. Wir müssen die Gegend um die Tiefschwarze Grotte herum gegen die Allianz sichern, die den Außenposten von Zoram'gar im Westen von hier bedroht.\n\nGeht zur Tiefschwarzen Grotte nördlich des Außenpostens von Zoram'gar und sprecht mit Je'neu vom Irdenen Ring. Er wird viel für Euch zu tun haben.", sourceObjective = "Sprecht mit Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[26894] = { id = 26894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Die Naga verspotten uns mit ihrem offenen Widerstand. Wir werden sie und ihre Verbündeten endgültig aus diesen Landen vertreiben.\n\nReist nach Norden zu der Tiefschwarzen Grotte und sprecht mit Je'neu Sancrea. Er hat sie bereits betreten.\n\nÜbrigens, nehmt Euch vor Zeya in Acht. Sie ist manchmal etwas... launisch.", sourceObjective = "Sprecht mit Je'neu Sancrea.", completion = "Hat Kommandant Grimmfang Euch geschickt? Ich habe ihn gebeten, passende Rekruten zu finden, die mir hier helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26895] = { id = 26895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Donnerkuppel!", description = "Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? \n\nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anzeigen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt! Macht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden weiter!", sourceObjective = "Sprecht in Gadgetzan mit Doktor Haudenlukas.", completion = "Noch ein stolzer {class}, angelockt vom Versprechen des Ruhms! Von Reichtum! Von GEWALT!\n\nJa, willkommen, mein Freund. Willkommen in der DONNERKUPPEL!", sourceObjectiveStatus = "unverified-source-field" }
quests[26896] = { id = 26896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Donnerkuppel!", description = "Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? \n\nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anklagen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt!\n\nMacht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden!", sourceObjective = "Sprecht in Gadgetzan mit Doktor Haudenlukas.", completion = "Noch ein stolzer {class}, angelockt vom Versprechen des Ruhms! Von Reichtum! Von GEWALT!\n\nJa, willkommen, mein Freund. Willkommen in der DONNERKUPPEL!", sourceObjectiveStatus = "unverified-source-field" }
quests[26897] = { id = 26897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Obwohl wir hier ziemlich auf dem Präsentierteller stehen, sind wir noch sicher im Vergleich zu unseren Freunden in der Tiefschwarzen Grotte! Sie sind nur einige Fuß entfernt von den tödlichsten Nagatruppen des Landes. Sprecht mit Schildwache Aluwyn und gebt ihnen die Hilfe, die sie so dringend benötigen!", sourceObjective = "Sprecht mit Schildwache Aluwyn.", completion = "Elune sei Dank - Ihr seid hier! Wir können jede Hilfe gebrauchen, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26898] = { id = 26898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Ich mache mir sehr viel aus diesen Wäldern, {class}. Es sieht wirklich nicht gut aus hier, aber ich würde mich lieber der Horde allein entgegenstellen, als zuzusehen, wie sie sich ihren Weg durch die Bäume hacken und schneiden.\n\nReist nach Westen zur Tiefschwarze Grotte. Sobald Ihr sie betretet, sucht Schildwache Aluwyn auf. Sie ist eine enge Vertraute, die Hilfe benötigt. Die \n\nOrcs im Außenposten von Zoram'gar bedrohen ihre Position in diesem Augenblick. Wenn sie die Tiefschwarze Grotte einnehmen, werden sie bestimmt jeden Baum fällen, um ihren Wahnsinn zu schüren.", sourceObjective = "Sprecht mit Schildwache Aluwyn.", completion = "Elune sei Dank - Ihr seid hier! Wir können jede Hilfe gebrauchen, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26899] = { id = 26899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes", description = "Kultisten...Opfer...Macht...\n\nFeind...erwacht...\n\nAlter Gott...sperrt...mich ein...\n\nLord...Kelris...\n\nBringt Kopf...Rache...\n\nAUSLÖSCHEN!!!", sourceObjective = "Verschafft Euch den Kopf von Zwielichtfürst Kelris.", progress = "Rache...Belohnung...", completion = "<Der flammende Vernichter scheint sich zu konzentrieren.>\n\nIch schone Euer Leben für Eure Hilfe, {race}. Geht jetzt...bevor ich es mir...anders überlege.", sourceObjectiveStatus = "unverified-source-field" }
quests[26901] = { id = 26901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go, Go, Guano!", description = "Die Fledermäuse aus dem Kral der Klingenhauer produzieren eine äußerst seltsame, natürliche Substanz. Der Gestank ihres Guano scheint die Stacheleber in mörderische Raserei zu versetzen - und hier stinkt es gewaltig danach!\n\nIhr müsst die Fledermaushöhle finden und mir eine passende Probe bringen. Wenn wir die Auswirkungen umkehren und ein Gegengift herstellen können, können wir die Stacheleber vielleicht retten.", sourceObjective = "Sammelt 1 Häufchen Kralguano", progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt. Konntet Ihr etwas Kralguano beschaffen?", completion = "Gut gemacht! Das ist genau das, was wir brauchen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26903] = { id = 26903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix der Importeur", description = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer auf die schnelle Mark aus, wie man so sagt. Ich habe Wind davon bekommen, dass sich Schweineschnauzen unglaublich gut auf dem Markt verkaufen lassen. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, soll es Euer Schaden nicht sein.", sourceObjective = "Führt Willix den Importeur aus dem Kral der Klingenhauer hinaus.", completion = "Nochmals danke, Freund! Ich sagte doch, es würde sich für Euch lohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26904] = { id = 26904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammen nutzbar machen", description = "Nur wenige Menschen, besonders unter unseren Verbündeten, sind wirklich in der Lage, die Natur der Macht nachzuvollziehen, die wir besitzen. Sie meiden uns, weil sie zu schwach sind, das Wissen, das wir besitzen, richtig anzuwenden.\n\nLasst mich Euch eine Beschwörung zeigen, die ich nützlich finde. Dieser Zauber mit Namen Feuerbrand setzt Euer Ziel in Flammen und verursacht Schaden sofort und über einen gewissen Zeitraum. Setzt ihn weise ein, {name}, und Eure Feinde werden lernen, Euch zu fürchten.", sourceObjective = "Sprecht mit Saripal Schmauchbräu und lernt Feuerbrand. Dann wirkt Feuerbrand 5-mal auf eine Trainingsattrappe nahe des Eingangs zu Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26905] = { id = 26905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggans Auftrag", description = "Hört gut zu, Sterblicher.\n\nDie Stacheleber sind meine Kinder. Dieses Land ist von meinem Blut durchzogen.\n\nCharlga Klingenflanke hat meine Kinder in die Dunkelheit geführt, nachdem sie von der Geißel in den Wahnsinn getrieben wurde.\n\nTötet sie, {name}. Tötet sie und öffnet meinen Kindern die Augen.\n\nGebt den Stachelebern die Chance, wieder zu ihren edlen Wurzeln zurückzukehren.\n\nLasst sie meinen Segen wieder verdienen. Bringt mir ihr Herz!!!", sourceObjective = "Nehmt Charlga Klingenflanke das Herz.", progress = "<Der Geist von Agamaggan betrachtet Euch geduldig.>", completion = "Nehmt dieses Geschenk. Ihr habt Euch heute wahrlich meinen Segen verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[26906] = { id = 26906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan", description = "Ich spüre eine ungeheure Macht in diesen gewundenen Dornen, {name}. Die ganze Gegend wird durch ihre Gegenwart belebt.\n\nEs muss der Geist von Agamaggan sein! Er war eins der ersten und mächtigsten Wesen, die je gelebt haben - die Stacheleber verehren ihn zutiefst.\n\nJede Ranke, die Ihr im Lande seht, stammt von seinem Blut - von dem Opfer, das er brachte, um Azeroth während des Kriegs der Ahnen zu retten.\n\nWenn ein Wesen die Stacheleber wieder zu ihren edlen Wurzeln führen kann, dann er.\n\nIhr müsst ihn finden.", sourceObjective = "Sprecht mit dem Geist von Agamaggan.", completion = "<Der Geist von Agamaggan betrachtet Euch. Eine uralte Stimme ertönt in Eurem Kopf.>\n\nIch habe darauf gewartet, dass Ihr herkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26907] = { id = 26907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht sie nieder!", description = "Oberanführer Rammhauer und die Totenköpfe machen für den Krieg mobil. Es hat viele Späher das Leben gekostet, aber wir haben erfahren, mit Hilfe welcher Waffe sie den Rest des Brachlands übernehmen wollen.\n\nMan nennt ihn Agathelos den Tobenden. Er ist ein gewaltiger Eber mit schwerer Rüstung, dem man zwangsweise Kralfledermausguano verabreicht hat, das Raserei auslöst.\n\n{race}, Ihr müsst sie aufhalten, bevor sie unschuldige Leben vernichten!", sourceObjective = "Tötet Aggem Dornfluch, Todessprecher Jargba, Oberanführer Rammhauer und Agathelos den Tobenden.", completion = "Ihr habt Eure Sache heute gut gemacht. Agathelos hätte in seiner Wut viele Leben ausgelöscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26908] = { id = 26908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorn im Auge", description = "Mankriks Wut über seine tote Frau bietet Anlass zu weiterer Sorge, {class}.\n\nDie Stacheleber im Kral der Klingenhauer sind weitaus skrupelloser und hasserfüllter als Mankrik sich vorstellen konnte.\n\nIhr solltet nach Süden reisen und mit meinem alten Freund Auld Steinkeil sprechen. Er arbeitet daran, ihrer Raserei ein Ende zu bereiten, bevor das ohnehin geschwächte Land noch mehr leidet.", sourceObjective = "Sprecht mit Auld Steinkeil.", completion = "Nur ein Veteran wie Ihr könnte den Gefahren, die hier lauern, trotzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26909] = { id = 26909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steinsplitter", description = "Uralte Steine sind über das ganze Land verstreut. Die Elemente strömen in Scharen zu ihnen und umringen sie schützend.\n\nEs handelt sich um Orte großer Macht. Der größte von ihnen liegt westlich von Hammerfall. Keine Seele dringt dort widerrechtlich ein, aber wenn Ihr alleine dort hingeht, hört ihr das Flüstern der Erde.\n\nIch bin schon lange nicht mehr dort gewesen, aber unsere Grunzer berichteten mir, dass das Flüstern wieder begonnen hat. Würdet Ihr für mich nachsehen? Werdet ihr nachsehen, ob die Steine immer noch sprechen?", sourceObjective = "Untersucht die Splitter von Myzrael.", completion = "<Die Splitter pulsieren sanft und ein Flüstern hallt in Eurem Kopf wider.>\n\nHilfe...", sourceObjectiveStatus = "unverified-source-field" }
quests[26910] = { id = 26910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzter Brief", description = "Mir wurde aufgetragen, Euch so bald wie möglich, nachdem Ihr von der Angelegenheit mit den Spionen des Schwarzfels zurückgekehrt seid, hierauf aufmerksam zu machen, {name}. Es scheint sich um einen Brief zu handeln, der mit dem Siegel von Ashley Blank, unserer Jägerlehrerin, versehen ist. Ich würde keine Zeit verlieren und ihn sofort lesen, bevor Ihr hier in der Abtei irgendetwas anderes macht.", sourceObjective = "Lest den geätzten Brief und sprecht im Nordhaintal mit Ashley Blank.", progress = "Hallo, {name}. Gibt es etwas, das ich für Euch tun kann?", completion = "Ihr habt meine Nachricht also erhalten? Ausgezeichnet. Ihr habt Euch im Umgang mit den Orcs als recht geschickt erwiesen. Während Ihr immer mächtiger werdet, werde ich Euch einige neue Techniken lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26911] = { id = 26911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzraels Geschichte", description = "Als der Stein in Schweigen verfällt, bleibt Ihr mit einem vagen Unbehagen zurück. Etwas stimmt nicht.\n\nVielleicht solltet Ihr Zaruk erzählen, was Ihr bis jetzt getan habt.", sourceObjective = "Kehrt in das Arathihochland nach Hammerfall zu Zaruk zurück.", completion = "Ich weiß, {name}. Ich hätte Euch nicht schicken dürfen.\n\nVergebt mir... Das Flüstern der Stimmen aus der Vergangenheit ist manchmal zu stark.", sourceObjectiveStatus = "unverified-source-field" }
quests[26912] = { id = 26912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die entfesselte Prinzessin", description = "Myzrael ist eine Betrügerin. Sie ist eine uralte Macht, die vor langer Zeit unter Verschluss genommen wurde und da sollte sie auch bleiben.\n\nIhr müsst an den Splittern von Myzrael, wo Ihr zuerst mit ihr gesprochen habt, die Konfrontation mit ihr suchen. Ruft sie mit dieser Schriftrolle herbei. Wenn sie dann in voller Größe an der Oberfläche angelangt ist, besiegt sie. Dann nehmt die geisterhaften Fesseln von ihrem Körper und legt sie auf die Splitter, damit sie wieder vollkommen gebunden ist.\n\nViel Glück, {name}... Möge die Vergangenheit Euch nicht mehr beunruhigen.", sourceObjective = "Ruft Myzrael an den Splittern von Myzrael herbei und besiegt sie.", progress = "Die Splitter von Myzrael sind jetzt seltsam still.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, erschallt von tief unten ein unmenschliches Heulen. Auf den Schrei folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht länger Gefühle der Wärme und Sicherheit hervor, wie sie es zuvor taten. Jetzt sind sie erfüllt von einer feindseligen Aura... als ob das Ding unter ihnen der Außenwelt nicht wohlgesinnt wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[26913] = { id = 26913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Kampf stürmen", description = "Jetzt, da Ihr Gelegenheit hattet, Eure Fähigkeiten im Kampf zu erproben, wird es Zeit, Euch eine neue Kampfkunst zu zeigen: Sturmangriff. Es ist wichtig, dass Ihr als Krieger jeden vorhandenen Vorteil nutzt, um Euch im Kampf die Oberhand zu verschaffen.\n\nEs gibt keinen besseren Weg, als in den Kampf zu stürmen und den Gegner zu betäuben. Ich werde Euch zeigen, wie man das macht und dann möchte ich, dass Ihr es bei einer der Trainingsattrappen ausprobiert, die sich südlich vom Eingang der Abtei befinden.", sourceObjective = "Sprecht mit Llane Bershere und erwerbt die Fähigkeit 'Sturmangriff'. Dann übt die Anwendung von 'Sturmangriff' an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[26914] = { id = 26914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbrand", description = "Wir müssen hier in der Abtei und in ihrer Umgebung vorsichtig mit dem sein, was wir sagen, aber lasst Euch dadurch nicht vom Pfad der Macht abbringen.\n\nIch möchte Euch einen meiner Lieblingszauber zeigen. Er setzt einen Gegner in Brand, fügt ihm sofort Schaden zu und richtet über einen gewissen Zeitraum noch weiteren Schaden an. Ich werde Euch zeigen, wie man das macht und dann möchte ich, dass Ihr es bei einer der Trainingsattrappen ausprobiert, die sich südlich vom Eingang der Abtei befinden.", sourceObjective = "Sprecht mit Drusilla La Salle und erwerbt die Fähigkeit 'Feuerbrand'. Dann übt die Anwendung von Feuerbrand 5 Mal an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", progress = "Nun, habt Ihr es ausprobiert?", completion = "Wie ich sehe, beherrscht Ihr Feuerbrand bereits. Ich freue mich darauf, Euch in Zukunft weiter zu unterrichten. Vergesst nicht, für weitere Lektionen zurückzukehren, während Ihr immer mächtiger werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26915] = { id = 26915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Einschnitte", description = "Bisher kennt Ihr die Grundlagen für den Kampf als Schurke, aber ich möchte Euch eine neue Fähigkeit lehren. Als Schurken sind wir dafür bekannt, Ketten von Kampftechniken ausführen zu können und uns den mächtigsten Schlag bis zum Ende aufzubewahren.\n\nLasst mich Euch die Grundzüge von 'Ausweiden' erklären. Nachdem Ihr einige Male 'Finsterer Stoß' ausgeführt habt, könnt Ihr mit 'Ausweiden' angreifen, um Euren Feind noch härter zu treffen. Ich möchte, dass Ihr es bei einer der Trainingsattrappen ausprobiert, die sich südlich vom Eingang der Abtei befinden.", sourceObjective = "Sprecht mit Jorik Kerridan und erwerbt die Fähigkeit 'Ausweiden'. Dann sucht eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain und übt Ausweiden 3 Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26916] = { id = 26916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung des Arkanen", description = "Als Magier werdet Ihr mit wachsendem Verständnis eine Vielzahl von Zaubern lernen. Ich möchte Euch eine neue Technik zeigen, die es Euch erlaubt, Salven arkaner Energie auf Euren Gegner abzufeuern: Arkane Geschosse. Ihr werdet diesen Zauber nicht immer wirken können, aber jedes Mal, wenn Ihr einen anderen Zauber wirkt, besteht die Chance, dass die Möglichkeit zur Anwendung von 'Arkane Geschosse' sich auftut. Ich werde Euch zeigen, wie man das macht und dann möchte ich, dass Ihr es bei einer der Trainingsattrappen ausprobiert, die sich südlich vom Eingang der Abtei befinden.", sourceObjective = "Sprecht mit Khelden Bremen und erwerbt die Fähigkeit 'Arkane Geschosse'. Dann übt die Anwendung von 'Arkane Geschosse' 2 Mal an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[26917] = { id = 26917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Ich hörte, dass Ihr geholfen habt, einige der Orcs auszumerzen. Ihr habt bewiesen, dass Ihr Euch im Kampf zu verhalten wisst.\n\nIch möchte Euch eine neue Fähigkeit zeigen. Ich werde Euch zeigen, wie sie ausgeführt wird und dann möchte ich, dass Ihr sie bei einer der Trainingsattrappen ausprobiert, die sich südlich vom Eingang der Abtei befinden.", sourceObjective = "Sprecht mit Ashley Blank und erwerbt die Fähigkeit 'Zuverlässiger Schuss'. Dann sucht eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain und übt 'Zuverlässiger Schuss' 5 Mal.", completion = "Ich wusste, Ihr würdet 'Zuverlässiger Schuss' schnell meistern. Ich freue mich darauf, Euch neue Techniken zu zeigen, wenn Ihr weitere Erfahrungen als Jäger gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26918] = { id = 26918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Lichts", description = "Ich möchte Euch einige Techniken lehren, mithilfe derer Ihr die Macht des Lichts zur Verstärkung Eurer Kampfkünste nutzen könnt.\n\nDie erste Technik sieht vor, das Siegel der Rechtschaffenheit anzuwenden. Während Ihr unter dem Einfluss des Siegels steht, werden all Eure Nahkampfangriffe zusätzlichen Heiligschaden verursachen.\n\nDie zweite Fähigkeit - 'Richturteil' - kann regelmäßig angewendet werden, um die Macht des Siegels zu entfesseln und Schaden zu verursachen.", sourceObjective = "Sprecht mit Bruder Sammuel und erwerbt die Fähigkeiten 'Siegel der Rechtschaffenheit' und 'Richturteil'. Wirkt 'Siegel der Rechtschaffenheit' auf Euch und benutzt dann 'Richturteil' auf eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", progress = "Nun, habt Ihr es ausprobiert?", completion = "Ihr lernt schnell, {name}. Kehrt zu mir zurück, wenn Ihr stärker geworden seid und ich werde Euch mehr darüber lehren, wie Ihr das Licht zur Vernichtung Eurer Feinde und zur Stärkung Eurer Verbündeten anwenden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26919] = { id = 26919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verwundeten heilen", description = "Als <Priester/Priesterin> müsst Ihr Euch unter anderem um die Verwundeten kümmern. Mit der Kraft des Lichts könnt Ihr jene retten, die sonst sterben würden. Außerdem könnt Ihr die Heilung der Wunden beschleunigen.\n\nIch möchte Euch eine einfache, schnelle Technik lehren, mit der Ihr einen Verbündeten rasch heilen könnt.\n\nIch werde Euch zeigen, wie man das macht und dann möchte ich, dass Ihr mit dem Zauber die Verletzungen verwundeter Lehrlinge in der Abtei behandelt.", sourceObjective = "Sprecht mit Priesterin Anetta und erwerbt die Fähigkeit 'Blitzheilung'. Dann benutzt 'Blitzheilung' 5 Mal, um verwundete Lehrlinge in der Abtei von Nordhain zu behandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[26920] = { id = 26920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Beeilt Euch, {name}... Wir haben keine Zeit zu verschwenden.\n\nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. Fürstin Sylvanas hat einen ihrer besten Todesritter entsandt, um den Sturmangriff für ihre Sache zu leiten. Dennoch bin ich sicher, dass er jede Hilfe gebrauchen kann. Arthas ist tot, deshalb ist jetzt der perfekte Zeitpunkt für die Verlassenen, Andorhal einzunehmen.\n\nSprecht mit dem Fledermausführer Timothy Cunningham, wenn Ihr bereit seid, und er wird Euch den nächsten Flug dorthin verschaffen.", sourceObjective = "Meldet Euch in den Westlichen Pestländern innerhalb Andorhals bei Koltira Todesweber.", completion = "Wurde auch Zeit, dass Ihr eintrefft, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26921] = { id = 26921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst die Geißel... dann die Allianz", description = "Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein alter Widerpart, Thassarian, führt die Streitkräfte der Allianz an. Wenn wir Andorhal für uns gewinnen wollen, müssen wir beide besiegen. Doch wir werden sicherlich nicht beide gleichzeitig angreifen können.\n\nIch kenne Thassarian gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden dasselbe tun.\n\nSchaltet die schwächeren ausgedörrten Geißeldiener aus, damit sie zahlenmäßig unterlegen sind. Die Allianz wird unsere Rache erst später zu spüren bekommen.", sourceObjective = "Tötet 15 ausgedörrte Geißeldiener in Andorhal.", completion = "Ihr seid zwar nicht besonders schnell, aber wenigstens enttäuscht Ihr mich nicht.\n\nSehr schön. Sobald die Zeit reif ist, werde ich noch eine wichtigere Aufgabe für Euch haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26922] = { id = 26922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unendliche Fluss", description = "Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten... eine Armee von Schwächlingen, die Euch eher überrennen als übermannen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!\n\n<Jearl reicht Euch ein paar Granaten.>\n\nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.", sourceObjective = "Benutzt Jearls Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.", completion = "Diese Granaten sind Sprengstoff, mehr nicht. Selbst als Mitglied der Königlichen Apothekervereinigung sehe ich ein, dass sich manche Probleme nicht dadurch lösen lassen, mehr Seuche nach ihnen zu werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26923] = { id = 26923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen", description = "Ihr Narren werdet die Geißel niemals besiegen, solange diese Monstrositäten herumlaufen. Koltira quasselt ständig davon, sie zahlenmäßig unterlegen zu machen, aber die beste Waffe der Geißel hier in Andorhal findet man unter diesen herumtorkelnden Schlägern, die meine Todeswachen wie Puppen umherschleudern.\n\nDas hat jetzt ein Ende.\n\n{name}, geht auf das Schlachtfeld und vernichtet diese Monster.", sourceObjective = "Vernichtet 6 aufgeschlitzte Ungetüme in Andorhal.", completion = "Jetzt, da die Ungetüme aus dem Weg sind, ist uns der Sieg gegen die Geißel gewiss.\n\nUnsere Chancen gegen die Allianz sind momentan nicht ganz so günstig... Aber das soll Euch nicht kümmern. Jedenfalls noch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26924] = { id = 26924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "Scholomance ist eine der letzten verbliebenen Bastionen der Geißel im Westen von Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld aufgetaucht.\n\nDas wird sein letzter Fehler sein.\n\nIhr findet Gandling auf einem Platz in der Nähe des südlichen Stadtrands. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch unterstützen, damit er sein Ende findet.", sourceObjective = "Tötet Dunkelmeister Gandling in Andorhal.", completion = "Ausgezeichnete Arbeit, {name}. Jetzt, da der Anführer der Streitmächte der Geißel nicht länger in Andorhal sein Unwesen treibt, müssen wir den richtigen Augenblick abwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26925] = { id = 26925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj der Beschwörer", description = "Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln gesehen.\n\nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.", sourceObjective = "Tötet Araj den Beschwörer. Ihr könnt Jearls Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.", progress = "Araj ist ein ausgezeichneter Gegner. Ihr solltet gut vorbereitet sein.", completion = "Araj ist tot... das ist gut. Die Königliche Apothekervereinigung hat ihren Part getan. Und Ihr auch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26926] = { id = 26926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg, im Moment", description = "Die Verlassenen haben gesiegt und unsere Streitmächte sind immer noch stark. Gemäß unserer strategischen Kriegsführung müssten wir die Allianz jetzt angreifen, solange man sich dort noch vom Kampf erholt und nicht mit einem Angriff rechnet. Ich habe allerdings andere Pläne...\n\nWir werden warten. Wir greifen Thassarian und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Rhonda Molver und nehmt einen Flug Richtung Bollwerk an der westlichen Grenze der Pestländer. Hochexekutor Derrington wird Euch mit Eurer nächsten Aufgabe vertraut machen.\n\nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.", sourceObjective = "Meldet Euch in Tirisfal am Bollwerk bei Hochexekutor Derrington.", completion = "Die Nachricht traf kurz vor Euch ein, {name}. Dass die Geißel aus Andorhal hinausgeworfen wurde hat die Stellung der Verlassenen in Lordaeron gefestigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26927] = { id = 26927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und plötzlich Murlocs!", description = "Also, wir haben Troggs, die für Kobolde arbeiten und Kobolde, die für Gnolle arbeiten. Die Gnolle müssen aus dem Sumpfland hergezogen sein.\n\nWas weiß ich denn? Nun, sie haben Freunde mitgebracht, denn die Murloc der Blaukiemen schwärmen überall am Loch herum, oder an dem, was von ihm übrig geblieben ist.\n\nPlagegeister sind Plagegeister, aber die Koordination ist besorgniserregend. Ihr müsst mit Kanari Zielwasser reden. Sie ist eine der besten Jägerinnen im Umkreis und sie wird wissen, wie man mit den Murlocs umgeht - wenn es Euch gelingt, sie lange genug von ihrem Krug wegzuzerren.", sourceObjective = "Sprecht mit Kanari Zielwasser.", completion = "Murlocs? Natürlich habe ich Murlocs gejagt.\n\nUnd jeder einzelne dieser Stinker hat bekommen, was er verdiente! Versteht Ihr mich?", sourceObjectiveStatus = "unverified-source-field" }
quests[26928] = { id = 26928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das riecht nach 'nem Plan", description = "Murlocs, die mit Gnollen zusammenarbeiten? Das ist lachhaft! Nun, sie einfach nur zu töten wird Euch auch nicht weiterhelfen. Es gibt zu viele von den Quälgeistern.\n\nAber ich habe einen Plan - ich benutze mein Köpfchen, müsst Ihr wissen. Diese Murlocs sondern einen Geruch ab, den sie überall hinterlassen. Wenn andere Murlocs das riechen, werden sie irre! Damit kann man sie prima ködern.\n\nWie auch immer, sie haben kleine Drüsen, in denen sich der Geruchsstoff befindet. Geht und holt mir ein paar davon.", sourceObjective = "Sammelt am Loch 7 Stinkdrüsen eines Murlocs von beliebigen Murlocs der Blaukiemen.", progress = "Ihr stinkt ja zum Himmel! Ich nehme an, dass das an den Murlocs liegt, aber es ist schwer zu sagen.", completion = "Puh! Welch ein Gestank.\n\nJetzt haltet Euch fest, denn ich werde Euch mit dem, was von meinen geistigen Fähigkeiten geblieben ist, umhauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26929] = { id = 26929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Kroki", description = "Während Ihr herumlauft und das tut, was immer ihr da auch tut - würde es Euch da etwas ausmachen, mir ein wenig zu helfen?\n\nSchaut, normalerweise gehe ich unten am Loch Krokilisken jagen, aber unter den gegebenen Umständen ziehe ich es vor, hier zu sitzen. Es ist sehr höflich von Euch, mir deshalb keine Vorwürfe zu machen. Danke!\n\nDa ihr <solch ein feiner Herr/so eine feine Dame> seid, warum bringt Ihr mir nicht ein paar Krokiliskenkiefer mit und ich gebe Euch im Gegenzug ein bisschen fast sauberes Geld?", sourceObjective = "Sammelt 6 Krokiliskenkiefer.", progress = "Habt Ihr diese Krokiliskdinger gefunden oder habe ich das geträumt?", completion = "Mächtig nett von Euch, einem alten Narren wie mir zu helfen. Hier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26930] = { id = 26930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Kreuzzug", description = "Unsere Siege häufen sich, {name}. Der Scharlachrote Kreuzzug, der die Verlassenen schon seit Langem verfolgt, pfeift aus dem letzten Loch. Sie halten immer noch ihr Kloster hier in Tirisfal, aber sie haben Herdweiler und Tyrs Hand im fernen Osten verloren.\n\nErst letzte Woche gab es Berichte von Aktivitäten des Scharlachroten Kreuzzugs in einem kleinen Lager östlich vom Teufelssteinfeld, aber ich habe guten Grund anzunehmen, dass auch sie ausgelöscht wurden. Reist dorthin und überprüft für mich diese Information.", sourceObjective = "Späht östlich vom Teufelssteinfeld in den Westlichen Pestländern das Lager des Scharlachroten Kreuzzugs aus.", completion = "Brennende Leichen? Keine Überlebenden? Ich habe richtig vermutet.\n\nUmso besser! Wir sind besser dran, wenn die scharlachrote Verderbnis nicht über Lordaeron liegt. Sie verkörperten alles Schlechte am Menschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26931] = { id = 26931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Füchse und Hunde", description = "Die Streitkräfte der Allianz laufen in den Pestländern herum, als ob die Gegend ihnen gehört. Nun, dem ist nicht so. Dieses Land gehört rechtmäßig der Dunklen Fürstin!\n\nAls der Kampf um Andorhal zum Ende kam, zerstreuten sich die Kräfte der Allianz, die die Pestländer besetzten. Einige von ihnen sind genau östlich von hier und jagen Füchse. Beweist ihnen, dass das hier das Gebiet der Verlassenen ist.\n\nTötet die Jäger. Tötet ihre Jagdhunde. Und wenn Ihr gerade dabei seid, tötet die Füchse noch obendrein.", sourceObjective = "Tötet 4 Fuchsjäger der Allianz, 4 Bullenmastiffs und 4 Weißschwanzfüchse in den Westlichen Pestländern.", completion = "Die Jäger aus dem Weg zu haben ist solch eine Erleichterung. Wir sind allerdings noch nicht fertig damit, Allianzler zu töten...", sourceObjectiveStatus = "unverified-source-field" }
quests[26932] = { id = 26932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeflattert", description = "Als der Steinwerkdamm brach, legte er fast den ganzen See trocken. Eine verheerende Umweltkatastrophe.\n\nUnd wagt es nicht, zu denken, dass das keine Auswirkungen auf uns Zwerge hatte! Wir haben nicht nur absolut keine Fische mehr, sondern da draußen liegen über viele Morgen verstreut tote Dreschadon und verrotten in der Sonne. Die Bussarde sind hinter ihnen her und verbreiten dabei Dreck und Krankheiten an den Außenbezirken der Stadt.\n\nIch kann Euch nicht darum bitten, das alles zu säubern, aber könntet Ihr Euch der Bussarde annehmen? Es wird schon helfen, nur ein paar zu töten.", sourceObjective = "Tötet 8 Lochbussarde.", completion = "Das sollte die weitere Verbreitung von Krankheiten in dem Wasser, das uns noch geblieben ist, verhindern. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26933] = { id = 26933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feind oder Bauer?", description = "Die Männer, die das Teufelssteinfeld bestellen, sind keine Bauern. Sie sind Soldaten.\n\nThassarians Streitkräfte benötigten Nahrung, also hat er einige Allianzler aus Andorhal nach Norden entsandt, damit sie sich um das Teufelssteinfeld kümmern. Der Kampf um Andorhal mag vorüber sein, aber es droht bereits die nächste Schlacht... Verlassene gegen Menschen. Wenn die dort auf dem Teufelssteinfeld arbeitenden Soldaten getötet werden, wird das den Streitkräften der Dunklen Fürstin einen entscheidenden Vorteil verschaffen.", sourceObjective = "Tötet 9 Allianzarbeiter auf dem Teufelssteinfeld.", completion = "Haha! Ich hoffe, sie kommen als Zombies zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26934] = { id = 26934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Krankheit", description = "Ich brauche verseuchtes Gras für ein... ein Experiment sozusagen. Diese Argentumkreuzfahrer und die höllischen Cenarischen Druiden haben bei der Heilung der Pestländer wirklich ganze Arbeit geleistet. Ich kann keine brauchbaren Reagenzien in erreichbarer Nähe finden.\n\nAllerdings tragen einige der hiesigen Wildtiere noch die Seuche in sich. Tötet einen kranken Schwarzbär und pflückt dann das Gras, das dort wächst, wo sein verfallender Körper liegt. Das ist nicht optimal, aber es wird genügen.", sourceObjective = "Tötet kranke Schwarzbären in den Westlichen Pestländern und pflückt dann 20 Pesttentakel, die in der Nähe ihrer Körper wachsen.", progress = "Krankheiten erhalten sich in Tiergewebe so viel besser als in Pflanzengewebe, nicht wahr?", completion = "Großartig! Das ist das letzte Stück, das ich benötige.\n\nWartet doch noch einen Moment, {name}. Lasst mich Euch ein wenig mehr über unseren Plan erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26935] = { id = 26935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sägewerk des Nordkamms", description = "Wir sind nicht die einzigen Argentumkreuzfahrer hier in den Pestländern. Unser Hauptquartier, Herdweiler, liegt im Norden. Noch etwas näher im Norden ist ein kleines Sägewerk, das ebenfalls unter unserer Kontrolle steht.\n\nNathaniel Dumah ist mein Kontaktmann im Sägewerk. Sprecht ihn ruhig an, wenn Ihr dort einmal in der Nähe seid.", sourceObjective = "Meldet Euch bei Nathaniel Dumah im Sägewerk des Nordkamms in den Westlichen Pestländern.", completion = "Willkommen in Nordkamm, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26936] = { id = 26936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weniger Bumm", sourceObjective = "Teufelssteinfeld ist geräumt und die Bomben sind scharfgemacht. Ich hoffe, Ihr seid bereit. Ich schlage vor, Ihr haltet Euch die Ohren zu.\n\n<Derrington schaut nach unten und legt seinen Finger auf einen Zündschalter.>\n\nALLES KLAR ZUR ZÜNDUNG! IN 3...\n\n2...\n\n1...", sourceObjectiveStatus = "unverified-source-field" }
quests[26937] = { id = 26937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Tod nicht ausreicht", description = "Derrington und seine Männer wissen es nicht, aber ich habe die Verseuchung vom Teufelssteinfeld angeordnet. Wir brauchen das Gebiet zum Üben. Wenn wir diesen Krieg für Andorhal gewinnen wollen, müssen wir unsere neueste und vielseitigste Waffe einsetzen:\n\nVal'kyr.\n\nNehmt diese umzauberte Val'kyr mit, {name}, und tötet den jämmerlichen Abschaum der Allianz, der auf dem Teufelssteinfeld noch zu finden ist. Sobald einer tot ist, wird er von ihr in diese Welt zurückgeholt... als einer von uns.\n\nDie Verlassenen werden nicht aussterben!", sourceObjective = "Tötet 8 Allianzarbeiter auf dem Teufelssteinfeld, damit Eure bezauberte Val'kyr sie in Verlassene umwandeln kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26938] = { id = 26938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Der einzige Lebenszweck einer Val'kyr ist zu dienen - und diese dient Euch. Ich werde Euch jetzt volle Kontrolle über ihre Fähigkeiten geben, {name}.\n\nWenn Ihr in den Außenbereichen des Hofs herumlauft, solltet Ihr einige der Verlassenen finden, die Ihr gerade erschaffen habt. Ich möchte, dass Ihr Eure Val'kyr benutzt, um mindestens fünf von ihnen einzusammeln. Wenn Ihr das getan habt, nehmt Eure neue Soldatenkolonne, bringt sie in die Teufelssteinscheune und tötet die Bestie darin. Heute werdet Ihr lernen, was es heißt, für die Dunkle Fürstin zu kämpfen.", sourceObjective = "Benutzt die Fähigkeit Eurer umzauberten Val'kyr, um 5 Gardisten der Verlassenen auf dem Teufelssteinfeld zu mobilisieren. Dann tötet die aufgeschlitzte Monstrosität in der Teufelssteinscheune.", completion = "Wenn Koltira das Zeichen gibt, werde ich diese Val'kyr nach Andorhal hineinbringen. Wir werden gewinnen. Und noch ein weiterer Teil Lordaerons wird sich der Macht der Verlassenen beugen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26939] = { id = 26939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Wie seid Ihr hier reingekommen?\n\nAch, ist auch egal. Ich bin Mör'dok vom G-Team. Wir sind die Besten, die es gibt und wir sind hier, um Gnomeregan zurückzuerobern!\n\nAls niemand anders ihm helfen konnte, kam der Hochtüftler zu uns und hat uns angeheuert.\n\nAber das kriegen wir nicht alleine hin! Ihr seid jetzt ein G-Team Kommandosoldat ehrenhalber, {name}.\n\nNehmt diesen Fallschirm, springt geradeaus in die Halle der Zahnräder und tötet die Verflüssigte Ablagerung. Wenn Ihr fertig seid, meldet Euch bei Kommandosoldat Bi'ay Bäräkuss im westlichen Korridor. Ihr beide werdet Euch mit Sicherheit gut verstehen.", sourceObjective = "Tötet die Verflüssigte Ablagerung.", completion = "Ich hoffe, das hat Euch nicht überfordert. Die Mission ist noch längst nicht vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[26940] = { id = 26940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Geschosse", description = "Wir sind die Erben eines Vermächtnisses arkaner Magie und Euer Weg wird kein leichter sein. Viele machen uns immer noch für die Taten unserer Vorfahren verantwortlich, doch unsere Talente werden gebraucht.\n\nIch möchte Euch einen neuen Zauber zeigen: Arkane Geschosse. Er erlaubt es, Salven arkaner Energie abzufeuern, aber Ihr werdet nicht immer in der Lage sein, ihn zu wirken. Wenn Ihr andere Zauber wirkt, besteht die Chance, dass Ihr dadurch die Möglichkeit zur Anwendung von 'Arkane Geschosse' eröffnet.\n\nIch möchte, dass Ihr das jetzt ausprobiert. Sucht nach einer Trainingsattrappe am südöstlichen Ende Aldrassils.", sourceObjective = "Lernt von Rhyanda 'Arkane Geschosse'. Sucht in der Nähe nach einer Trainingsattrappe und übt daran die Anwendung von 'Arkane Geschosse' zwei Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26941] = { id = 26941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Dieser Mör'dok ist verrückt, {class}. Passt bloß auf, dass Ihr niemals mit diesem Gnom in einem Flugzeug sitzt.\n\nVerstohlenheit ist normalerweise nicht mein Ding, und sie wird ganz bestimmt auch nicht Eures sein. Geht diesen Flur entlang bis zur Abschussrampe und entledigt Euch des Elektrokutor 6000.\n\nDer Elektrokutor ist verantwortlich für die Luftfahrzeuge...\n\n... und ich hasse Luftfahrzeuge. Mich bekommt man in kein Luftfahrzeug!\n\nBenutzt diesen Fallschirm, um anschließend abzuspringen und sprecht mit Kommandosoldat Fähs über Eure nächste Aufgabe.", sourceObjective = "Tötet den Elektrokutor 6000.", completion = "Hat ja lange genug gedauert. Kommt mit mir hinter die Säule, bevor Ihr unsere Tarnung auffliegen lasst!", sourceObjectiveStatus = "unverified-source-field" }
quests[26942] = { id = 26942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Ich würde mich von Bi'ay Bäräkuss und Mör'dok geflissentlich fernhalten - die sind beide nicht ganz dicht.\n\nAber Ihr seid es, also an die Arbeit! Geht diesen Tunnel entlang, bis Ihr zum Tüftlerhof kommt. Hoffentlich wisst Ihr, was zu tun ist, wenn Ihr Robogenieur Thermadraht begegnet.\n\nUnser Anführer, Kommandosoldat Hann Ibal möchte Euch irgendwo da drin treffen. Er wird Euch reich für Eure Bemühungen belohnen.\n\nWahrscheinlich.", sourceObjective = "Tötet Robogenieur Thermadraht.", completion = "Ich hätte Euch liebend gern als vollwertigen G-Team Kommandosoldaten, aber Ihr verfolgt andere Abenteuer.\n\nIch bin sicher, wir werden uns wiedersehen und ich hoffe, Ihr habt Euch bis dahin überlegt, uns beizutreten. Hier ist etwas für Eure Unannehmlichkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26943] = { id = 26943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trautes Heim, Gnom allein", description = "Ich hatte in Eisenschmiede mal ein ganz nettes Zuhause. Bis man mich rausgeworfen hat, um Platz für die Gnome zu machen.\n\nDie könnten nicht mal eine Gruppe Troggs aufhalten mit ihren ganzen Dingsdas und Maschinen! Und ich soll für ihre Schwäche bezahlen?\n\nNein, Sir! Nicht mehr.\n\nGeht nach Gnomeregan und redet mit Kommandosoldat Mör'dok. Klar, er ist ein Gnom, aber seine Leute... S.I.C.H.E.R. Ich glaube, so heißen sie... die werden Gnomeregan zurückerobern.\n\nLos! Ich will mein Haus zurück!", sourceObjective = "Sprecht mit Mör'dok.", sourceObjectiveStatus = "unverified-source-field" }
quests[26944] = { id = 26944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeregan erforschen", description = "Die Hauptstadt der Gnome, Gnomeregan, ist seit einiger Zeit nicht mehr unter ihrer Kontrolle. Ich weiß, wie es ist, ein Zuhause zu verlieren.\n\nBitte begebt Euch nach Gnomeregan und sprecht mit Kommandosoldat Mör'dok, einem Mitglied von S.I.C.H.E.R. Wenn Ihr ihnen irgendwie helfen könnt, ihre Heimat zurückzuerobern, dann fordere ich Euch auf, es zu tun. Jene Hallen bergen dunkle Geheimnisse.", sourceObjective = "Sprecht mit Mör'dok.", completion = "Ich hätte nie gedacht, dass ich einen {race} wie Euch hier unten sehen würde. Gibt es einen bestimmten Grund dafür, dass Ihr Leib und Leben riskiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[26945] = { id = 26945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Techniken lernen", description = "Es gibt keine bessere Zeit im Kampf, die Oberhand zu gewinnen, als am Anfang. Lasst mich Euch eine Technik beibringen, mit der Ihr in den Kampf stürmt und Euren Gegner betäubt.\n\nIch möchte, dass Ihr sie jetzt ausprobiert. Sucht nach einer Trainingsattrappe am südöstlichen Ende Aldrassils.", sourceObjective = "Lernt von Alyissia 'Sturmangriff'. Sucht in der Nähe nach einer Trainingsattrappe und übt daran die Anwendung von 'Sturmangriff'.", sourceObjectiveStatus = "unverified-source-field" }
quests[26946] = { id = 26946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vorteil eines Schurken", description = "Ich bin sicher, dass Ihr inzwischen den Finsteren Stoß meisterlich gegen Eure Feinde anwendet. Dennoch möchte ich Euch eine Technik zeigen, die Ihr nach einer erfolgreichen Reihe des Finsteren Stoßes benutzen könnt. Sie nennt sich 'Ausweiden' und ist ein mächtiger Abschluss für eine Kombination von Angriffen.\n\nIch möchte, dass Ihr sie jetzt ausprobiert. Sucht nach einer Trainingsattrappe am südöstlichen Ende Aldrassils.", sourceObjective = "Lernt von Frahun Schattenflüsterer 'Ausweiden'. Sucht im Südosten von Aldrassil nach einer Trainingsattrappe und übt daran die Anwendung von 'Ausweiden' 3 Mal.", completion = "Ihr habt schnell gelernt. Wenn Ihr so scharfsinnig seid, wie Ihr wirkt, dann könntet Ihr einer meiner besten Schüler werden. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26947] = { id = 26947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung eines Waldhirten", description = "Die meisten Menschen, die an die Kaldorei denken, haben Visionen von Druiden und Schildwachen, aber der Weg des Jägers ist ebenso alt und genauso ehrenvoll.\n\nIch habe Euch beobachtet und Ihr habt einige Erfahrungen mit Eurem Bogen gesammelt. Ich möchte Euch eine Schusstechnik zeigen, die ich oft im Kampf anwende.\n\nIch möchte, dass Ihr sie jetzt ausprobiert. Sucht nach einer Trainingsattrappe am südöstlichen Ende Aldrassils.", sourceObjective = "Lernt von Ayanna Immerlauf 'Zuverlässiger Schuss'. Sucht im Südosten von Aldrassil nach einer Trainingsattrappe und übt daran die Anwendung von 'Zuverlässiger Schuss' 5 Mal.", completion = "Ihr lernt unsere Gepflogenheiten schnell. Ich freue mich darauf, Eure Ausbildung fortzusetzen. Kehrt zu mir zurück, wenn die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26948] = { id = 26948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verjüngende Berührung", description = "Druiden spielen in unserer Gesellschaft eine wichtige Rolle. Doch allzu oft werden wir als passive Träumer angesehen, in einer Welt, die sich um uns herum verändert. Ich möchte Euch eine einfache Heiltechnik lehren und ich möchte, dass Ihr damit in die Welt hinausgeht und den Bedürftigen und Gefallenen helft.\n\nWendet Euer Wissen an, um die Wunden der Schildwachen zu heilen, die bei der Verteidigung vom Laubschattental verletzt wurden.", sourceObjective = "Lernt von Mardant Starkeiche 'Verjüngung'. Wendet 'Verjüngung' an, um eine verwundete Schildwache in Aldrassil zu behandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[26949] = { id = 26949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verwundeten heilen", description = "Man wird Euch als Priester oft rufen, damit Ihr die Wunden verletzter Kameraden heilt. Ich möchte Euch eine einfache Heiltechnik lehren. Mit ihrer Hilfe werdet Ihr in der Lage sein, das Leiden der Verwundeten zu lindern und ihre Genesung zu beschleunigen.\n\nWendet Euer Wissen an, um die verletzten Schildwachen zu heilen, die sich in Aldrassil erholen.", sourceObjective = "Lernt von Shanda 'Blitzheilung'. Wendet 'Blitzheilung' 5 Mal an, um die verwundeten Schildwachen in Aldrassil zu behandeln.", completion = "Ihr werdet nie Mangel an Verbündeten haben, die Heilung benötigen. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26950] = { id = 26950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Lichts", description = "Der Scharlachrote Kreuzzug lockt junge Krieger mit dem Versprechen an, die Untoten auszulöschen. Was sie nicht sehen, ist die Schattenseite der ganzen Operation.\n\nBefrager Vishas ist der grausamste Mann, den ich je das Missvergnügen hatte zu treffen - er hat aus meiner Mutter Informationen \"herausgeholt\", als die Seuche zum ersten Mal ausbrach. Der gnadenlose Blutmagier Thalnos bewacht den Friedhof.\n\nDer heilige Zorn der Kreuzfahrer macht sie blind gegenüber ihrer eigenen Dunkelheit. Sorgt dafür, dass sie ihre Scheinheiligkeit bereuen.", sourceObjective = "Tötet Befrager Vishas und Blutmagier Thalnos.", completion = "Was meint Ihr damit, das Thalnos ein Untoter war? Das ist unmöglich. Dies ist ein heiliger Ort, der Scharlachrote Kreuzzug würde niemals zulassen...\n\nNehmt dies als Belohnung und ruht Euch aus. Die Gruften müssen sehr an Euren Nerven gezerrt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26951] = { id = 26951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen auf der E. Insel", description = "Der Kampf, um die Echoinseln zurückzuerobern, ist uns teuer zu stehen gekommen. Aber er war es wert, {class}. Der große Geist, Bwonsamdi, hat unseren Kriegern geholfen, den widerlichen Zalazane zu besiegen. Er hat unsere Krieger mit den Geistern der Insel beschützt. Aber einige dieser Geister sind im Kampf gefallen. Helft dabei, diesen Geistern die ewige Ruhe zu verschaffen. Ihr werdet auf den Echoinseln herumliegende Masken finden. Sammelt sie auf und bringt sie hierher.", sourceObjective = "Sammelt 8 entzauberte Tikimasken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26952] = { id = 26952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Es gefällt mir nicht, was die Verlassenen hier am Bollwerk anrichten. Bomben, Kessel, sinnloses Blutvergießen... Nichts davon verkörpert das, wofür der Argentumkreuzzug steht. Außerdem gefällt mir die Tatsache nicht, dass sie Söldner wie Euch anheuern.\n\nNichts gegen Euch persönlich, {class}. Nur könntet Ihr so viel mehr aus Euch machen. Wenn Ihr Euch eher für die Heilung der Pestländer interessiert als dafür, sie erneut zu verseuchen, dann meldet Euch in der Stätte der Heiler bei Außenagent Kaartish. Die Stätte liegt gen Osten.", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", completion = "Willkommen, {class}. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26953] = { id = 26953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki, der Druide", description = "Ich bin Adrine Wergfell, ein Druide des Zirkels des Cenarius. Ihr könnt Euch bei uns für die Heilung dieses Landes, wo einst nur Tod zu finden war, bedanken.\n\nWir nehmen alle auf, die dem Weg des Druiden folgen möchten ungeachtet von Rasse, Fraktion oder Talent. Hin und wieder bedeutet das die Aufnahme eines Druiden, der mehr Hilfe benötigt als andere.\n\nIch möchte Euch Zen'Kiki vorstellen. Er ist noch recht neu und lernt immer noch sein Handwerk. Würde es Euch etwas ausmachen, wenn Ihr ihn eine Weile mit hinaus nehmt? Ihr könnt an den verseuchten Tieren, die in der Nähe herumstreunen, kämpfen üben.", sourceObjective = "Tötet mit Zen'Kiki an Eurer Seite 20 verseuchte Wildtiere. Ihr könnt schwerfällige Seuchenbären, kranke Wölfe, Giftnebellauerer oder Seuchenlauerer töten.\n\nKehrt zur Stätte der Heiler zurück, wenn Ihr von Zen'Kiki getrennt werdet.", completion = "Anscheinend hat Zen'Kiki immer noch Schwierigkeiten mit der Gestaltwandlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26954] = { id = 26954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anderer Ansatz", description = "Zen'Kiki muss unter anderem an der Genauigkeit seiner Zauber arbeiten. Ich konnte sogar von hier aus sehen, wie sein Zorn Zauber vollkommen außer Kontrolle geriet. Ich konnte ihn sogar als Markierung nutzen, um Euren Fortschritt in den Wäldern zu verfolgen.\n\nVielleicht können wir Zen'Kiki anderweitig einsetzen. Nehmt ihn mit hinauf auf den Hügel im Osten. Die kranken Falken, die über diesem Hügel kreisen, müssen vernichtet werden. Bittet Zen'Kiki, auf diese Falken zu schießen. Selbst, wenn er sie nicht trifft, wird er sie ablenken, damit Ihr sie erledigen könnt.", sourceObjective = "Bringt Zen'Kiki auf den Hügel östlich der Stätte der Heiler und lasst ihn 7 kranke Falken herbeirufen und töten.", completion = "Das wird ja langsam was. Wie viele Vögel hat Zen'Kiki getötet?\n\nKeine? Ihr habt sie alle selbst getötet?\n\nAlso gut, ich denke, wir werden für ihn eine andere Verwendung finden müssen. Wir werden Euch informieren, wenn es so weit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26955] = { id = 26955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki und die Kultisten", description = "Während Eurer Abwesenheit habe ich versucht, für unseren Freund eine neue Verwendung zu finden. Ich glaube, er könnte eine Zukunft als Heiler haben. Das liegt hauptsächlich daran, dass man mit Heilungszaubern nicht danebenschießen kann.\n\nWie Außenagent Kaartish mir mitteilt, kommen die verseuchten Tiere aus dem Lager der Kultisten im Osten. Ich hoffe, es macht Euch nichts aus, Zen'Kiki dorthin zu begleiten... Vielleicht kann er in dem Lager dort einige der verseuchten Tiere heilen.", sourceObjective = "Bringt Zen'Kiki in den Westlichen Pestländern zu Malicias Außenposten, holt 4 gefangene Seuchenbären aus ihren Käfigen und lasst Zen'Kiki sie heilen.", completion = "Bei der Gnade der Erdenmutter - er hat es geschafft! Danke, {name}.\n\nIch gebe zu, dass ich die Hoffnung, was Zen'Kiki angeht, schon fast aufgegeben hatte. Es ist nur Eurer Geduld und Eurem Pflichtbewusstsein zu verdanken, dass er jetzt zu sich als Druide gefunden hat und ein Mitglied des Zirkels des Cenarius ist. Ganz zu schweigen von dem Guten, das Ihr für die Natur getan habt.\n\nEuch gebührt meine Bewunderung und mein Respekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26956] = { id = 26956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guten ins Töpfchen...", description = "{race}! Endlich ist jemand da, der mir helfen kann.\n\nWir Druiden des Cenarius haben Dalsons Hof, der direkt hinter mir liegt, neu bewirtschaftet. Das Land blüht geradezu auf und unsere Ernten waren erfolgreich... zum großen Teil.\n\nEinige Pflanzen scheinen aber noch immer mit der Seuche infiziert zu sein, die dieses Land überzogen hat. Vielleicht waren sie zu tief verwurzelt oder ihre Samen zu schwach. Ich weiß es nicht. Ich weiß nur, dass ich <einen fähigen/eine fähige:c> {class} wie Euch brauche, um die schlechten Pflanzen von den guten zu trennen.", sourceObjective = "Entfernt 6 verdorbene Maispflanzen, 4 verfaulte Äpfel und 3 ungesund aussehende Kürbisse von Dalsons Hof in den Westlichen Pestländern.", completion = "Danke für Eure Hilfe, {name}. Ich weiß, dass Gemüse pflücken nicht gerade die heldenhafteste Tat ist, die man sich vorstellen kann, aber auch bescheidene Aufgaben haben ihren Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[26957] = { id = 26957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der lange Heimweg", description = "Ich bin in meinem Leben schon an vielen Orten gewesen, {class}. Ich habe den Kampf um Ahn'Qiraj mitgemacht, bin durch das Dunkle Portal in die Scherbenwelt getreten und habe mich den Argentumkreuzfahrern angeschlossen, um die Geißel im kalten Nordend niederzuschlagen.\n\nDoch vor all dem war ich ein Bauer hier in Lordaeron. Jetzt bin ich hier in Herdweiler, nur wenige Meilen von zu Hause weg. Es wird Zeit, dass ich meinen Respekt erweise.\n\nIch bin unterwegs zur Stätte der Heiler bevor ich nach Hause zurückkehre. Ich würde mich freuen, wenn wir uns nach meiner Ankunft dort wiedertreffen.", sourceObjective = "Trefft Euch erneut mit Del Gahrron in den Westlichen Pestländern in der Stätte der Heiler.", completion = "Anscheinend bin ich vor Euch eingetroffen, {name}.\n\nAußenagent Kaartish hat mir Einzelheiten über meine alte Heimat berichtet. Wie es scheint, sind meine Kämpfe mit der Geißel noch nicht ganz vorüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[26958] = { id = 26958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Lektion", description = "Lasst uns sofort mit Eurer Ausbildung beginnen. Ich möchte Euch eine Kampftechnik beibringen, die Ihr zu Beginn eines Kampfes sehr nützlich finden werdet. Indem Ihr, noch bevor der Kampf beginnt, auf Euren Gegner losstürmt, könnt Ihr ihn betäuben und dann haltet Ihr die Fäden in der Hand.\n\nIch möchte, dass Ihr diese Technik an einer der Trainingsattrappen ausprobiert, die sich nordwestlich der Absturzstelle befinden. Kehrt zu mir zurück, wenn Ihr sie beherrscht.", sourceObjective = "Lernt von Kore 'Sturmangriff'. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Sturmangriff'.", sourceObjectiveStatus = "unverified-source-field" }
quests[26959] = { id = 26959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beraubt sie ihrer Verteidigung", description = "Wir müssen die Verteidigung des Scharlachroten Klosters ausschalten, bevor eine richtige Invastion stattfinden kann. Stoßt bis in ihre Bibliothek vor und bringt Hundemeister Loksey und Arkanist Doan um. Sie halten die mächtige Verteidigung ihrer Kameraden aufrecht.\n\nMeine Magie wird sicherstellen, dass der Rest des Klosters Euch nicht bemerken wird. Sobald sie tot sind, kann ich weitere Verstärkung herbeirufen, die uns bei unserem Angriff unterstützen wird.\n\nWir müssen erfolgreich sein, {name}. Die Dunkle Fürstin wird ein Versagen nicht im Mindesten tolerieren.", sourceObjective = "Tötet Hundemeister Loksey und Arkanist Doan.", progress = "Habt Ihr Euch um Loksey und Doan gekümmert? Mich zu enttäuschen heißt, die Dunkle Fürstin zu enttäuschen, {race}.", completion = "Ich wusste, ich kann auf Euch zählen! Diese Narren werden niemals wissen, wie ihnen geschah.", sourceObjectiveStatus = "unverified-source-field" }
quests[26960] = { id = 26960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Sohn, der Prinz", description = "Mein Sohn musste in seinem kurzen Leben bisher schon viele Bürden schultern und ich fürchte, er wird noch mehr Verantwortung übernehmen müssen.\n\nEr wird nie lernen, ein Anführer zu sein, wenn er sich nur in der Burg aufhält, doch ich hasse es, ihn ohne Begleitung hinauszuschicken.\n\n{name}, Eure Taten in der Zeit nach dem Kataklysmus sind bereits legendär. Ihr wärt bestimmt <ein ausgezeichneter Mentor/eine ausgezeichnete Mentorin> für den jungen Prinz Anduin.\n\nBitte, stellt Euch ihm vor. Es gibt dringende Geschäfte für die Stadt, die ihr beide für mich wahrnehmen könnt.", sourceObjective = "Stellt Euch in Burg Sturmwind Prinz Anduin vor. Sprecht mit König Wrynn, wenn Ihr Euch bekannt gemacht habt.", progress = "Wie versteht Ihr beide Euch? Anduin lernt schnell - zeigt ihm, wie er ein wahrer Meister wird, {class}!\n\nSeid Ihr beide bereit?", completion = "Ausgezeichnet, Anduin wird viel lernen, wenn er Euch beobachtet.\n\nDenkt daran, verlasst nicht die Stadt. Haltet ihn von Ärger fern. Und das Wichtigste: Bewacht ihn mit Eurem Leben!\n\n<König Wrynn wendet seine Aufmerksamkeit seinem Sohn zu.>\n\nAnduin - keine Abenteuer! Bleib in der Nähe von {name} und komm zur Burg zurück, wenn es Schwierigkeiten gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26961] = { id = 26961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzen sammeln", description = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, fanden wir eine große Anzahl merkwürdiger, verzierter Götzen Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt! Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!\n\nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen! Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", sourceObjective = "Bringt Magmar Todesstreich an der Eisenband Ausgrabungsstätte 8 verzierte Steingötzen.", progress = "Habt Ihr die Götzen? Wir müssen sie studieren und Eisenschmiede von unseren Ergebnissen berichten!", completion = "Ihr habt sie! Gut gemacht, {name}!\n\nUnd Ihr seht nicht einmal besonders angeschlagen aus, trotz all der wild gewordenen Troggs. Ich werde Euch im Auge behalten... Ihr seid viel versprechend.", sourceObjectiveStatus = "unverified-source-field" }
quests[26962] = { id = 26962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beraubt sie ihres Angriffs", description = "Wie Ihr seht, {name}, ist unser erster Angriff auf die Waffenkammer nicht wie geplant verlaufen. Wir hatten bereits den nahegelegenen Hof eingenommen, da tauchte der Scharlachrote Champion Herod auf.\n\nWir müssen unseren Angriff fortsetzen. Der Scharlachrote Kreuzzug darf hier niemals wieder Krieger ausbilden, geschweige denn, einen Angriff auf Unterstadt starten.\n\nEure Aufgabe ist wohl klar. Nieder mit dem Scharlachroten Held.", sourceObjective = "Tötet Herod.", completion = "Herod ist tot! Die Waffenkammer wird fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26963] = { id = 26963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfeinerung Eurer Schüsse", description = "Lasst uns sofort mit Eurer Ausbildung beginnen. Es wird nicht leicht sein, hier zu überleben, und Ihr werdet eine wichtige Rolle für die Versorgung und Sicherheit unserer Leute spielen. Ich möchte Euch eine Schusstechnik zeigen, die ich immer anwende.\n\nProbiert diese Technik an einer der Trainingsattrappen aus, die sich nordwestlich der Absturzstelle befinden. Kehrt zu mir zurück, wenn Ihr sie beherrscht.", sourceObjective = "Lernt von Keilnei 'Zuverlässiger Schuss'. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Zuverlässiger Schuss' 5 Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26964] = { id = 26964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Der Silberwald!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald zu melden.\n\nMehr denn je wird Eure Hilfe benötigt, um die Heimsuchung durch unsere Feinde in dieser Region zu beenden und den Hafen von Gilneas zu erobern!\n\nIhr müsst nach Süden durch Tirisfal reisen und Euch in den Silberwald begeben, um die Kommandozentrale der Verlassenen zu erreichen. Folgt der Straße im Silberwald nach Süden, bis Ihr die Kommandozentrale der Verlassenen erreicht.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Meldet Euch bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald.", completion = "Sehr gut! Ein neuer Rekrut ist eingetroffen. Es gibt viel zu tun... in der Tat sehr viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26965] = { id = 26965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshäuptling kommt", description = "Ihr kommt gerade rechtzeitig, {name}nub. Ihr heißt doch {name}nub, stimmt's?\n\n<Großexekutor Mortuus betrachtet ein Blatt Papier.>\n\nJa, das steht hier in den Papieren: \"{name}nub\".\n\n<Großexekutor Mortuus zeigt auf dem Blatt Papier auf Euren Namen.>\n\nWo war ich noch gleich? Ach ja, Ihr kommt gerade rechtzeitig! Der Kriegshäuptling müsste jeden Moment hier eintreffen, um sich mit unserer Anführerin und Retterin höchstpersönlich zu treffen - der Dunklen Fürstin. Wartet einfach ab und benehmt Euch anständig. Ich bin davon überzeugt, dass wir alle Belobigungen bekommen, wenn diese Kundgebung vorbei ist!", sourceObjective = "Wartet auf die Ankunft von Kriegshäuptling Garrosh Höllschrei.", completion = "Also das war überraschend! Ich will ja nicht an unserem Kriegshäuptling zweifeln, aber...\n\nEgal! Wir haben noch genug Arbeit vor uns. Ich bin sicher, die Dunkle Fürstin und der Kriegshäuptling werden das alles hier in den Griff bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26966] = { id = 26966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Lichts", description = "Als Paladin kennt Ihr das Licht, das uns alle berührt. Gleichzeitig habt Ihr die einzigartige Macht, das Licht im Kampf zur Unterstützung herbeizurufen.\n\nWährend Ihr unter dem Einfluss des Siegels der Rechtschaffenheit steht, werden alle Eure Nahkampfangriffe zusätzlichen Heiligschaden verursachen. Ihr könnt ebenfalls von Zeit zu Zeit 'Richturteil' anwenden, um die Macht Eures Siegels für einen weiteren Angriff zu entfesseln.\n\nIch möchte, dass Ihr diese Techniken an den Trainingsattrappen ausprobiert, die sich nordwestlich der Absturzstelle befinden.", sourceObjective = "Lernt Siegel der Rechtschaffenheit und Richturteil von Aurelon. Wendet Siegel der Rechtschaffenheit an, sucht eine Trainingsattrappe auf der Nordwestseite der Absturzstelle und benutzt Richturteil.", completion = "Ihr habt Euch als guter Schüler erwiesen, {name}. Ich freue mich darauf, Euch wieder zu lehren, wenn die Zeit gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26967] = { id = 26967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf um das Scharlachrote Kloster", description = "Blicket auf die Macht der Verlassenen! Der unaufhaltsame Wille der Dunklen Fürstin durchfließt unsere Körper!\n\nDie meisten der verbliebenen Truppen des Kreuzzugs sind geflohen. Einige leisten allerdings immer noch Widerstand.\n\nIhr habt eine wichtige Rolle beim Erfolg dieser Kampagne gespielt. Sylvanas lässt Euch die Ehre zuteilwerden, ihre letzten noch verbleibenden Feinde zu töten, {name}.\n\nLasst keine Gnade walten.", sourceObjective = "Tötet den Scharlachroten Kommandanten Mograine und Hochinquisitorin Weißsträhne.", completion = "Ja! Das Scharlachrote Kloster gehört jetzt den Verlassenen! Niemand entkommt unserer Rache!\n\nIhr habt die Aufgabe mit der Präzision eines wahren Champions erledigt. Nehmt dies als Belohnung - mit freundlicher Genehmigung der Bansheekönigin.", sourceObjectiveStatus = "unverified-source-field" }
quests[26968] = { id = 26968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Geschosse", description = "Man erwartet von Euch als zukünftigem Magier, dass Ihr eine Vielzahl von Zaubern beherrscht. Einen davon möchte ich Euch jetzt beibringen. Er heißt 'Arkane Geschosse' und Ihr könnt damit eine Salve arkaner Energie auf Euren Gegner abfeuern. Allerdings werdet Ihr ihn nicht immer anwenden können. Jedes Mal, wenn Ihr einen anderen Zauber wirkt, besteht die Chance, dass sich die Möglichkeit zur Anwendung von 'Arkane Geschosse' auftut.\n\nIch möchte, dass Ihr diese Technik an einer der Trainingsattrappen ausprobiert, die sich nordwestlich der Absturzstelle befinden.", sourceObjective = "Lernt von Valaatu 'Arkane Geschosse'. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Arkane Geschosse' 2 Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26969] = { id = 26969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Eure Reise mit der Elementarenergie wird Euch an viele Orte führen. Lasst uns Eure Reise mit einer einfachen, aber nützlichen Lektion beginnen. Ich möchte Euch eine einfache Kampfkunst zeigen.\n\nWenn Ihr sie erlernt habt, geht und probiert Eure neue Fähigkeit an den Trainingsattrappen aus, die sich nordwestlich der Absturzstelle befinden. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Lernt von Firmanvaar 'Urtümlicher Schlag'. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Urtümlicher Schlag' 3 Mal.", completion = "Es ist ein Vergnügen, einen so fähigen Schüler zu haben. Solange Ihr die Traditionen getreu fortführt, werden die Künste des Schamanismus unserem Volk nie mehr verloren gehen. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26970] = { id = 26970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Verletzten helfen", description = "Eine Eurer wichtigsten Pflichten als Priester ist die Anwendung der Macht des Lichts, um Verwundeten zu helfen. Es gibt hier viele Leute, die Eure Fähigkeiten benötigen, {name}. Erlaubt mir, Euch eine einfache, schnelle Heilung zu zeigen, die Ihr zur Behandlung jedes Verbündeten anwenden könnt.\n\nNutzt Euer neu erworbenes Wissen und helft mir, die Verwundeten des Absturzes zu behandeln.", sourceObjective = "Lernt von Zalduun 'Blitzheilung'. Benutzt 'Blitzheilung' 5 Mal, um die Wunden der verletzten Draenei an der Absturzstelle zu behandeln.", completion = "Eure Fähigkeiten als Heiler werden sehr gefragt sein, {name}. Zögert nicht, zu mir zurückzukehren, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26971] = { id = 26971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Ein Geräusch in der Hauptkammer des Tempels erregt Eure Aufmerksamkeit. Ihr hört ein wohlbekanntes Lachen... Lorthuna. Sie ist zurückgekommen, um das Ritual zu unterbrechen - Ihr müsst sie aufhalten!", sourceObjective = "Tötet Hohepriesterin Lorthuna.", completion = "Als all dies begann, sagte Maruut, dass er mit Vergnügen sein Leben gäbe, damit unsere Aufgabe erledigt würde. Er wäre stolz auf diesen Erfolg... auf diesen Tod.\n\nDer Riss ist auf dieser Seite jetzt geschlossen. Tiefenheim sollte sich jetzt ein wenig stabilisieren. Es wird Zeit brauchen, bis Thrall die Wunde in Azeroth geheilt hat, und wir werden wahrscheinlich hierbleiben müssen, bis er es geschafft hat.\n\nDanke für alles, was Ihr getan habt. Ohne Euch hätten wir das wahrscheinlich nicht so schnell erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26972] = { id = 26972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Lichts", description = "Ich habe mich dem Scharlachroten Kreuzzug als junger Paladin voller Eifer angeschlossen, um das Böse aus der Welt zu tilgen. Wie wenig wusste ich doch über die dunkle Wahrheit dieser Fanatiker.\n\nBefrager Vishas und Blutmagier Thalnos überwachen diesen Friedhof. Es bereitet ihnen großes Vergnügen, neue Rekruten endlos zu quälen, um sicherzustellen, dass sie 'rein' sind. Das ist eine Beleidigung des Lichts, {class}!\n\nIch kann nicht länger Teil dieser verdorbenen Organisation sein. Ihr müsst sie beide töten, damit andere nie wieder die Qualen erdulden müssen, die ich ertragen musste.", sourceObjective = "Tötet Befrager Vishas und Blutmagier Thalnos.", completion = "Was meint Ihr damit, dass Thalnos ein Untoter war? Das ist unmöglich. Die ganze Mission des Scharlachroten Kreuzzugs ist darauf ausgerichtet, Untote zu vernichten! Auf gar keinen Fall...\n\nIhr habt meine Gedanken durcheinandergebracht. Bitte nehmt diese Belohnung für Euren Erfolg und lasst mich ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26973] = { id = 26973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einzig wahre Weg", description = "Ich glaube, dass die Wurzel der Verderbnis des Kreuzzugs hier zu finden ist. Arkanist Doan überwacht die Bibliothek und lehrt viele junge Rekruten, wie man mit den arkanen Künsten umgeht.\n\nDas Licht ist der einzig wahre Weg! Ihr müsst ihn töten, {class}, und diese glorreiche Bewegung rehabilitieren!\n\n<Josef der Erweckte bewegt sich unruhig.>\n\nIhr werdet Euch auch Lokseys entledigen müssen. Seine Hunde scheinen etwas gegen unsere noble Absicht zu haben.", sourceObjective = "Tötet Hundemeister Loksey und Arkanist Doan.", completion = "Gute Arbeit! Ich weiß einfach, dass das Licht wohlwollend auf uns und unsere Arbeit scheint. Unsere Sache ist gerecht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26974] = { id = 26974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der falsche Champion", description = "Wir...wir...wir mussten sie töten! Sie waren hinter uns her!\n\nIhr glaubt mir doch, nicht wahr, {name}?\n\nHerod ist nicht der wahre Champion des Scharlachroten Kreuzzugs. Ich bin es! Er hat das, was rechtmäßig mir gehört, an sich gerissen!\n\nIhr solltet ihn töten. Er ist...eine Bedrohung! Er bildet Soldaten aus, die jeden töten und nicht nur die Untoten.\n\nIch werde Euch fürstlich belohnen...", sourceObjective = "Tötet Herod.", completion = "Also ist er wirklich tot? Das bedeutet... Ich, Josef, bin der neue Scharlachrote Champion!!!\n\nNehmt dies. Ich habe ohnehin keine Verwendung für derartige Besitztümer. Schließlich bin ich der Scharlachrote Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[26975] = { id = 26975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flotte zusammenrufen", description = "Ich rufe eine Kriegsflotte zusammen, um das Schattenhochland anzugreifen und den Lakaien von Todesschwinge ihr Ende zu bereiten.\n\nMeine Soldaten sind bereit, aber die Vorbereitungen der Flotte verzögern sich. Meine Männer an den Docks brauchen Inspiration und Motivation. Ein Besuch des Prinzen sollte sie aufmuntern und ihnen erneut die glorreiche Zukunft vor Augen führen, für die sie kämpfen.\n\nGeht mit Prinz Anduin zu den Docks und sprecht mit Nachschuboffizier Graves. Ich möchte, dass Anduin sieht, wie ein geborener Anführer mit der Situation umgeht.", sourceObjective = "Begleitet Prinz Anduin zu den Docks in Sturmwind und sprecht mit Nachschuboffizier Graves. Wenn Ihr und der Prinz Euch aus den Augen verliert, findet Ihr ihn im Thronzimmer von Sturmwind.", completion = "<Graves verbeugt sich respektvoll vor dem Prinz.>\n\nBitte versteht, Eure Hoheit, die Leute arbeiten in Doppelschichten. Das, was Euer Vater vorhat, ist von ungeheurem Ausmaß.\n\nAber wir sind bestrebt, alles fertig zu bekommen. Ich gebe Euch mein Wort.", sourceObjectiveStatus = "unverified-source-field" }
quests[26976] = { id = 26976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf um das Scharlachrote Kloster", description = "Oh, schön, Euch wiederzusehen, {name}! Ich fürchte, ich brauche Eure Hilfe.\n\nWisst Ihr, Mograine ist hier der Befehlshabende zusammen mit Hochinquisitorin Weißsträhne. Sie haben versucht, mir einzureden, dass ich eigentlich nicht der neue Scharlachrote Champion bin. Die Jungs und ich finden das gar nicht gut.\n\nWir werden jetzt das Scharlachrote Kloster selbst übernehmen und die Ordnung so wieder herstellen, wie sie immer hätte sein sollen - mit mir an der Spitze! Ich werde mich der Verlassenen und der Geißel endgültig entledigen.\n\nHelft Ihr einem alten Freund?", sourceObjective = "Tötet den Scharlachroten Kommandant Mograine und Hochinquisitorin Weißsträhne.", completion = "Ja! Das Scharlachrote Kloster gehört uns! Ihr seid ein wahrer Freund. Nehmt dies zur Belohnung und kommt mich jederzeit besuchen, nachdem ich Unterstadt ebenfalls übernommen habe.\n\nDas wird ein scharlachrotes Paradies!", sourceObjectiveStatus = "unverified-source-field" }
quests[26977] = { id = 26977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung im Zwielicht", description = "Die Verräterischen Taten des Schattenhammers in den letzten Monaten haben die Stadt in Aufruhr versetzt. Sie haben es auf die Ängste der Bauern abgesehen und korrumpieren unsere wichtigsten Bürger. Wir müssen herausfinden, wie tief diese Verschwörung bereits sitzt.\n\nIch habe Major Samuelson von der Stadtwache von Sturmwind beauftragt, eine Untersuchung zu leiten. Er ist hier im Thronraum. Seht, ob Ihr ihn bei seinen Bemühungen unterstützen könnt.", sourceObjective = "Sprecht in Burg Sturmwind mit Major Samuelson.", completion = "Hmmm, ja? Meine Untersuchung des Schattenhammers. Natürlich.\n\nEure Mitarbeit wird von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26978] = { id = 26978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer braucht Kessel?", description = "Habt Ihr den Zustand vom Teufelssteinfeld gesehen? Die Streitkräfte der Allianz aus Andorhal haben das Gebiet übernommen und benutzen es, um...um...FELDFRÜCHTE anzubauen!\n\nDa gefiel es mir fast schon besser, als die Geißel das Gebiet noch besetzt hielt. Wenigstens hatten sie so viel Verstand, einen riesigen Seuchenkessel mitten aufs Feld zu stellen.\n\nWir werden uns den Hof von diesen Menschen zurückholen, {name}. Nehmt diese Fässer und stellt sie an Schlüsselpositionen um das Feld herum auf. Ich werde hier am Bollwerk warten.", sourceObjective = "Stellt Zitters Seuchenfässer in der Nähe der Windmühle, bei den Getreidesilos, am Farmhaus und bei der Scheune am Teufelssteinfeld auf.", completion = "<Zitters glüht geradezu vor Aufregung.>\n\nDie Fässer sind aufgestellt? Auf ihren Positionen?\n\nNun gut, ich werde dem Hochexekutor Bericht erstatten. Wenn es so weit ist, wird er derjenige sein, der den Auslöser drückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26979] = { id = 26979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merkwürdige neue Gesichter", description = "Jetzt, da Teufelsstein uns gehört, können wir seine Äcker - und alle Leichen, die wir finden - für unsere Zwecke nutzen. Ich habe von oben den Befehl erhalten, dass Ihr dabei helfen sollt.\n\nVielleicht habt Ihr Lindsay Rabensonn bereits auf dem Schlachtfeld bei Andorhal kennengelernt. Ich habe sie noch nie getroffen, aber sie scheint einige hohe Tiere als Freunde zu haben, denn sie übernimmt das Kommando hier in Teufelsstein. Ihr sollt sie bei dem niedergebrannten Scharlachroten Lager treffen, das ihr vor Kurzem ausspioniert habt.", sourceObjective = "Meldet Euch in den Westlichen Pestländern am Niedergebrannten Außenposten bei Lindsay Rabensonn.", completion = "{name}. Die Dunkle Fürstin wacht über Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26980] = { id = 26980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnellschalts Station", description = "Ihr habt hier gute Arbeit geleistet, {name}. Euch jetzt zu bitten, Sandsäcke zu schleppen, wäre die reine Verschwendung. Um ehrlich zu sein, schicke ich Euch lieber dahin, wo Eure Fähigkeiten gebraucht werden.\n\nWir haben im Marschengebiet weiter nördlich einen kleinen Außenposten. Schnellschalt ist der Gnom, der ihn gebaut hat, aber Ihr solltet mit Shilah Fliesmeißel sprechen und ihr bei Angelegenheiten für Eisenschmiede helfen.\n\nIch gebe zu, sie sieht echt gut aus... aber ich würde nicht den Fehler machen, mir bei ihr irgendwelche Freiheiten herauszunehmen! Die Familie heißt nicht umsonst Fliesmeißel.", sourceObjective = "Sprecht an der Station Schnellschalt nördlich vom Hafen von Menethil mit Shilah Fliesmeißel.", completion = "Starkfaust hat Euch geschickt, ja? Er ist ein guter Hauptmann, führt seine Leute gut. Ich wünschte nur, er würde aufhören, mir auf die Taille zu starren.\n\nUnd Euch will ich auch nicht dabei erwischen. Wir haben hier zu arbeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26981] = { id = 26981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelgars Zuflucht", description = "Ausgrabungsleiter Whelgar hat südlich von hier in diesen Bergen seit geraumer Zeit die Ausgrabungen geleitet. Früher einmal hatte er Probleme mit Raptoren, aber in letzter Zeit hatte sich die Lage gebessert.\n\nVor ein paar Tagen haben wir nun erfahren, dass er die ganze Ausgrabungsstätte evakuieren musste. Ich weiß nicht, was dort vor sich geht, aber ich kann mir nicht vorstellen, dass der Kataklysmus einen Steinbruch sicherer gemacht hat als vorher.\n\nDort arbeiten gute Zwerge, {name}. Würdet Ihr hingehen und nachsehen, was dort los ist und vielleicht auch helfen?", sourceObjective = "Sprecht bei Whelgars Zuflucht südlich der Station Schnellschalt mit Ausgrabungsleiter Whelgar.", completion = "Seid gegrüßt, {class}. Wir haben auf jeden Fall ein Raptorenproblem... oder so was in der Art.\n\nEs ist eher, dass die ganze Grabungsstätte auf uns losgegangen ist. Ich habe noch nie gesehen, dass Felsen und Fossilien sich so aufregen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26982] = { id = 26982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Scharlachrote Kloster", description = "Das Kloster in Tirisfal, das die Scharlachroten Kreuzfahrer jetzt besetzt halten, war früher einmal die Ausbildungsstätte für unsere Paladine. Jetzt lauern dort die Verlassenen aus Unterstadt und der Kreuzzug verhindert, dass wir es für die Ausbildung der Soldaten nutzen, die wir so dringend benötigen, um mit den Verlassenen fertigzuwerden.\n\nHört zu, ich traue ihm zwar nicht über den Weg, aber Josef der Erweckte wartet auf dem Friedhof. Geht und sprecht mit ihm - obwohl er ein Kreuzfahrer ist, sagt er, dass er sich gegen sie auflehnt und uns die Gelegenheit gibt, das zurückzuholen, was uns gehört.", sourceObjective = "Besucht Josef den Erweckten.", completion = "Hauptmann Nials hat Euch geschickt? Ich habe sie schon ewig lange nicht mehr gesehen! Wie geht es ihr? Hat sie meinen Brief erhalten?\n\nOh, Ihr seid nicht deswegen hier. Na, dann lasst uns zum Geschäft kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26983] = { id = 26983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerade nah genug", description = "Täuscht Euch nicht - es gibt hier noch viel zu tun! Dennoch müssen wir auch dort gegen die Verlassenen zurückschlagen, wo wir sie empfindlich treffen können. Das Scharlachrote Kloster in Tirisfal liegt in perfekter Entfernung zu Unterstadt und Brill.\n\nMeldet Euch bei Josef dem Erweckten in der Bibliothek. Er ist ein aufständischer Kreuzfahrer, der uns vielleicht dabei helfen kann, das Kloster als unsere Basis für alle Operationen in dem Gebiet zu übernehmen. Wenn Ihr schon dabei seid, könnt Ihr auch gleich Arkanist Doan eliminieren, einen ihrer mächtigsten Magier.", sourceObjective = "Besucht Josef den Erweckten.", completion = "Ihr seid von Süderstade hiergekommen, nicht wahr? Ich wette, dass Rachehunger gegen die widerwärtigen Verlassenen den Ort in Schutt und Asche gelegt hat. Der Scharlachrote Kreuzzug kann helfen, sich darum zu kümmern!\n\nDas heißt, sobald Ihr mir geholfen habt, ihre fehlgeleiteten Seelen wieder auf den rechten Weg zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26984] = { id = 26984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter, verrückter Freund", description = "Josef der Wahnsinnige war hier einer meiner guten Freunde, bevor er sich dem Scharlachroten Kreuzzug im Scharlachroten Kloster in Tirisfal anschloss. Ich hörte, dass er in der Waffenkammer dort ist und einen lächerlichen Versuch unternimmt, Herods Position als Scharlachroter Champion zu übernehmen.\n\nEs ist reiner Selbstmord, Herod so herauszufordern! Geht dort hinauf und versucht, ihm das auszureden.", sourceObjective = "Besucht Josef den Wahnsinnigen.", completion = "Ihr seht zäh aus, {class}. Es gilt hier, viel Unrecht wiedergutzumachen. Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26985] = { id = 26985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinn gegen Irrsinn ausspielen", description = "Unsere frisch verstärkten Streitkräfte kommen mit der Situation hier für eine Weile ohne Euch zurecht. Ich habe Berichte erhalten, dass Josef der Irrsinnige, eine früherer Offizier des Scharlachroten Kreuzzugs, sich im Scharlachroten Kloster aufhält und mit seiner Gruppe Abtrünniger gegen den Scharlachroten Kommandanten Mograine losschlagen will.\n\nDas ist eine ausgezeichnete Gelegenheit. Geht dort hin und helft ihm bei seinem irrsinnigen Vorhaben. Vielleicht können wir dann das Kloster als Festung genau auf der Türschwelle von Sylvanas benutzen.", sourceObjective = "Besucht Josef den Rasenden.", completion = "Moment, Ihr wurdet von DER Shandris Mondfeder hierhergeschickt? Ich traue meinen Ohren nicht! Zu wissen, dass meine Sache von ihrer riesigen Armee unterstützt wird...\n\nJa, ja, Ihr seid perfekt. Ihr seid der Schlüssel zu meiner Zukunft!", sourceObjectiveStatus = "unverified-source-field" }
quests[26986] = { id = 26986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Scharlachrote Kloster", description = "Um sicherzustellen, dass unsere Männer sich so wenig Verletzungen wie möglich zuziehen, ist es oftmals am besten, unseren Feinden zuhause großen Schaden zuzufügen, um so zu verhindern, dass Schlachten überhaupt stattfinden!\n\nReist zum Scharlachroten Kloster und sprecht mit der dunklen Waldläuferin Velonara auf dem dortigen Friedhof. Sie führt einen Angriff der Verlassenen an und könnte von <einem erfahrenen/einer erfahrenen:c> {class} wie Euch profitieren.", sourceObjective = "Meldet Euch bei der dunklen Waldläuferin Velonara.", completion = "Sieht so aus, als ob Darthalia wie von mir gewünscht einen fähigen {class} geschickt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26987] = { id = 26987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der rechte Weg", description = "Meine Leute sind generell nicht sehr von den arkanen Künsten, die von anderen Völkern missbraucht werden, angetan. Glücklicherweise sind wir weit von den Zauberen in der Bücherei des Scharlachroten Klosters entfernt, doch ihre Fähigkeit, sich über die materielle Welt hinwegzusetzen, bereitet mir Sorgen und stellt letztendlich eine Gefahr für das Überleben meines Stammes dar.\n\nReist weit nach Westen zur Bücherei des Klosters und sprecht dort mit der dunklen Waldläuferin Velonara. Ihre Streitkräfte stehen schon kurz davor Arkanist Doan, den führenden Magus des Kreuzzugs, höchstpersönlich anzugreifen.", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", completion = "Ich bin überrascht, dass Jäger Mark'hor zur Abwechslung einmal mit mir zusammenarbeitet. Er ist sonst ziemlich stur. Allerdings nährt er einen starken Hass gegen Magie.\n\nIch hoffe, Ihr tut das auch, {class}, denn wir werden dem Scharlachroten Kreuzzug seine Magie wegnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26988] = { id = 26988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sache in Schwung bringen", description = "Ich warte auf einige sehr mächtige Reagenzien, die ich vor Kurzem aus Unterstadt bestellt habe. Wie ich höre, verzögert sich die Lieferung, weil die Kreuzfahrer des Scharlachroten Klosters den Weg versperren. Der Scharlachrote Champion Herod ist wahrscheinlich für diese Unannehmlichkeit verantwortlich.\n\nBitte geht und sprecht mit der dunklen Waldläuferin Velonara in der Waffenkammer des Scharlachroten Klosters. Sie wird sich um Herod kümmern, was bedeutet, dass meine Lieferung sicher ankommt!", sourceObjective = "Besucht die dunkle Waldläuferin Velonara.", completion = "Yayo'jin hat Recht, wenn Ihr mir hier helft, wird ihr das im Hinterland ebenfalls helfen.\n\nNoch ein Grund, warum wir sofort loslegen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26989] = { id = 26989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gilnearische Befreiungsfront", description = "Der Kampf um die Region tobt immer noch, {name}nub. Obwohl wir die Verteidiger von Gilneas vernichtend geschlagen und Gilneas für die Horde eingenommen haben, ist es einer kleinen Gruppe Rebellen gelungen, zu entkommen. Die \"Gilnearische Befreiungsfront\" - wie sie sich selbst nennen - ergreift jede Gelegenheit, unsere Truppen draußen anzugreifen. Den Rebellen sind einige kleinere Siege gelungen und jetzt werden sie bei ihren Angriffen immer dreister! Es ist an der Zeit, zurückzuschlagen, {name}nub.\n\nGeht nach Süden in die Wildnis von Silberwald und tötet jeden Rebellen, dem Ihr begegnet.", sourceObjective = "Tötet 10 Worgenrenegaten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26991] = { id = 26991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde vor den Toren", description = "Manchmal müssen wir die Notwendigkeit, unsere Verbündeten zu beschützen, anerkennen, damit sie uns beschützen können. Dies ist eine solche Gelegenheit, {race}.\n\nReist zum Scharlachroten Kloster in der Nähe von Unterstadt in Tirisfal. Sobald Ihr dort eintrefft, geht zur Kathedrale und sprecht mit der dunklen Waldläuferin Velonara. Sie führt den letzten Schlag gegen den Kreuzzug dort und es würde uns allen sehr zum Vorteil gereichen, wenn wir sicherstellen, dass unsere untoten Verbündeten das Kloster übernehmen, bevor die Kreuzfahrer eine Chance haben, ihre Hauptstadt anzugreifen.", sourceObjective = "Findet die dunkle Waldläuferin Velonara.", completion = "Nazeer ist ein kräftiger Krieger - sein Hass auf unsere Feinde ist noch stärker als meiner. Ihr seid eingeladen, meinen Streitkräften zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26992] = { id = 26992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerz im Überfluss", description = "Zweifellos habt Ihr von dem Vorfall gehört, der sich am Zornestor in Nordend abgespielt hat, nicht wahr? Wegen dieser unglückseligen Vorkommnisse ist es uns strengstens verboten, den Erregerstamm der todbringenden Krankheit, den wir endlich perfektioniert hatten, zu verwenden. Jetzt gibt es Regeln und Vorschriften und anderen Unsinn!\n\nMan hat uns eine entschärfte Version der perfekten Krankheit gegeben und erwartet nun, dass wir daraus eine Waffe basteln.\n\nWenn ich diesen Mist zum Funktionieren bringen soll, dann brauche ich einige Taschen voll mit wildem Verdammniskraut. Ihr findet es überall im Silberwald.", sourceObjective = "Sammelt 8-mal Wildes Verdammniskraut.", progress = "Habt Ihr das wilde Verdammniskraut gesammelt, um das ich Euch gebeten hatte?", completion = "Schmerz im Überfluss, sage ich Euch! Das Land selbst droht, uns zu verschlingen und dennoch bestehen wir fort. Ich frage mich, warum das so ist? Mit diesem Verdammniskraut, den Eingeweiden und dem geronnenen Blut, das T'Veen benötigt, haben wir vielleicht etwas Geeignetes, das wir an die Frontlinie der Verlassenen senden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26993] = { id = 26993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompendium der Gefallenen", description = "Keine Angst, ich diene keinem Herrn, {race}. In diesen Hallen liegt ein Buch, genannt Kompendium der Gefallenen. Es enthält Unmengen von Forschungsergebnissen, die der Scharlachrote Kreuzzug im Laufe der Jahre über meinesgleichen zusammengetragen hat.\n\nEinfach gesagt möchte ich, dass Ihr es findet und zu mir zurück bringt, ohne Fragen zu stellen.", sourceObjective = "Findet das Kompendium der Gefallenen.", progress = "Ich möchte nicht noch länger in einem Kloster bleiben, das voller Zeloten ist, die Untote hassen. Das könnt Ihr sicherlich nachvollziehen. Sprecht mich nicht an, solange Ihr das Buch nicht bei Euch tragt.", completion = "Gut gemacht! Wie wäre es, wenn ich Euch eine hübsche Belohnung für Eure Arbeit gebe und Ihr erzählt niemanden, dass Ihr mich hier gesehen habt. Einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[26994] = { id = 26994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Sinn und Verstand", description = "Wie ich höre, möchte Joseph der Wahnsinnige, dass Ihr Herod tötet. Wenn Ihr schon dabei seid, warum bringt Ihr dann auch nicht gleich ihre besten Soldaten um? Ich werde Euch für Eure Arbeit gut bezahlen.\n\nZerbrecht Euch über das 'Warum' nicht den Kopf, nur über das 'Wie'.", sourceObjective = "Tötet 3 scharlachrote Myrmidonen, 3 scharlachrote Beschützer, 3 scharlachrote Gardisten und 3 scharlachrote Rufer.", progress = "Spielen wir keine Spielchen... Sind sie tot oder nicht?", completion = "Sehr gut! Ja, in der Tat, sehr gut.\n\nEure Belohnung, wie versprochen. Keine Fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26995] = { id = 26995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Innereien und Blut", description = "Wenn wir diese neue Krankheit in die Gänge bringen wollen, brauchen wir saubere Tierinnereien. Das Problem ist, dass saubere Tierinnereien im Silberwald ausgesprochen selten sind. Die meisten Tiere sind von Krankheiten befallen und haben daher nur kranke Innereien.\n\nDurchsucht das Waldgebiet östlich von hier nach Worgs und ergrauten Bären. Tötet nur die, die nicht von Krankheiten befallen sind und reißt ihnen die Innereien heraus. Bringt mir so viele saubere Eingeweide, wie Ihr in Euren Rucksack stopfen könnt.", sourceObjective = "Findet 6 \"saubere\" Tierinnereien.", progress = "Denkt daran, ich kann nur saubere Tierinnereien für den neuen Erregerstamm der Krankheit, die wir entwickeln, gebrauchen.", completion = "Ausgezeichnet! Mit diesen Eingeweiden und dem wilden Verdammniskraut können wir den Erregerstamm unserer neuen Krankheit testen. Jetzt müssen wir nur noch ein geeignetes Ziel auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26996] = { id = 26996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau vor ihren Nasen", description = "In dem rechten Seitenraum der verfluchten Kathedrale ist an der Wand eine Fackel. Bewegt sie und eine Geheimtür wird sich öffnen. Dahinter befindet sich Hochinquisitor Schönufer. Er ist jetzt ein Untoter.\n\nJemand muss ihn erledigen. Wenn möglich, tötet ihn in seinem Zimmer. Ich ziehe es vor, wenn die Kreuzfahrer ihn nicht sehen. Ihr kennt das ja - tötet ihn und ich gebe Euch eine Belohnung. Wir müssen nichts weiter sagen.", sourceObjective = "Tötet Hochinquisitor Schönufer..", completion = "<Dominic gibt Euch Eure Belohnung. Kein Wort wird gewechselt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26997] = { id = 26997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die üblichen Verdächtigen", description = "<Samuelson kratzt sich gedankenverloren das Kinn.>\n\nMeine Untersuchungen haben ergeben, ähm, es ist möglich, dass sich unter den Dockarbeitern von Sturmwind Ärger zusammenbraut. Durchtriebene Bande. Ich traue denen nicht!\n\nIhr solltet dahin gehen und alles mal ordentlich auf den Kopf stellen. Fühlt diesen Hafenarbeitern auf den Zahn. Das sollte Euch eine Weile beschäftigen.\n\nGeht und eliminiert diese Ungläubigen des Schattenhammers!", sourceObjective = "Fühlt im Hafen von Sturmwind 6 Dockarbeitern von Sturmwind auf den Zahn.", completion = "Das ergibt doch keinen Sinn, {name}.\n\nWarum hat Samuelson uns hier hinaus auf eine sinnlose Verfolgungsjagd geschickt?\n\nDa stimmt doch etwas nicht. Wir sollten auf eigene Faust Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26998] = { id = 26998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Erfolg fortsetzen", description = "Das Gebräu ist endlich fertig, aber bevor ich diesem Erregerstamm mein Gütesiegel verleihe, müssen wir einen Feldversuch unternehmen.\n\nSprecht hier in der Kommandozentrale mit Fledermausführer Madenhauch und verschafft Euch eine Fledermaus. Die Fledermaus bringt Euch über den Lordameresee hinweg zu den Morgeninseln, mitten ins Herz der Verderbnis - zu den Höhlen der Murlocs der Finsterflossen.\n\nBenutzt dieses Gebräu gegen die Murlocs und berichtet mir über die Ergebnisse.\n\nDie Ergebnisse sollten natürlich so aussehen, dass Ihr sie alle wie befohlen getötet habt!", sourceObjective = "Tötet 50 Murlocs der Finsterflossen.", progress = "Habt Ihr die Murlocs der Finsterflossen auf den Morgeninseln ausgerottet?", completion = "Stark genug, um tausend Murlocs auszurotten! Ich glaube, das schreibe ich auf das Etikett. Ihr habt gute Arbeit geleistet, {name}, und gute Arbeit wird hier belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26999] = { id = 26999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Ära für die Pestländer", description = "Die Geißel hat die Macht über dieses Gebiet verloren. Wir, die Lebenden, übernehmen Lordaeron wieder.\n\nWir haben bereits große Fortschritte gemacht, wie Ihr gesehen habt. Die Erde erblüht, die Bäume wachsen immer höher und sind grün und die Tierwelt kehrt langsam zurück. Dennoch sind eine Handvoll Untote zurückgeblieben.\n\nDie Bäume und das Gras gedeihen, aber die Tiere haben Schwierigkeiten. Etwas hindert sie an ihrer Heilung und ich gedenke herauszufinden, was das ist. Bringt mir Proben von den verseuchten Tieren, damit ich sie mir genauer ansehen kann.", sourceObjective = "Sammelt Proben von 4 Seuchenlauerern, 4 Giftnebellauerern, 4 schwerfälligen Seuchenbären und 4 kranken Wölfen.", progress = "Sobald die Tiere geheilt sind, wird unsere Pflicht hier draußen fast erfüllt sein.", completion = "Das ist mehr als genug, {name}. Jetzt brauche ich etwas Zeit, um meine Studien durchzuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27000] = { id = 27000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komm, hol das Lasso raus", description = "Ah, schön wieder auf dem Nordkamm zu sein! Ich habe mein Sägewerk, meine hübsche Frau, meinen quietschfidelen kleinen Jungen... Ich habe mich sogar dem Argentumkreuzzug angeschlossen. Wir werden Tirions Streitkräfte mit Holz versorgen.\n\nMeine Holzfäller waren ausgesprochen produktiv... bis die Spinnen kamen. Jetzt weigern sie sich, tiefer in den Wald zu gehen.\n\nVielleicht könntet Ihr mir helfen. Schwingt Euch auf eins meiner Pferde und jagt den Spinnen Angst ein. Vielleicht können wir Blutvergießen vermeiden und sie einfach fortjagen.", sourceObjective = "Steigt am Sägewerk des Nordkamms auf einen Herdweiler Mustang und benutzt seine Fähigkeit 'Wiehern', um 25 Nordkammspinnen Angst einzujagen.", completion = "Nun, es hört sich so an, als ob sie große Angst vor dem Mustang haben, aber sie bleiben nicht weg. Ich kann Euch nicht ewig auf dem Pferd herumrennen lassen. Und ich glaube auch nicht, dass Ihr das möchtet.\n\nAlso gut. Dann eben Blutvergießen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27001] = { id = 27001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier ist WoW (Wald ohne Wildspinnen)", description = "Der Hochlord war so großzügig, einige seiner Rekruten zu entsenden, damit sie uns hier am Sägewerk unterstützen. Mit Eurer Reitkunst und ihren Kampfkünsten können wir uns dieses Spinnenproblems mit Leichtigkeit entledigen.\n\nSteigt wieder auf den Mustang und macht den Spinnen Angst. Diesmal müsst Ihr sie aber bis zum Sägewerk vor Euch hertreiben. Die Rekruten aus Herdweiler können sich dann hier der Dinge annehmen.", sourceObjective = "Besteigt am Sägewerk des Nordkamms einen Herdweiler Mustang und benutzt seine Fähigkeit 'Wiehern', um 10 Nordkammspinnen zu den Rekruten von Herdweiler an der Nordkamm Sägemühle zu treiben. Ihr könnt mehrere Spinnen auf einmal zusammentreiben.", completion = "So ist es schon viel besser! Jetzt können meine Holzfäller wieder an die Arbeit gehen.\n\nWie schon gesagt, Ihr seid da draußen gut geritten, {name}. Auf dem Mustang gebt Ihr ein echt gutes Bild ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[27002] = { id = 27002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz mit dem Hochlord.", description = "Oh, bevor Ihr geht, {name}... Ich habe eine Nachricht für Euch. Jemand in Herdweiler möchte Euch gerne kennenlernen. Er sagte, dass er bereits einige Male über Euren Namen gestolpert ist.\n\nIhr könnt Euch glücklich schätzen, {name}. Nicht jeder bekommt eine persönliche Audienz mit Hochlord Tirion Fordring.\n\nOh - und Ihr dürft gerne einen meiner Mustangs für den Ritt dorthin nehmen. Sie sind die schnellsten, die man für Geld kaufen kann.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Herdweiler bei Hochlord Tirion Fordring.", completion = "{name}. Es ist mir wirklich ein Vergnügen.\n\nIch weiß, Ihr seid jung und steht noch in Ausbildung, aber ich habe Euch im Auge behalten. Wir beim Argentumkreuzzug suchen immer nach vielversprechenden Rekruten und Ihr habt großes Potenzial gezeigt. Ich habe noch keine Aufgaben für Euch, doch ich wollte Euch persönlich kennenlernen und mir selbst ein Bild davon machen, was Ihr für ein {race} seid.\n\nFür den Moment dürft Ihr Euch an den Annehmlichkeiten von Herdweiler erfreuen. Ich freue mich auf unser nächstes Treffen, {name}. Ihr dürft wegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27003] = { id = 27003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichtverdientes Geld", description = "Wen haben wir denn da!\n\nWie auch immer Ihr hierhergekommen seid, ich bin so froh, dass Ihr hier seid!\n\nMeine Freunde hier würden es nie zugeben, aber wir können wirklich Hilfe gebrauchen.\n\nDie uralte Region von Uldum ist freigelegt worden! Dort gibt es Schätze, die Eure kühnsten Träume übertreffen, und man kann sie einfach mitnehmen!\n\nDas einzige, was wir brauchen, ist eine kleine Eskorte, bei den ganzen Banditen und so...\n\nIhr werdet uns begleiten, oder?\n\nIhr dürft auch so viele Schätze mitnehmen, wie Ihr tragen könnt!", sourceObjective = "Begleitet Adarrahs Karawane hinein nach Uldum.", completion = "Es riecht, als wäre vor Kurzem jemand in dieser Zelle gewesen.\n\nIgitt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27004] = { id = 27004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtpläne", description = "Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.\n\nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, {name}.\n\nDurchsucht die Kultisten, bis Ihr sie findet.", sourceObjective = "Sammelt die Pläne für das Tor der Meister.", progress = "Diese Pläne sind der Schlüssel zu allem.", completion = "<Mowi betrachtet die Pläne, die Ihr ihr gegeben habt.>\n\nAber… aber das ist nichts als Kauderwelsch!\n\nWas soll das überhaupt bedeuten? Welche Sprache ist das?", sourceObjectiveStatus = "unverified-source-field" }
quests[27005] = { id = 27005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtpläne", description = "Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.\n\nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, {name}.\n\nDurchsucht die Kultisten, bis Ihr sie findet.", sourceObjective = "Sammelt die Pläne für das Tor der Meister.", progress = "Diese Pläne sind der Schlüssel zu allem.", completion = "<Der Prüfer betrachtet die Pläne, die Ihr ihm gegeben habt.>\n\nDas ist nichts als Kauderwelsch!\n\nWas soll das überhaupt bedeuten? Welche Sprache ist das?", sourceObjectiveStatus = "unverified-source-field" }
quests[27006] = { id = 27006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überflieger", description = "Ich hab versucht, die Terrasse zu überfliegen und mir selbst 'n Bild zu machen, aber diese toastfressenden Weicheier ha'm auf mich geschossen und ich kam nicht dran.\n\nIhr seht so aus, als ob Ihr mit Zügeln umgehen könnt. Warum nehmt Ihr nicht Euer Flugtierchen und fliegt hoch nach Südwesten, mal nachsehen, was der ganze Wirbel soll?", sourceObjective = "Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.", completion = "Ein Tor?! Die Kulties ha'm ein Titanentor ausgebuddelt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27007] = { id = 27007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stelldichein in den Silbermarschen", description = "Ausgezeichnete Arbeit, {name}. Wir wissen genau, wo der Treffpunkt ist.\n\nDie Oberen Silbermarschen sind ein Quecksilbersumpf östlich von hier. Normalerweise hausen dort Elementare und gelegentlich auch Steintroggs, aber unsere Späher haben in der Region Aktivität des Schattenhammers beobachtet.\n\nMacht Euch auf den Weg dorthin und findet eine Möglichkeit, das Treffen des Schmiedemeisters zu belauschen.", sourceObjective = "Geht zu den Oberen Silbermarschen in Tiefenheim.", completion = "Das ist der Ort. Unsere Späher haben die Anwesenheit von hochrangigen Offizieren des Schattenhammers bestätigt und gleichzeitig mögliche Troggjäger ausgemacht.\n\nSeid vorsichtig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27008] = { id = 27008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überflieger", description = "Ich bin ziemlich geschickt im Umgang mit dem fliegenden Teppich. Doch als ich versucht habe, herauszufinden, was diese Kultisten auf der Zwielichtterrasse entdeckt haben, haben sie mich fast vom Himmel geschossen.\n\nIhr seht aus, als wärt auch Ihr ein Meister der Lüfte. Würdet Ihr für mich nach Südwesten fliegen und herausfinden, was sie da ausgegraben haben?", sourceObjective = "Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.", completion = "Ein Tor?! Sie haben ein Tor der Titanen ausgegraben.\n\nDas ist äußerst interessant und möglicherweise sehr gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27009] = { id = 27009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kältebringer", description = "Amnennar der Kältebringer regiert die Hügel der Klingenhauer mit dunkelster und mächtiger Geißelmagie. Es ist mir gelungen, eine Öffnung in die Dornen oberhalb seines Machtsitzes zu schlagen, aber seine Zauberkraft verwehrt es mir, einen Angriff zu starten.\n\nWenn Ihr die Dornenspirale hinaufgeht und ihn angreift, wird ihn das ablenken, bis ich ihn angreifen und schwächen kann, damit er seine tödlichen Zauber nicht wirken kann. Wenn er erst geschwächt ist, tötet ihn, ohne Gnade zu zeigen.", sourceObjective = "Tötet Amnennar den Kältebringer.", completion = "Das war gute Arbeit, {name}. Die Stacheleber hier können nicht gerettet werden, aber wenigstens sind sie nicht mehr zum Angriff aufgestellt und sind nicht länger Sklaven unter Amnennars tyrannischer Herrschaft.\n\nBitte geht schnell. Die Hügel der Klingenhauer sind ohne Hoffnung. Sie müssen gereinigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27010] = { id = 27010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untertauchen im Quecksilber", description = "Die Troggs in Tiefenheim sind genau so feindselig wie die in Azeroth. Dennoch, ihre Anwesenheit könnte für unsere Bemühungen von Vorteil sein.\n\nDie Kisten, die sie benutzen, um in dem Quecksilber herumzufischen, können Euch perfekt tarnen, wenn Ihr in den Marschen auf Tauchstation geht.\n\nBenutzt sie, um das Lager des Schattenhammers am östlichen Ende der Oberen Silbermarschen unentdeckt zu erreichen.", sourceObjective = "Verschafft Euch eine Troggkiste und versteckt Euch darunter. Dann belauscht das Lager des Schattenhammers im Osten.", completion = "Wir haben die benötigten Informationen. Wir sollten uns nicht verraten, indem wir den Feind zu früh angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27011] = { id = 27011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotkieferdiebstahl", description = "Weiter im Süden findet Ihr Gnolle der Rotkiefer...Neuankömmlinge in diesem Gebiet. Ihr seid wahrscheinlich auf dem Weg hierher an ihnen vorbeigekommen. Nathaniel tut so, als ob sie kein Problem darstellen, aber ich weiß es besser.\n\nIch habe gesehen, wie sie nachts mit unserem Holz weggerannt sind. Ich weiß gar nicht, was sie mit dem Holz vorhaben - sie scheinen keine guten Handwerker zu sein - aber das hält sie nicht davon ab, es zu stehlen. Geht hinunter zu ihren Lagern und stehlt das Holz zurück.", sourceObjective = "Holt aus dem Rotkieferlager in den Westlichen Pestländern 10 Stapel Nordkammholz zurück.", progress = "Einige der älteren Holzfäller erzählen, dass die Rotkiefer vor einigen Jahren hier gelebt haben. Doch als die Seuche ausbrach, sind sie fortgegangen. Trotzdem gibt ihnen das nicht das Recht, zu stehlen.", completion = "Ich bringe das nur eben zurück in die Holzlager draußen. Nathaniel wird wahrscheinlich nicht einmal bemerken, dass es gefehlt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27012] = { id = 27012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lösung des Gnollproblems", description = "Ich habe so meine Zweifel, was die Absichten dieser Gnolle angeht. Bisher haben sie uns noch nicht angegriffen, aber es werden immer mehr und sie scheinen immer ihre Waffen im Anschlag zu haben. Ich bin kein Militärexperte, aber das erscheint mir ein wenig aggressiv.\n\nWenn wir ihnen einige ihrer Waffen wegnehmen, werden sie vielleicht nicht zur Bedrohung für unser Sägewerk. Ich würde mich viel besser fühlen, wenn Ihr dort hinunter geht und einige ihrer Waffen zu mir bringt.", sourceObjective = "Beschafft 6 Rotkieferstäbe und 6 Rotkieferkeulen von den Gnollen der Rotkiefer.", progress = "Ich will nicht allein wegen einer besorgten Mutter eine Art Massenmord an Gnollen befehlen. Ich möchte mich nur in meinem Zuhause sicher fühlen.", completion = "Danke, {name}. Ich werde die jetzt ins Feuer werfen. Schließlich wollen wir nicht, dass die Gnolle sich hineinschleichen und sie erneut stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27013] = { id = 27013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu knapp für meinen Geschmack", description = "Ich freue mich für Nathaniel. Er versucht schon so lange, wieder nach Nordkamm zurückzukehren. Jetzt, da der Scharlachrote Kreuzzug ihm nicht mehr im Weg steht, kann er endlich nach Hause. Nur ... Auch, wenn die Umgebung hier idyllisch zu sein scheint, ist sie nicht der beste Ort, um eine Familie aufzuziehen.\n\nZum Beispiel: Am Rande dieses Tals findet man tollwütige Füchse, die nach unschuldiger Beute suchen. Hin und wieder erhasche ich einen Blick auf einen von ihnen, der mich direkt anschaut.\n\nBitte, {class}, erlegt einige dieser Füchse. Ich fühle mich in ihrer Nähe nicht sicher.", sourceObjective = "Tötet in den Westlichen Pestländern nahe dem Sägewerk des Nordkamms 12 tollwütige Füchse.", completion = "Jetzt bin ich etwas erleichtert, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27014] = { id = 27014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Notiz", description = "Gerade war ein Bote hier und hat Euch gesucht, {name}. Ich glaube, er wurde von der Priesterlehrerin Seherin Rabenfeder geschickt. Wenn diese Nachricht von der Seherin ist, würde ich sie sofort aufsuchen.", sourceObjective = "Sprecht im Camp Narache mit Seherin Rabenfeder.", sourceObjectiveStatus = "unverified-source-field" }
quests[27015] = { id = 27015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Notiz", description = "Gerade war ein Bote hier und hat Euch gesucht, {name}. Ich glaube, er wurde von dem Paladinlehrer Sonnenwandler Helaku geschickt. Wenn diese Nachricht von dem Sonnenwandler ist, würde ich ihn sofort aufsuchen.", sourceObjective = "Sprecht im Camp Narache mit Sonnenwandler Helaku.", sourceObjectiveStatus = "unverified-source-field" }
quests[27016] = { id = 27016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freuden der Eberjagd", description = "Versucht, Eure Aufregung zu zügeln, {name}, denn Ihr befindet Euch in der Gesellschaft des besten Eberjägers in Azeroth!\n\nIhre Durchtriebenheit, ihre rasende Geschwindigkeit, die extreme Stärke und die widerstandfähigen Bälger... ja, Eber sind nur die Beute der meisterlichsten Jäger. Anfänger brauchen sich gar nicht erst bewerben!\n\nIch wette, Ihr habt noch nie so ein exotisches Tier gejagt. Ich halte jede Wette, dass Ihr meinen Rekord von zehn getöteten Ebern nicht einstellen könnt. Versucht es mit denen an der Ostseite des Loch, aber tut Euch nicht weh, Grünschnabel!", sourceObjective = "Tötet 10 Schlammbaucheber.", completion = "Ihr habt bereits zehn getötet? H...hah! Während Ihr unterwegs wart, habe ich meinen bisherigen Rekord gebrochen! Jetzt steht er auf zehn...hundert! Ja, zehnhundert Eber!\n\nEine Wette ist eine Wette...hier ist Euer Trostpreis, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27017] = { id = 27017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an längst vergangene Zeiten", description = "Schon komisch, an was man sich so erinnert. Ich habe 16 Stunden am Tag auf den Feldern gearbeitet und an jedem siebten Tag bin ich in das geschäftige Andorhal gegangen, um das, was ich angebaut hatte, zu verkaufen. Es war ein hartes Leben, aber wir kamen zurecht.\n\nDoch ich erinnere mich kaum daran. Wenn ich an die Zeit zurückdenke, fällt mir Glorias Lächeln ein - oder wie Andrea mir aus dem Fenster zugewinkt hat, wenn ich von dem Pflug aufsah.\n\nDer Hof ist etwas östlich von hier, aber ich bin nicht sicher, ob ich schon bereit bin, dorthin zurückzukehren, {name}. Ich möchte nur diese Erinnerungen nicht verlieren.", sourceObjective = "Begebt Euch zum Hof in Gahrrons Trauerfeld und sammelt alle Erinnerungsstücke, die Ihr finden könnt.", progress = "Ich möchte Euch nicht mit den Launen eines nostalgischen alten Mannes belästigen, {name}, aber solltet Ihr in der Gegend sein...", completion = "Dies... Gloria hat jeden Abend aus diesem Gebetsbuch gelesen! Wie konnte ich das nur vergessen? Sie war so fromm, {name}.\n\n\n\nOh...\n\nDieses Bild... meine Tochter, Andrea... sie hat so gerne gemalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27019] = { id = 27019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel der Hügel", description = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber irgendjemand muss es ja tun und ich bezweifle ernsthaft, dass noch andere Abenteurer ihren Weg an diesen hoffnungslosen Ort finden werden.", sourceObjective = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", progress = "Ich schere mich nicht um Politik; mich interessiert nicht, ob Ihr Euch auf die Seite der Horde oder der Allianz schlagt. Ich bin eher daran interessiert, direkte und schreckliche Drohungen gegen alle Völker auszuschalten... und das hier ist eine ziemlich große.\n\nWenn Ihr willens seid, für alle Völker ein wahrer Held zu sein, dann übergebt mir den Schwurstein, den ich Euch gab, als Zeichen der Verpflichtung. Ich bin... nicht aus dieser Gegend, ein Schwurstein bedeutet für Leute wie mich ein Bund der Übereinkunft.", completion = "Phantastisch, ich dachte schon, dass Ihr heldenmutig ausseht! Ich will Euch nicht anlügen, {name}, wir haben eine Menge Arbeit vor uns. Wenn wir uns auf die vor uns liegende Aufgabe konzentrieren, sollten wir in der Lage sein, als Sieger aus der Sache hervorzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27020] = { id = 27020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Lektion", description = "Die Zeit für Eure erste Unterweisung in den Gebräuchen eines Kriegers ist gekommen, {name}, und es ist eine sehr passende Lektion. Ich werde Euch eine Kampftechnik beibringen, mit der Ihr gleich zu Beginn eines Kampfes die Oberhand gewinnt.\n\nStürmt mitten ins Getümmel, überrascht Euren Feind und betäubt ihn. Wenn wir die Lehrstunde beendet haben, möchte ich, dass Ihr das alleine ausprobiert.", sourceObjective = "Lernt von Harutt Donnerhorn 'Sturmangriff'. Findet eine Trainingsattrappe in Camp Narache und übt 'Sturmangriff'.", sourceObjectiveStatus = "unverified-source-field" }
quests[27021] = { id = 27021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Es ist Zeit für Eure erste Lehrstunde, {name}. Vor Euch liegt noch ein langer Weg, bis Ihr die Gebräuche der Jäger beherrscht, aber jede neue Fähigkeit ist ein weiterer Schritt auf diesem Weg. Lasst mich Euch einen nützlichen Schuss zeigen.\n\nWenn wir die Lehrstunde beendet haben, möchte ich, dass Ihr ihn alleine ausprobiert.", sourceObjective = "Lernt von Lanka Weitschuss 'Zuverlässiger Schuss'. Findet eine Trainingsattrappe in Camp Narache und übt 'Zuverlässiger Schuss' 5 Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27022] = { id = 27022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausschalten des Götzen", description = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; sie... sie verzehren buchstäblich die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und ihn unbrauchbar machen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. \n\nSteht Ihr mir bei? Kann ich auf Eure Hilfe zählen, um diesen Gräßlichkeiten ein Ende zu bereiten?", sourceObjective = "Beschützt Belnistrasz.", completion = "Belnistrasz' plötzlicher Abgang hat eine brennende Kohlenpfanne hinterlassen. Während Ihr in die Flammen starrt, erfüllt das Bild eines roten Großdrachen mit riesigen Flügeln Euren Geist. Eine rauere Version von Belnistrasz' Stimme spricht direkt zu Euch.\n\n\"Wahrlich, sterbliche Wesen, Ihr seid die Helden, die ich mir erhofft hatte. Dank Euch gehören die Schlächtereien, die diese Bestien begangen haben, der Vergangenheit an. Mein Glaube an Wesen wie Euch ist wieder einmal erneuert worden. Nehmt dies als Belohnung, die eines Helden würdig ist.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[27023] = { id = 27023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Sonnenwandlers", description = "Es ist immer ein Vergnügen, einen anderen Sonnenwandler zu treffen. Von uns gibt es nicht so viele wie von den älteren Orden, aber unsere Wege sind nicht weniger mächtig und unsere Mitglieder werden nicht weniger respektiert.\n\nErlaubt mir, Euch eine unserer grundlegendsten Techniken beizubringen - Siegel und Richturteile. Wenn Ihr das Siegel der Rechtschaffenheit verwendet, könnt Ihr zusätzlichen Heiligschaden bei jedem Schlag verursachen. Außerdem könnt Ihr regelmäßig 'Richturteil' verwenden, um Eurem Gegner zusätzlichen Schaden zuzufügen.\n\nVersucht es selbst.", sourceObjective = "Lernt Siegel der Rechtschaffenheit und Richturteil von Sonnenwandler Helaku. Findet eine Trainingsattrappe in Camp Narache und übt die Anwendung von 'Richturteil'.", sourceObjectiveStatus = "unverified-source-field" }
quests[27024] = { id = 27024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komplizen", description = "Obwohl Amnennar hier die größte Bedrohung darstellt, ist er beileibe nicht die einzige. Ihr müsst auch seine Leutnants erschlagen, wenn ihre Umklammerung der Niederungen aufhören soll.\n\nNimmersatt bewacht den Anfang der Dornenspirale.\n\nMordesh steht oben auf dem Knochenhaufen und wiegelt die Geißel zu blinder Wut auf.\n\nTuten'kash befindet sich unter der Erde. Um ihn herauszulocken, müsst Ihr den Gong in der Kammer des Rufers drei Mal schlagen.\n\nViel Glück, tapferer Held.", sourceObjective = "Tötet, Nimmersatt, Mordresh Feuerauge und Tuten'kash.", completion = "Gut gemacht! Ohne ihre Anführer ist die Geißel keine nennenswerte Bedrohung mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[27025] = { id = 27025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disteln im Dickicht", description = "Es ist die Jahreszeit der Dolchdisteln! Dolchdistelsamen sind für 89% der durch Samen verursachten Verletzungen bei Jägern verantwortlich.\n\nIhr werdet Dolchdistelsamen zum größten Teil in den unteren Waldländern nördlich der Jagdhütte finden. Man findet sie gewöhnlich auf dem Boden bei Bäumen und sie werden Euch stechen und Schmerzen zufügen.\n\nIch würde Euch ja den Rat geben, einen Bogen um sie zu machen, aber ich brauche jemanden, der mir hilft, sie aus Sicherheitsgründen zu entfernen. Bringt mir Dolchdistelsamen, damit andere sich nicht verletzen.", sourceObjective = "Sammelt 6 Dolchdistelsamen.", progress = "Ihr müsst sie mit größter Vorsicht behandeln!", completion = "Ich habe gehört, dass es für die Waldländer auch eine Bärenwarnung gibt. Bären lieben diese Dolchdistelsamen.\n\nGut, dass Ihr sie gesammelt habt, damit sie nicht noch mehr Bären anziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27026] = { id = 27026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alarmstufe: Rotluchs", description = "Lasst alles stehen und liegen! Es ist mir zu Ohren gekommen, dass in der Nähe der Jagdhütte Rotluchse gesehen wurden. Rotluchse!\n\nIch habe zwar noch nie einen Rotluchs gesehen, aber sie sind bestimmt gefährlich. Sie sind wie Berglöwen oder so ähnlich. Ich will nicht, dass jemand fortgeht, bevor die Gegend nicht gesichert ist.\n\nAußer Euch, heißt das. Ich werde Euch dafür bezahlen, die Gegend zu sichern, {class}. Aber lasst Euch nicht in Stücke reißen.", sourceObjective = "Tötet 8 Rotluchse.", completion = "Also gut, ja, man hat mich informiert, dass die Rotluchse viel kleiner sind, als zunächst angenommen. Aber für Gnome ist das immer noch ganz schön gefährlich!\n\nIhr habt Euch um die Sicherheit diese Hütte verdient gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
